// AUTO-GENERATED by scripts/build-api-docs.mjs from /docs. Do not edit; run `npm run gen:docs -w aaira-gallery`.
const area: Record<string, Record<string, string>> = {"react-installation-and-peer-dependencies":{"overview":"<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">powershell</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-powershell\"><span class=\"tok-f\">npm</span> install @wf-controls/react @wf-controls/core react</code></pre></div>\n<p>From <code>packages/react/package.json</code>:</p>\n<div class=\"table-scroll\"><table><thead><tr><th>Field</th><th>Value</th><th>Notes</th></tr></thead><tbody><tr><td><code>peerDependencies</code></td><td><code>react &gt;= 18</code></td><td>You must install React yourself.</td></tr><tr><td><code>dependencies</code></td><td><code>@wf-controls/core 1.0.0</code></td><td>Installed automatically; also pulls <code>@wf-controls/data</code>.</td></tr><tr><td><code>devDependencies</code></td><td><code>@types/react ^18.3.0</code>, <code>typescript ^6.0.2</code></td><td><strong>Not</strong> peers. Install <code>@types/react</code> in your app for typings.</td></tr><tr><td>Module format</td><td><code>&quot;type&quot;: &quot;module&quot;</code>, <code>main: dist/index.js</code>, <code>types: dist/index.d.ts</code></td><td>ESM only. Compiled with <code>jsx: react-jsx</code> (needs <code>react/jsx-runtime</code>, React 17+ -- satisfied by the <code>&gt;=18</code> peer).</td></tr></tbody></table></div>\n<p>You will normally import controllers from <code>@wf-controls/core</code> and components from <code>@wf-controls/react</code>:</p>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">tsx</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-tsx\"><span class=\"tok-k\">import</span> { <span class=\"tok-t\">GridViewController</span> } <span class=\"tok-k\">from</span> <span class=\"tok-s\">&quot;@wf-controls/core&quot;</span>;\n<span class=\"tok-k\">import</span> { <span class=\"tok-t\">WebFormsGridView</span> } <span class=\"tok-k\">from</span> <span class=\"tok-s\">&quot;@wf-controls/react&quot;</span>;</code></pre></div>\n<p><strong>Styling.</strong> The package ships <strong>no CSS</strong>. Several components emit Bootstrap 5 class names (<code>nav-tabs</code>, <code>modal</code>, <code>breadcrumb</code>, <code>navbar</code>, <code>form-control-sm</code>, ...). Without Bootstrap those classes do nothing; the Modal in particular relies on inline style plus Bootstrap's <code>modal</code>/<code>d-block</code> classes for layout (see section 9). The sister package <code>@wf-controls/styles</code> supplies themes for these class names, including the Modal, Repeater and DataList (section 14).</p>\n<hr>\n"},"react-which-package-do-i-use":{"overview":"<div class=\"table-scroll\"><table><thead><tr><th>You want to...</th><th>Use</th><th>Notes</th></tr></thead><tbody><tr><td>Run grid/paging/sort/edit/validation logic in Node, a worker, a test, or any non-UI code</td><td><code>@wf-controls/core</code></td><td>Zero DOM dependencies. See section 3.</td></tr><tr><td>Use the in-memory ADO.NET layer (<code>DataTable</code>, <code>DataView</code>, <code>DataSet</code>) on its own</td><td><code>@wf-controls/data</code></td><td>Re-exported by <code>@wf-controls/core</code>, so most apps only need core.</td></tr><tr><td>Render a GridView / Repeater / DataList in React</td><td><code>@wf-controls/react</code> + <code>@wf-controls/core</code></td><td>Adapter takes a controller instance.</td></tr><tr><td>Render a Menu / Breadcrumb / TreeView in React</td><td><code>@wf-controls/react</code> (+ core controllers if you want data binding or site maps)</td><td>Components are props-driven; core controllers feed them (examples 8).</td></tr><tr><td>Render a modal or tabs in React</td><td><code>@wf-controls/react</code></td><td>Optional <code>ModalBehavior</code> / <code>TabsController</code> from core.</td></tr><tr><td>Render a login, sign-up, change-password or recovery form in React</td><td><code>@wf-controls/react</code> + <code>@wf-controls/core</code></td><td>Section 10A; pass <code>className=&quot;lg-&lt;theme&gt;&quot;</code>.</td></tr><tr><td>Render a GridView / Repeater in Angular</td><td><code>@wf-controls/angular</code> + <code>@wf-controls/core</code></td><td>See <code>angular-adapters.md</code>: grid, repeater, data list, tabs, modal, tree, breadcrumb, menu and the account family.</td></tr><tr><td>Anything in Angular that has no adapter (DataList, Menu, Tree, Tabs, Modal, validators...)</td><td><code>@wf-controls/core</code> controllers + your own template</td><td>See <code>angular-adapters.md</code>.</td></tr><tr><td>Use jQuery / plain HTML</td><td><code>@wf-controls/core</code> directly</td><td>There is no jQuery package; wrap the controllers yourself (see the JavaScript/HTML guide).</td></tr><tr><td>Theme the controls</td><td><code>@wf-controls/styles</code></td><td>Five themes for GridView (incl. edit rows), Login family, Menu, TreeView, Tabs, Navigation, Validation, Modal, Repeater and DataList. Load <code>&lt;theme&gt;-full.css</code>. See section 14.</td></tr></tbody></table></div>\n<hr>\n"},"react-using-the-headless-core-without-an-adapter":{"overview":"<p>Controllers are framework independent. The only contract an adapter needs is <code>stateChanged</code>: an <code>EventDispatcher&lt;this, { reason: string }&gt;</code> whose <code>subscribe(handler)</code> returns an unsubscribe function. All state-changing controller methods are <code>async</code> and emit <code>stateChanged</code> after they finish.</p>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">typescript</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-typescript\"><span class=\"tok-k\">import</span> { <span class=\"tok-t\">GridViewController</span> } <span class=\"tok-k\">from</span> <span class=\"tok-s\">&quot;@wf-controls/core&quot;</span>;\n\n<span class=\"tok-k\">interface</span> <span class=\"tok-t\">Order</span> { id: number; customer: string; total: number; }\n\n<span class=\"tok-k\">const</span> grid = <span class=\"tok-k\">new</span> <span class=\"tok-t\">GridViewController</span>&lt;<span class=\"tok-t\">Order</span>&gt;({\n  id: <span class=\"tok-s\">&quot;orders&quot;</span>, dataKeyField: <span class=\"tok-s\">&quot;id&quot;</span>, allowPaging: <span class=\"tok-k\">true</span>, pageSize: <span class=\"tok-n\">2</span>, allowSorting: <span class=\"tok-k\">true</span>,\n  dataSource: [\n    { id: <span class=\"tok-n\">1</span>, customer: <span class=\"tok-s\">&quot;Ann&quot;</span>, total: <span class=\"tok-n\">30</span> },\n    { id: <span class=\"tok-n\">2</span>, customer: <span class=\"tok-s\">&quot;Bob&quot;</span>, total: <span class=\"tok-n\">10</span> },\n    { id: <span class=\"tok-n\">3</span>, customer: <span class=\"tok-s\">&quot;Cy&quot;</span>, total: <span class=\"tok-n\">20</span> }\n  ],\n  columns: [\n    { <span class=\"tok-k\">type</span>: <span class=\"tok-s\">&quot;bound&quot;</span>, key: <span class=\"tok-s\">&quot;customer&quot;</span>, dataField: <span class=\"tok-s\">&quot;customer&quot;</span>, headerText: <span class=\"tok-s\">&quot;Customer&quot;</span>, sortable: <span class=\"tok-k\">true</span> },\n    { <span class=\"tok-k\">type</span>: <span class=\"tok-s\">&quot;bound&quot;</span>, key: <span class=\"tok-s\">&quot;total&quot;</span>, dataField: <span class=\"tok-s\">&quot;total&quot;</span>, headerText: <span class=\"tok-s\">&quot;Total&quot;</span>, sortable: <span class=\"tok-k\">true</span> }\n  ]\n});\n\ngrid.rowDeleting.<span class=\"tok-f\">subscribe</span>((_sender, e) =&gt; { <span class=\"tok-k\">if</span> (e.dataItem.total &gt; <span class=\"tok-n\">25</span>) e.cancel = <span class=\"tok-k\">true</span>; });\n<span class=\"tok-k\">const</span> off = grid.stateChanged.<span class=\"tok-f\">subscribe</span>((_s, { reason }) =&gt; {\n  console.<span class=\"tok-f\">log</span>(reason, grid.visibleRows.<span class=\"tok-f\">map</span>((r) =&gt; r.customer));\n});\n\n<span class=\"tok-k\">await</span> grid.<span class=\"tok-f\">dataBind</span>();\n<span class=\"tok-k\">await</span> grid.<span class=\"tok-f\">sort</span>(<span class=\"tok-s\">&quot;total&quot;</span>, <span class=\"tok-s\">&quot;desc&quot;</span>);\n<span class=\"tok-k\">await</span> grid.<span class=\"tok-f\">changePage</span>(<span class=\"tok-n\">1</span>);\n<span class=\"tok-k\">await</span> grid.<span class=\"tok-f\">executeCommand</span>(<span class=\"tok-n\">2</span>, <span class=\"tok-s\">&quot;Edit&quot;</span>);\n<span class=\"tok-k\">await</span> grid.<span class=\"tok-f\">updateRow</span>(<span class=\"tok-n\">2</span>, { total: <span class=\"tok-n\">99</span> });\n<span class=\"tok-f\">off</span>();</code></pre></div>\n<p>A minimal re-render hook for your own React components (this is exactly what the adapters do internally; the package does <strong>not</strong> export it):</p>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">tsx</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-tsx\"><span class=\"tok-k\">import</span> { useEffect, useReducer } <span class=\"tok-k\">from</span> <span class=\"tok-s\">&quot;react&quot;</span>;\n\n<span class=\"tok-k\">export</span> <span class=\"tok-k\">function</span> useController&lt;<span class=\"tok-t\">C</span> <span class=\"tok-k\">extends</span> { stateChanged: { <span class=\"tok-f\">subscribe</span>(h: () =&gt; <span class=\"tok-k\">void</span>): () =&gt; unknown } }&gt;(c: <span class=\"tok-t\">C</span>): <span class=\"tok-t\">C</span> {\n  <span class=\"tok-k\">const</span> [, refresh] = <span class=\"tok-f\">useReducer</span>((n: number) =&gt; n + <span class=\"tok-n\">1</span>, <span class=\"tok-n\">0</span>);\n  <span class=\"tok-f\">useEffect</span>(() =&gt; { <span class=\"tok-k\">const</span> off = c.stateChanged.<span class=\"tok-f\">subscribe</span>(() =&gt; <span class=\"tok-f\">refresh</span>()); <span class=\"tok-k\">return</span> () =&gt; { <span class=\"tok-f\">off</span>(); }; }, [c]);\n  <span class=\"tok-k\">return</span> c;\n}</code></pre></div>\n<hr>\n"},"react-export-inventory":{"overview":"<p><code>packages/react/src/index.ts</code> re-exports everything from ten modules. There are <strong>no hooks, contexts or helper functions</strong> exported; only components and their prop/type interfaces.</p>\n<div class=\"table-scroll\"><table><thead><tr><th>Export</th><th>Kind</th><th>Wraps / uses</th></tr></thead><tbody><tr><td><code>WebFormsGridView</code>, <code>WebFormsGridViewProps&lt;T&gt;</code></td><td>generic function component + props</td><td><code>GridViewController&lt;T&gt;</code></td></tr><tr><td><code>WebFormsRepeater</code>, <code>WebFormsRepeaterProps&lt;T&gt;</code></td><td>generic function component + props</td><td><code>RepeaterController&lt;T&gt;</code></td></tr><tr><td><code>WebFormsDataList</code>, <code>WebFormsDataListProps&lt;T&gt;</code></td><td>generic function component + props</td><td><code>DataListController&lt;T&gt;</code></td></tr><tr><td><code>NavigationMenu</code>, <code>NavigationMenuProps</code></td><td><code>React.FC</code></td><td>optional <code>MenuController</code> (or plain <code>items</code>)</td></tr><tr><td><code>Breadcrumb</code>, <code>BreadcrumbProps</code>, <code>BreadcrumbItem</code></td><td><code>React.FC</code> + types</td><td>optional <code>SiteMapPathController</code> (or plain <code>items</code>)</td></tr><tr><td><code>TreeView</code>, <code>TreeViewProps</code>, <code>TreeNode</code> (interface)</td><td><code>React.FC</code> + types</td><td>optional <code>TreeViewController</code> (or plain <code>nodes</code>)</td></tr><tr><td><code>WebFormsTabs</code>, <code>WebFormsTabsProps</code>, <code>TabDefinition</code></td><td><code>React.FC</code> + types</td><td>optional <code>TabsController</code></td></tr><tr><td><code>WebFormsModal</code>, <code>WebFormsModalProps</code></td><td><code>React.FC</code> + type</td><td>optional <code>ModalBehavior</code></td></tr><tr><td><code>WebFormsLogin</code>, <code>WebFormsLoginStatus</code>, <code>WebFormsLoginName</code>, <code>WebFormsLoginView</code> (+ <code>...Props</code>)</td><td><code>React.FC</code> + props</td><td><code>LoginController</code>, <code>LoginStatusController</code>, <code>LoginNameController</code>, <code>LoginViewController</code> (section 10A)</td></tr><tr><td><code>WebFormsChangePassword</code>, <code>WebFormsPasswordRecovery</code>, <code>WebFormsCreateUserWizard</code> (+ <code>...Props</code>)</td><td><code>React.FC</code> + props</td><td><code>ChangePasswordController</code>, <code>PasswordRecoveryController</code>, <code>CreateUserWizardController</code> (section 10A)</td></tr></tbody></table></div>\n<blockquote class=\"\"><p><strong>Name clash.</strong> The adapter's <code>TreeNode</code> <strong>interface</strong> (<code>{ text, value?, navigateUrl?, expanded?, selected?, children? }</code>) is unrelated to the core <code>TreeNode</code> <strong>class</strong> (<code>childNodes</code>, not <code>children</code>). Import one under an alias if you use both (example 8 does <code>type TreeNode as CoreTreeNode</code>).</p></blockquote>\n<hr>\n"},"react-webformsgridview":{"overview":"<p>Renders a <code>&lt;table&gt;</code> for a <code>GridViewController&lt;T&gt;</code> with ASP.NET-style markup that the <code>@wf-controls/styles</code> kit (<code>table.gv-&lt;theme&gt;</code>) styles directly: header with sortable column links (<code>aria-sort</code>), body rows (normal / alternating / selected / editing), an optional <code>tr.footer</code>, an empty-data row, and a <code>tr.pager</code> row with Previous / numbered links / Next. See <a href=\"#/api/adapters/react-styling-with-wf-controls-styles/overview/14-styling-with-wf-controlsstyles\">section 14</a>.</p>\n","how-it-observes-state":"<h3 id=\"51-how-it-observes-state\">5.1 How it observes state<a class=\"anchor\" href=\"#51-how-it-observes-state\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">text</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-text\">useEffect(() =&gt; controller.stateChanged.subscribe(() =&gt; refresh()), [controller])</code></pre></div>\n<p>Any controller method that calls its internal <code>notify()</code> (<code>dataBind</code>, <code>beginEdit</code>, <code>updateRow</code>, <code>cancelEdit</code>, <code>deleteRow</code>, <code>selectRow</code>, <code>changePage</code>, <code>sort</code>) triggers a re-render. The component reads <code>controller.options</code>, <code>controller.visibleRows</code>, <code>controller.pageCount</code> directly on each render. It <strong>never calls <code>dataBind()</code> for you</strong> -- bind the controller yourself (typically in a <code>useEffect</code>), otherwise the empty-data row is shown.</p>\n<p>Caveat: <code>controller.options</code> is mutated in place (<code>editIndex</code>, <code>pageIndex</code>, <code>selectedIndex</code>). Mutating options directly from outside (e.g. <code>grid.options.pageSize = 5</code>) does <strong>not</strong> emit <code>stateChanged</code>; call a controller method (or <code>dataBind()</code>) afterward.</p>\n","props":"<h3 id=\"52-props\">5.2 Props<a class=\"anchor\" href=\"#52-props\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Prop</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>controller</code></td><td><code>GridViewController&lt;T&gt;</code></td><td>yes</td><td>--</td><td>Controller to render. <code>T extends object</code>. Re-subscribes if the instance changes.</td></tr><tr><td><code>className</code></td><td><code>string</code></td><td>no</td><td><code>cssClass</code> + <code>tableCssClass</code> (space-joined)</td><td>CSS class of the <strong><code>&lt;table&gt;</code></strong> (not the wrapper). When given it replaces the joined <code>cssClass</code> / <code>tableCssClass</code> on the table only. Put the kit theme here (<code>gv-modern</code>) or in <code>cssClass</code>.</td></tr><tr><td><code>style</code></td><td><code>React.CSSProperties</code></td><td>no</td><td>--</td><td>Inline style of the <code>&lt;table&gt;</code>.</td></tr><tr><td><code>template</code></td><td><code>(key: string, row: T, index: number) =&gt; ReactNode</code></td><td>no</td><td>--</td><td>Renders cells of columns with <code>type: &quot;template&quot;</code>. <code>key</code> = column <code>key</code>; <code>index</code> = <strong>absolute</strong> row index (page offset included). If omitted, template cells are empty. Also used as the display fallback in edit mode.</td></tr><tr><td><code>editCellTemplate</code></td><td><code>(key, row, index, editValues, setEditValue, save, cancel) =&gt; ReactNode</code></td><td>no</td><td>--</td><td>Per-cell edit renderer, called for every visible column of the row being edited. Return <code>null</code>/<code>undefined</code> to fall back to the built-in editor (see 5.5).</td></tr><tr><td><code>editTemplate</code></td><td><code>(row: T, index: number, save: (values: Partial&lt;T&gt;) =&gt; Promise&lt;boolean&gt;, cancel: () =&gt; Promise&lt;boolean&gt;) =&gt; ReactNode</code></td><td>no</td><td>--</td><td>Full-row editor. When present and the row is being edited, the whole row is replaced by one <code>&lt;td colSpan&gt;</code> containing this node. Takes precedence over <code>editCellTemplate</code>.</td></tr></tbody></table></div>\n<p><code>editCellTemplate</code> argument detail:</p>\n<div class=\"table-scroll\"><table><thead><tr><th>Arg</th><th>Type</th><th>Meaning</th></tr></thead><tbody><tr><td><code>key</code></td><td><code>string</code></td><td>Column <code>key</code>.</td></tr><tr><td><code>row</code></td><td><code>T</code></td><td>Row data (not yet modified).</td></tr><tr><td><code>index</code></td><td><code>number</code></td><td>Absolute row index.</td></tr><tr><td><code>editValues</code></td><td><code>Partial&lt;T&gt;</code></td><td>Pending (uncommitted) values for this row, held in component state.</td></tr><tr><td><code>setEditValue</code></td><td><code>(field: string, val: unknown) =&gt; void</code></td><td>Stage a value.</td></tr><tr><td><code>save</code></td><td><code>() =&gt; Promise&lt;boolean&gt;</code></td><td>Calls <code>controller.updateRow(index, editValues)</code>. Resolves <code>false</code> if cancelled/invalid.</td></tr><tr><td><code>cancel</code></td><td><code>() =&gt; Promise&lt;boolean&gt;</code></td><td>Clears staged values and calls <code>controller.cancelEdit()</code>.</td></tr></tbody></table></div>\n","column-and-controller-options-that-matter":"<h3 id=\"53-column-and-controller-options-that-matter\">5.3 Column and controller options that matter<a class=\"anchor\" href=\"#53-column-and-controller-options-that-matter\" aria-label=\"Link to this section\">#</a></h3>\n<p>The component has no column props; columns come from <code>controller.options.columns</code>:</p>\n<div class=\"table-scroll\"><table><thead><tr><th>Column field</th><th>Effect in the adapter</th></tr></thead><tbody><tr><td><code>type: &quot;bound&quot;</code></td><td>Renders <code>String(row[dataField] ?? &quot;&quot;)</code> or <code>format(value, row)</code>. Eligible for sort button and default text input in edit mode.</td></tr><tr><td><code>type: &quot;template&quot;</code></td><td>Renders <code>template(key, row, absoluteIndex)</code>. Never sortable.</td></tr><tr><td><code>visible: false</code></td><td>Column is filtered out of header, body and footer.</td></tr><tr><td><code>sortable</code></td><td>With <code>options.allowSorting</code>, the header text becomes an <code>&lt;a href=&quot;#&quot; role=&quot;button&quot;&gt;</code> calling <code>controller.sort(dataField)</code>; the <code>&lt;th&gt;</code> gets <code>aria-sort</code> (<code>ascending</code> / <code>descending</code> / <code>none</code>).</td></tr><tr><td><code>headerText</code></td><td>Header text.</td></tr></tbody></table></div>\n<div class=\"table-scroll\"><table><thead><tr><th>Controller option</th><th>Effect</th></tr></thead><tbody><tr><td><code>showHeader</code> (default <code>true</code>)</td><td>Renders <code>&lt;thead&gt;</code>.</td></tr><tr><td><code>showFooter</code> (default <code>false</code>)</td><td>Renders <code>tr.footer</code> (plus <code>footerCssClass</code>) in the <code>&lt;tfoot&gt;</code> with <strong>empty</strong> <code>&lt;td&gt;</code> per column (no footer content API).</td></tr><tr><td><code>emptyDataText</code> (default <code>&quot;No records found.&quot;</code>)</td><td>Text of the empty row (<code>colSpan</code> = visible column count).</td></tr><tr><td><code>allowPaging</code>, <code>pageSize</code>, <code>pageIndex</code></td><td>The pager row is shown whenever <code>allowPaging</code> is true, even for a single page (Previous and Next are then disabled spans).</td></tr><tr><td><code>cssClass</code>, <code>tableCssClass</code></td><td>Both go on the <code>&lt;table&gt;</code>; <code>cssClass</code> also goes on the wrapper <code>&lt;div&gt;</code>.</td></tr><tr><td><code>rowCssClass</code>, <code>alternatingRowCssClass</code>, <code>selectedRowCssClass</code>, <code>editRowCssClass</code>, <code>headerCssClass</code>, <code>footerCssClass</code>, <code>pagerCssClass</code></td><td>Applied as described in 5.4.</td></tr><tr><td><code>editIndex</code>, <code>selectedIndex</code></td><td>Absolute indices driving row classes / edit mode.</td></tr><tr><td><code>dataKeyField</code></td><td>Used for React <code>key</code> (<code>String(getDataKey(row))</code>). <strong>Keep keys unique</strong>; duplicate keys give React warnings and bad reconciliation.</td></tr></tbody></table></div>\n","markup-and-styling-hooks":"<h3 id=\"54-markup-and-styling-hooks\">5.4 Markup and styling hooks<a class=\"anchor\" href=\"#54-markup-and-styling-hooks\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">html</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-html\"><span class=\"tok-t\">&lt;div</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;{options.cssClass}&quot;</span>&gt;\n  <span class=\"tok-t\">&lt;table</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;{className ?? (cssClass + ' ' + tableCssClass)}&quot;</span><span class=\"tok-k\"> style</span>=<span class=\"tok-s\">&quot;{style}&quot;</span>&gt;\n    <span class=\"tok-t\">&lt;thead</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;{headerCssClass}&quot;</span>&gt;<span class=\"tok-t\">&lt;tr</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;{headerCssClass}&quot;</span>&gt;\n      <span class=\"tok-t\">&lt;th</span><span class=\"tok-k\"> scope</span>=<span class=\"tok-s\">&quot;col&quot;</span><span class=\"tok-k\"> aria-sort</span>=<span class=\"tok-s\">&quot;ascending|descending|none&quot;</span>&gt;<span class=\"tok-t\">&lt;a</span><span class=\"tok-k\"> href</span>=<span class=\"tok-s\">&quot;#&quot;</span><span class=\"tok-k\"> role</span>=<span class=\"tok-s\">&quot;button&quot;</span>&gt;Name<span class=\"tok-t\">&lt;/a</span>&gt;<span class=\"tok-t\">&lt;/th</span>&gt;\n      <span class=\"tok-t\">&lt;th</span><span class=\"tok-k\"> scope</span>=<span class=\"tok-s\">&quot;col&quot;</span>&gt;Plain header<span class=\"tok-t\">&lt;/th</span>&gt;\n    <span class=\"tok-t\">&lt;/tr</span>&gt;<span class=\"tok-t\">&lt;/thead</span>&gt;\n    <span class=\"tok-t\">&lt;tbody</span>&gt;\n      <span class=\"tok-t\">&lt;tr</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;{row class}&quot;</span><span class=\"tok-k\"> aria-selected</span>=<span class=\"tok-s\">&quot;true&quot;</span>&gt;<span class=\"tok-t\">&lt;td</span>&gt;...<span class=\"tok-t\">&lt;/td</span>&gt;<span class=\"tok-t\">&lt;/tr</span>&gt;\n      <span class=\"tok-c\">&lt;!-- empty: &lt;tr class=&quot;empty&quot;&gt;&lt;td class=&quot;empty&quot; colspan=N&gt;emptyDataText&lt;/td&gt;&lt;/tr&gt; --&gt;</span>\n    <span class=\"tok-t\">&lt;/tbody</span>&gt;\n    <span class=\"tok-t\">&lt;tfoot</span>&gt;\n      <span class=\"tok-t\">&lt;tr</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;footer {footerCssClass}&quot;</span>&gt;<span class=\"tok-t\">&lt;td</span>&gt;<span class=\"tok-t\">&lt;/td</span>&gt;...<span class=\"tok-t\">&lt;/tr</span>&gt;                       <span class=\"tok-c\">&lt;!-- showFooter --&gt;</span>\n      <span class=\"tok-t\">&lt;tr</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;pager {pagerCssClass}&quot;</span>&gt;<span class=\"tok-t\">&lt;td</span><span class=\"tok-k\"> colspan</span>=N&gt;                            <span class=\"tok-c\">&lt;!-- allowPaging --&gt;</span>\n        <span class=\"tok-t\">&lt;a</span><span class=\"tok-k\"> href</span>=<span class=\"tok-s\">&quot;#&quot;</span><span class=\"tok-k\"> role</span>=<span class=\"tok-s\">&quot;button&quot;</span>&gt;Previous<span class=\"tok-t\">&lt;/a</span>&gt;  <span class=\"tok-t\">&lt;a</span><span class=\"tok-k\"> href</span>=<span class=\"tok-s\">&quot;#&quot;</span>&gt;1<span class=\"tok-t\">&lt;/a</span>&gt; <span class=\"tok-t\">&lt;span</span><span class=\"tok-k\"> aria-current</span>=<span class=\"tok-s\">&quot;page&quot;</span>&gt;2<span class=\"tok-t\">&lt;/span</span>&gt; <span class=\"tok-t\">&lt;a</span><span class=\"tok-k\"> href</span>=<span class=\"tok-s\">&quot;#&quot;</span>&gt;3<span class=\"tok-t\">&lt;/a</span>&gt;  <span class=\"tok-t\">&lt;a</span><span class=\"tok-k\"> href</span>=<span class=\"tok-s\">&quot;#&quot;</span><span class=\"tok-k\"> role</span>=<span class=\"tok-s\">&quot;button&quot;</span>&gt;Next<span class=\"tok-t\">&lt;/a</span>&gt;\n        <span class=\"tok-t\">&lt;span</span><span class=\"tok-k\"> style</span>=<span class=\"tok-s\">&quot;visually hidden&quot;</span>&gt;Page 2 of 3<span class=\"tok-t\">&lt;/span</span>&gt;\n      <span class=\"tok-t\">&lt;/td</span>&gt;<span class=\"tok-t\">&lt;/tr</span>&gt;\n    <span class=\"tok-t\">&lt;/tfoot</span>&gt;\n  <span class=\"tok-t\">&lt;/table</span>&gt;\n<span class=\"tok-t\">&lt;/div</span>&gt;</code></pre></div>\n<p>Row class is chosen in this priority order: editing row -&gt; <code>edit</code> + <code>editRowCssClass</code>; <code>rowIndex === selectedIndex</code> -&gt; <code>selected</code> + <code>selectedRowCssClass</code> (and <code>aria-selected=&quot;true&quot;</code>); odd visible index with <code>alternatingRowCssClass</code> set -&gt; <code>alternatingRowCssClass</code>; else <code>rowCssClass</code>. The kit defaults <code>edit</code>, <code>selected</code>, <code>footer</code>, <code>pager</code> and <code>empty</code> are always present, user classes are appended. An empty result becomes no <code>class</code> attribute.</p>\n<p>Details:</p>\n<ul><li>The pager lists a window of at most 10 page numbers around the current page. The current page is a <code>&lt;span aria-current=&quot;page&quot;&gt;</code>; a disabled Previous/Next is <code>&lt;span class=&quot;aspNetDisabled&quot;&gt;</code>. A visually hidden &quot;Page X of Y&quot; is included for assistive technology.</li><li><code>cssClass</code> lands on <strong>both</strong> the wrapper <code>&lt;div&gt;</code> and the <code>&lt;table&gt;</code> (the table also gets <code>tableCssClass</code>). For the kit this is intended: <code>cssClass: &quot;gv-modern&quot;</code> styles the table. Without the kit, set <code>tableCssClass</code> (or the <code>className</code> prop) if you do not want <code>table</code> classes on a <code>&lt;div&gt;</code>.</li><li>Alternation is by position on the <strong>page</strong> (<code>visibleIndex % 2</code>), not the absolute index.</li><li>The <code>Previous</code> / <code>Next</code> / <code>Page x of y</code> strings are hard-coded English; there is no pager template or prop to localize them.</li><li>Template-column actions (Edit, Delete, ...) are yours: render them from the <code>template</code> prop. Use <code>&lt;a href=&quot;#&quot; className=&quot;btn-link&quot;&gt;</code> (add <code>text-danger</code> for Delete) and call <code>e.preventDefault()</code> so the kit styles them as links.</li><li>The kit's nested-table pager selector (<code>.pager table</code>) is not produced; see <a href=\"#/api/guides/issues-needs-your-attention-first\">Known issues</a>.</li></ul>\n","edit-mode-behaviour":"<h3 id=\"55-edit-mode-behaviour\">5.5 Edit-mode behaviour<a class=\"anchor\" href=\"#55-edit-mode-behaviour\" aria-label=\"Link to this section\">#</a></h3>\n<p>When <code>controller.options.editIndex</code> equals the absolute row index:</p>\n<ol><li>If <code>editTemplate</code> is provided -&gt; row replaced by <code>&lt;tr class=&quot;edit {editRowCssClass}&quot;&gt;&lt;td colSpan=N&gt;{editTemplate(...)}&lt;/td&gt;&lt;/tr&gt;</code>. <code>save(values)</code> = <code>controller.updateRow(index, values)</code>; <code>cancel</code> = the component's cancel (clears staged values, then <code>controller.cancelEdit()</code>).</li><li>Otherwise each visible cell calls <code>editCellTemplate</code> (if provided). A non-null/undefined return value wins.</li><li>Fallback per cell: <code>bound</code> column -&gt; <code>&lt;input type=&quot;text&quot; class=&quot;form-control form-control-sm&quot;&gt;</code> bound to the staged value (initial = row value); <code>template</code> column -&gt; the normal <code>template(...)</code> output.</li></ol>\n<p>Gotchas:</p>\n<ul><li><strong>You must render your own Update/Cancel buttons.</strong> The default editor shows only text inputs. Use <code>editCellTemplate</code> and return buttons for your actions column (example 2), or use <code>editTemplate</code>.</li><li>Staged values only contain <strong>fields the user changed</strong>; <code>save()</code> passes exactly those as <code>Partial&lt;T&gt;</code>. Values are always <strong>strings</strong> from the default <code>&lt;input type=&quot;text&quot;&gt;</code> (a numeric field will be saved as a string unless you convert it in <code>rowUpdating</code> or supply your own editor).</li><li>Staged values live in component state keyed by <code>rowIndex</code>. They are cleared on <code>cancel()</code>, after a successful <code>save()</code> and whenever no row is being edited, so they do not leak into a later edit session.</li><li>Edit state is tracked by absolute index; paging while editing keeps <code>editIndex</code> on the old absolute index (the editor simply disappears from view and reappears when you return to that page).</li><li><code>controller.options.causesValidation</code> / <code>validationGroup</code>: <code>updateRow</code> runs <code>ValidatorManager.validate(validationGroup)</code> first and returns <code>false</code> if invalid. The adapter does not display validation messages; render a <code>ValidationSummary</code> yourself.</li></ul>\n","command-flow-ui-controller":"<h3 id=\"56-command-flow-ui---controller\">5.6 Command flow (UI -&gt; controller)<a class=\"anchor\" href=\"#56-command-flow-ui---controller\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>UI action</th><th>Adapter call</th><th>Controller events (in order)</th></tr></thead><tbody><tr><td>Click sortable header link</td><td><code>controller.sort(dataField)</code></td><td><code>sorting</code> (cancellable, <code>e.sortExpression</code>, <code>e.direction</code>) -&gt; <code>sorted</code> -&gt; <code>stateChanged(&quot;sort&quot;)</code>. Toggles asc/desc on repeated clicks. Returns <code>false</code> if <code>allowSorting</code> is off.</td></tr><tr><td>Click Previous / Next / a page number</td><td><code>controller.changePage(pageIndex -/+ 1)</code> (or the chosen page)</td><td><code>pageIndexChanging</code> (cancellable) -&gt; <code>pageIndexChanged</code> -&gt; <code>stateChanged(&quot;changePage&quot;)</code>. Re-runs <code>dataBind()</code> first if the source is an <code>IDataSourceControl</code> (server-style paging).</td></tr><tr><td>Your <code>template</code> button: Edit / Delete / Select / Cancel</td><td><code>controller.executeCommand(absIndex, &quot;Edit&quot; ...)</code> (you call it)</td><td><code>rowCommand</code> first, then by case-insensitive name: <code>edit</code> -&gt; <code>beginEdit</code> (<code>rowEditing</code>), <code>delete</code> -&gt; <code>deleteRow</code> (<code>rowDeleting</code>, <code>rowDeleted</code>), <code>select</code> -&gt; <code>selectRow</code> (<code>selectedIndexChanging/Changed</code>), <code>cancel</code> -&gt; <code>cancelEdit</code> (<code>rowCancelingEdit</code>). Any other name only fires <code>rowCommand</code>.</td></tr><tr><td><code>save()</code> / <code>editTemplate</code> save</td><td><code>controller.updateRow(index, values)</code></td><td>validation (if <code>causesValidation</code>) -&gt; <code>rowUpdating</code> (cancellable, <code>e.values</code>) -&gt; data-source <code>update</code> (if <code>IDataSourceControl</code>) -&gt; <code>Object.assign</code> onto the row -&gt; <code>rowUpdated</code> -&gt; <code>stateChanged(&quot;updateRow&quot;)</code>. Resolves <code>false</code> when cancelled.</td></tr></tbody></table></div>\n<p>There are <strong>no callback props</strong> for these; subscribe to the controller events (<code>controller.rowUpdating.subscribe((sender, e) =&gt; ...)</code>). Note that <code>&quot;update&quot;</code> is <strong>not</strong> a recognised <code>executeCommand</code> name; save through <code>updateRow</code> / the <code>save</code> callbacks.</p>\n<hr>\n"},"react-webformsrepeater":{"overview":"<p>Renders each item of a <code>RepeaterController&lt;T&gt;</code> using your templates, with optional built-in &quot;Add item&quot; / &quot;Delete&quot; controls.</p>\n","state":"<h3 id=\"61-state\">6.1 State<a class=\"anchor\" href=\"#61-state\" aria-label=\"Link to this section\">#</a></h3>\n<p>Subscribes to <code>controller.stateChanged</code>. Returns <code>null</code> while <code>controller.isResetting</code> (between <code>beginResetItemTemplate()</code> / <code>endResetItemTemplate()</code>). Does <strong>not</strong> call <code>dataBind()</code> for you.</p>\n","props":"<h3 id=\"62-props\">6.2 Props<a class=\"anchor\" href=\"#62-props\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Prop</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>controller</code></td><td><code>RepeaterController&lt;T&gt;</code></td><td>yes</td><td>--</td><td>Controller.</td></tr><tr><td><code>className</code></td><td><code>string</code></td><td>no</td><td><code>controller.options.cssClass</code></td><td>Class of the outer <code>&lt;div&gt;</code>.</td></tr><tr><td><code>itemTemplate</code></td><td><code>(item, index, command) =&gt; ReactNode</code></td><td><strong>yes</strong></td><td>--</td><td>Renders a normal item. <code>command(name, argument?)</code> -&gt; <code>controller.executeCommand(index, name, argument)</code>.</td></tr><tr><td><code>alternatingItemTemplate</code></td><td>same as <code>itemTemplate</code></td><td>no</td><td>falls back to <code>itemTemplate</code></td><td>Used for odd indices (<code>index % 2 === 1</code>).</td></tr><tr><td><code>editItemTemplate</code></td><td><code>(item, index, save, cancel) =&gt; ReactNode</code></td><td>no</td><td>--</td><td>Used when <code>controller.editItemIndex === index</code>. <code>save(values)</code> -&gt; <code>controller.updateItem</code>, <code>cancel()</code> -&gt; <code>controller.cancelEdit()</code>. If omitted, edit mode has no visible effect (the item template is used).</td></tr><tr><td><code>headerTemplate</code></td><td><code>() =&gt; ReactNode</code></td><td>no</td><td>--</td><td>Rendered before the items.</td></tr><tr><td><code>footerTemplate</code></td><td><code>() =&gt; ReactNode</code></td><td>no</td><td>--</td><td>Rendered after the items.</td></tr><tr><td><code>separatorTemplate</code></td><td><code>() =&gt; ReactNode</code></td><td>no</td><td>--</td><td>Rendered inside each item wrapper after the content, except for the last item.</td></tr><tr><td><code>emptyTemplate</code></td><td><code>() =&gt; ReactNode</code></td><td>no</td><td><code>&lt;p&gt;{options.emptyText ?? &quot;No records found.&quot;}&lt;/p&gt;</code></td><td>Shown when <code>items.length === 0</code>. Header/footer are <strong>not</strong> rendered in the empty state.</td></tr><tr><td><code>createItem</code></td><td><code>() =&gt; T | Promise&lt;T&gt;</code></td><td>no</td><td>--</td><td>Factory for the built-in &quot;Add item&quot; button. Without it the button does nothing.</td></tr></tbody></table></div>\n<p>Template precedence per item: edit (if <code>editItemIndex === index</code> and <code>editItemTemplate</code>) &gt; alternating (odd index and <code>alternatingItemTemplate</code>) &gt; item.</p>\n","controller-options-used":"<h3 id=\"63-controller-options-used\">6.3 Controller options used<a class=\"anchor\" href=\"#63-controller-options-used\" aria-label=\"Link to this section\">#</a></h3>\n<p><code>cssClass</code>, <code>itemCssClass</code>, <code>alternatingItemCssClass</code>, <code>itemHeaderVisible</code> (default behaves as <code>true</code>: only <code>false</code> hides it), <code>allowUserToAddItems</code>, <code>allowUserToDeleteItems</code>, <code>emptyText</code>, <code>dataKeyField</code> (React key; falls back to index).</p>\n","markup-and-styling-hooks":"<h3 id=\"64-markup-and-styling-hooks\">6.4 Markup and styling hooks<a class=\"anchor\" href=\"#64-markup-and-styling-hooks\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">html</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-html\"><span class=\"tok-t\">&lt;div</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;wf-repeater {className ?? cssClass}&quot;</span>&gt;      <span class=\"tok-c\">&lt;!-- e.g. rp-modern --&gt;</span>\n  <span class=\"tok-t\">&lt;button</span><span class=\"tok-k\"> type</span>=<span class=\"tok-s\">&quot;button&quot;</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;add&quot;</span>&gt;Add item<span class=\"tok-t\">&lt;/button</span>&gt;  <span class=\"tok-c\">&lt;!-- only if allowUserToAddItems --&gt;</span>\n  {headerTemplate()}\n  <span class=\"tok-t\">&lt;div</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;wf-item {itemCssClass} [alt {alternatingItemCssClass}] [active] [edit]&quot;</span>&gt;   <span class=\"tok-c\">&lt;!-- one per item; click selects --&gt;</span>\n    <span class=\"tok-t\">&lt;header</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;wf-item-header&quot;</span>&gt;                    <span class=\"tok-c\">&lt;!-- unless itemHeaderVisible === false --&gt;</span>\n      <span class=\"tok-t\">&lt;span</span>&gt;Item N<span class=\"tok-t\">&lt;/span</span>&gt;\n      <span class=\"tok-t\">&lt;button</span><span class=\"tok-k\"> type</span>=<span class=\"tok-s\">&quot;button&quot;</span>&gt;Delete<span class=\"tok-t\">&lt;/button</span>&gt;            <span class=\"tok-c\">&lt;!-- only if allowUserToDeleteItems --&gt;</span>\n    <span class=\"tok-t\">&lt;/header</span>&gt;\n    {template output}{separatorTemplate()}\n  <span class=\"tok-t\">&lt;/div</span>&gt;\n  {footerTemplate()}\n<span class=\"tok-t\">&lt;/div</span>&gt;\n<span class=\"tok-c\">&lt;!-- empty state (no emptyTemplate): &lt;div class=&quot;empty&quot;&gt;{emptyText}&lt;/div&gt; --&gt;</span></code></pre></div>\n<ul><li><code>alt</code> is added on odd indices, <code>active</code> when <code>controller.currentItemIndex === index</code>, and <code>edit</code> when the item is rendered through <code>editItemTemplate</code>. These are the hooks the <code>rp-&lt;theme&gt;</code> family styles.</li><li>Theming: set <code>className=&quot;rp-modern&quot;</code> (or <code>cssClass: &quot;rp-modern&quot;</code> on the controller) and load <code>@wf-controls/styles/bundles/modern-full.css</code>. Inputs, selects, textareas, checkboxes, labels and buttons inside <code>.wf-item.edit</code> are styled; a button with class <code>add</code>, <code>save</code>, <code>primary</code>, <code>type=submit</code> or <code>data-command=Update|Save|Insert</code> (or the first button of the edit item) gets the accent colour, <code>delete</code> / <code>data-command=Delete</code> the danger colour.</li><li>&quot;Add item&quot;, &quot;Item N&quot; and &quot;Delete&quot; are hard-coded English with no props to change them. Set <code>itemHeaderVisible: false</code> to drop the header (and the built-in Delete button with it) and render your own controls.</li><li>No ARIA attributes or data attributes are emitted.</li></ul>\n","command-flow":"<h3 id=\"65-command-flow\">6.5 Command flow<a class=\"anchor\" href=\"#65-command-flow\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>UI action</th><th>Controller call</th></tr></thead><tbody><tr><td>Click anywhere on an item wrapper</td><td><code>controller.setCurrentItemIndex(index)</code> -&gt; <code>currentItemIndexChanged</code>, <code>stateChanged</code>. <strong>Bubbles from your buttons too</strong>, so your Edit button also selects the item. The built-in Delete button stops propagation.</td></tr><tr><td>Built-in Delete</td><td><code>controller.deleteItem(index)</code> (no cancellable event on the repeater; just <code>stateChanged(&quot;deleteItem&quot;)</code>)</td></tr><tr><td>Built-in Add</td><td><code>controller.addItem(await createItem())</code> -&gt; <code>onItemValuePushed</code>, <code>stateChanged(&quot;addItem&quot;)</code></td></tr><tr><td><code>command(&quot;Edit&quot;)</code></td><td><code>executeCommand</code> -&gt; <code>itemCommand</code>, then <code>beginEdit(index)</code> (<code>itemEditing</code> cancellable)</td></tr><tr><td><code>command(&quot;Select&quot;)</code></td><td><code>executeCommand</code> -&gt; <code>itemCommand</code>, then <code>setCurrentItemIndex(index)</code></td></tr><tr><td><code>command(&quot;Cancel&quot;)</code></td><td><code>executeCommand</code> -&gt; <code>itemCommand</code>, then <code>cancelEdit()</code> (<code>itemCancelingEdit</code>)</td></tr><tr><td><code>save(values)</code></td><td><code>controller.updateItem(index, values)</code> -&gt; <code>itemUpdating</code> (cancellable) -&gt; <code>Object.assign</code> -&gt; <code>itemUpdated</code> -&gt; <code>stateChanged</code></td></tr></tbody></table></div>\n<p>Gotchas:</p>\n<ul><li><code>RepeaterController.executeCommand</code> handles only <code>select</code>, <code>edit</code>, <code>cancel</code>. <strong><code>&quot;Delete&quot;</code> is not handled</strong> -- it only raises <code>itemCommand</code>. Call <code>controller.deleteItem(index)</code> yourself (example 4).</li><li><code>addItem</code>/<code>deleteItem</code> mutate the controller's internal copy; they do <strong>not</strong> write back to the original <code>dataSource</code> array or an <code>IDataSourceControl</code>. A later <code>dataBind()</code> restores the original data.</li><li><code>setCurrentItemIndex</code> throws a <code>RangeError</code> for out-of-range indices (rejects the click handler's promise).</li></ul>\n<hr>\n"},"react-webformsdatalist":{"overview":"<p>Renders a <code>DataListController&lt;T&gt;</code> as a table (<code>repeatLayout: &quot;Table&quot;</code>, the default) using the controller's <code>getLayoutMatrix()</code> (honours <code>repeatColumns</code> and <code>repeatDirection</code>), or as a flow of <code>&lt;div&gt;</code>s (<code>repeatLayout: &quot;Flow&quot;</code>).</p>\n","state":"<h3 id=\"71-state\">7.1 State<a class=\"anchor\" href=\"#71-state\" aria-label=\"Link to this section\">#</a></h3>\n<p>Subscribes to <code>controller.stateChanged</code>. The controller owns the item type of each item (<code>Item</code>, <code>AlternatingItem</code>, <code>SelectedItem</code>, <code>EditItem</code>) and rebuilds it on select/edit. Binding is up to you: call <code>await list.dataBind()</code>.</p>\n","props":"<h3 id=\"72-props\">7.2 Props<a class=\"anchor\" href=\"#72-props\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Prop</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>controller</code></td><td><code>DataListController&lt;T&gt;</code></td><td>yes</td><td>--</td><td>Controller.</td></tr><tr><td><code>className</code></td><td><code>string</code></td><td>no</td><td>--</td><td>Class of the outer <code>&lt;div&gt;</code>.</td></tr><tr><td><code>itemTemplate</code></td><td><code>(item, index, command) =&gt; ReactNode</code></td><td><strong>yes</strong></td><td>--</td><td>Default item renderer; also the fallback for any item type whose specific template is missing.</td></tr><tr><td><code>alternatingItemTemplate</code></td><td>same</td><td>no</td><td><code>itemTemplate</code></td><td>For <code>AlternatingItem</code> (odd, non-selected, non-edit).</td></tr><tr><td><code>selectedItemTemplate</code></td><td>same</td><td>no</td><td><code>itemTemplate</code></td><td>For <code>SelectedItem</code>.</td></tr><tr><td><code>editItemTemplate</code></td><td><code>(item, index, save, cancel) =&gt; ReactNode</code></td><td>no</td><td><code>itemTemplate</code></td><td>For <code>EditItem</code>. <code>save(values)</code> -&gt; <code>controller.updateItem</code>, <code>cancel()</code> -&gt; <code>controller.cancelEdit()</code>.</td></tr><tr><td><code>headerTemplate</code></td><td><code>() =&gt; ReactNode</code></td><td>no</td><td>--</td><td>Shown when <code>controller.showHeader</code> is true (Table layout also requires the template to be provided).</td></tr><tr><td><code>footerTemplate</code></td><td><code>() =&gt; ReactNode</code></td><td>no</td><td>--</td><td>Shown when <code>controller.showFooter</code> is true.</td></tr><tr><td><code>separatorTemplate</code></td><td><code>() =&gt; ReactNode</code></td><td>no</td><td>--</td><td><strong>Flow layout only</strong>: rendered after each item except the last. Ignored in Table layout.</td></tr><tr><td><code>emptyTemplate</code></td><td><code>() =&gt; ReactNode</code></td><td>no</td><td><code>&lt;p&gt;{controller.emptyText}&lt;/p&gt;</code></td><td>Rendered (without the wrapper <code>&lt;div&gt;</code>) when <code>controller.itemCount</code> is 0.</td></tr></tbody></table></div>\n<p><code>index</code> is the data item index (<code>itemIndex</code>), also valid for <code>executeCommand</code>.</p>\n","controller-properties-used":"<h3 id=\"73-controller-properties-used\">7.3 Controller properties used<a class=\"anchor\" href=\"#73-controller-properties-used\" aria-label=\"Link to this section\">#</a></h3>\n<p><code>repeatLayout</code> (<code>&quot;Table&quot;</code>/<code>&quot;Flow&quot;</code>), <code>repeatColumns</code> (0 treated as 1 column), <code>repeatDirection</code> (<code>&quot;Horizontal&quot;</code> row-major, <code>&quot;Vertical&quot;</code> column-major; default <code>&quot;Vertical&quot;</code>), <code>showTableBorder</code> -&gt; <code>border</code> attribute, <code>showHeader</code>, <code>showFooter</code>, <code>emptyText</code>. Defaults: <code>showHeader</code>/<code>showFooter</code> are <strong>false</strong>, <code>emptyText</code> is <code>&quot;No records available.&quot;</code>.</p>\n","markup-and-styling-hooks":"<h3 id=\"74-markup-and-styling-hooks\">7.4 Markup and styling hooks<a class=\"anchor\" href=\"#74-markup-and-styling-hooks\" aria-label=\"Link to this section\">#</a></h3>\n<p>Table layout:</p>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">html</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-html\"><span class=\"tok-t\">&lt;div</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;{className}&quot;</span>&gt;\n  <span class=\"tok-t\">&lt;table</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;datalist-table wf-datalist {className}&quot;</span><span class=\"tok-k\"> border</span>=<span class=\"tok-s\">&quot;0|1&quot;</span>&gt;\n    <span class=\"tok-t\">&lt;thead</span>&gt;<span class=\"tok-t\">&lt;tr</span>&gt;<span class=\"tok-t\">&lt;th</span><span class=\"tok-k\"> colspan</span>=<span class=\"tok-s\">&quot;{repeatColumns||1}&quot;</span>&gt;{headerTemplate()}<span class=\"tok-t\">&lt;/th</span>&gt;<span class=\"tok-t\">&lt;/tr</span>&gt;<span class=\"tok-t\">&lt;/thead</span>&gt;   <span class=\"tok-c\">&lt;!-- showHeader &amp;&amp; headerTemplate --&gt;</span>\n    <span class=\"tok-t\">&lt;tbody</span>&gt;\n      <span class=\"tok-t\">&lt;tr</span>&gt;\n        <span class=\"tok-t\">&lt;td</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;datalist-cell datalist-item|datalist-alternatingitem|datalist-selecteditem|datalist-edititem&quot;</span>&gt;...<span class=\"tok-t\">&lt;/td</span>&gt;\n        <span class=\"tok-t\">&lt;td</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;datalist-cell-empty&quot;</span>&gt;<span class=\"tok-t\">&lt;/td</span>&gt;                                         <span class=\"tok-c\">&lt;!-- padding for the last row --&gt;</span>\n      <span class=\"tok-t\">&lt;/tr</span>&gt;\n    <span class=\"tok-t\">&lt;/tbody</span>&gt;\n    <span class=\"tok-t\">&lt;tfoot</span>&gt;<span class=\"tok-t\">&lt;tr</span>&gt;<span class=\"tok-t\">&lt;td</span><span class=\"tok-k\"> colspan</span>=<span class=\"tok-s\">&quot;...&quot;</span>&gt;{footerTemplate()}<span class=\"tok-t\">&lt;/td</span>&gt;<span class=\"tok-t\">&lt;/tr</span>&gt;<span class=\"tok-t\">&lt;/tfoot</span>&gt;                 <span class=\"tok-c\">&lt;!-- showFooter &amp;&amp; footerTemplate --&gt;</span>\n  <span class=\"tok-t\">&lt;/table</span>&gt;\n<span class=\"tok-t\">&lt;/div</span>&gt;</code></pre></div>\n<p>Flow layout: root <code>&lt;div class=&quot;wf-datalist {className}&quot;&gt;</code>; each item is <code>&lt;div class=&quot;datalist-item datalist-{itemtype lowercased} [alt|selected|edit|header|footer|separator]&quot;&gt;</code>. The semantic class (<code>alt</code>, <code>selected</code>, <code>edit</code>, plus <code>header</code> / <code>footer</code> / <code>separator</code> for those item types) is the hook the <code>dl-&lt;theme&gt;</code> family styles. In Table layout the table is <code>table.datalist-table.wf-datalist.{className}</code> inside <code>div.{className}</code> and the cells carry the same semantic class. The empty state is <code>&lt;p class=&quot;empty&quot;&gt;{emptyText}&lt;/p&gt;</code>.</p>\n<p>Theming: <code>className=&quot;dl-modern&quot;</code> plus <code>modern-full.css</code>. Inputs, selects, textareas, checkboxes, labels and buttons in the edit item are styled like the Repeater's edit item (section 6.4).</p>\n<p>Item-type class suffixes are the lower-cased <code>DataListItemType</code>: <code>datalist-item</code>, <code>datalist-alternatingitem</code>, <code>datalist-selecteditem</code>, <code>datalist-edititem</code>. Note that in Table layout the cell class is <code>datalist-cell datalist-&lt;type&gt;</code> -- so a plain item is <code>datalist-cell datalist-item</code>. The semantic classes <code>alt</code> / <code>selected</code> / <code>edit</code> / <code>header</code> / <code>footer</code> / <code>separator</code> are added next to them. No ARIA or data attributes.</p>\n","command-flow":"<h3 id=\"75-command-flow\">7.5 Command flow<a class=\"anchor\" href=\"#75-command-flow\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>UI action</th><th>Controller call</th><th>Events</th></tr></thead><tbody><tr><td><code>command(&quot;Edit&quot;)</code></td><td><code>executeCommand(i, &quot;Edit&quot;)</code></td><td><code>itemCommand</code> -&gt; <code>beginEdit</code> -&gt; <code>itemEditing</code> (cancellable)</td></tr><tr><td><code>command(&quot;Cancel&quot;)</code></td><td>-&gt; <code>cancelEdit</code></td><td><code>itemCancelingEdit</code> (cancellable)</td></tr><tr><td><code>command(&quot;Delete&quot;)</code></td><td>-&gt; <code>deleteItem</code></td><td><code>itemDeleting</code> (cancellable) -&gt; data-source <code>delete</code> (if source is an <code>IDataSourceControl</code>) -&gt; <code>itemDeleted</code></td></tr><tr><td><code>command(&quot;Select&quot;)</code></td><td>-&gt; <code>selectItem</code></td><td><code>selectedIndexChanged</code></td></tr><tr><td><code>save(values)</code></td><td><code>updateItem(i, values)</code></td><td><code>itemUpdating</code> (cancellable) -&gt; data-source <code>update</code> -&gt; <code>itemUpdated</code></td></tr></tbody></table></div>\n<p>Unlike the Repeater, the DataList controller <strong>does</strong> handle <code>delete</code>. <code>&quot;Update&quot;</code> is not a command name; use <code>save</code>.</p>\n<p>Gotchas: React keys are item index (not the data key); <code>dataBind</code> with an <code>IDataSourceControl</code> only accepts array results.</p>\n<hr>\n"},"react-navigation-components-controller-or-props":{"overview":"<p>Each component has two modes. <strong>Plain mode</strong> takes <code>items</code> / <code>nodes</code> and keeps its own expand/selection state. <strong>Controller mode</strong> takes a <code>controller</code> prop: the component subscribes to <code>stateChanged</code>, reads the controller on every render and routes clicks, expansion and selection back into it. When both are given, <code>controller</code> wins. In controller mode you still call <code>dataBind()</code> yourself.</p>\n","navigationmenu":"<h3 id=\"81-navigationmenu\">8.1 <code>NavigationMenu</code><a class=\"anchor\" href=\"#81-navigationmenu\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Prop</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>items</code></td><td><code>MenuItem[] | Array&lt;{ text: string; value?: string; navigateUrl?: string; childItems?: any[] }&gt;</code></td><td>no</td><td><code>[]</code></td><td>Item tree. <code>childItems</code> become flyouts. <code>MenuItem</code> is the core class.</td></tr><tr><td><code>controller</code></td><td><code>MenuController</code></td><td>no</td><td>--</td><td>Wins over <code>items</code>. Orientation, static/dynamic levels (<code>getStaticItems()</code> / <code>getDynamicItems(item)</code>) and <code>disappearAfter</code> come from it; clicks go through <code>controller.clickItem(item)</code>.</td></tr><tr><td><code>orientation</code></td><td><code>&quot;horizontal&quot; | &quot;vertical&quot;</code></td><td>no</td><td><code>&quot;horizontal&quot;</code></td><td><strong>Lower-case</strong> here (core <code>MenuOrientation</code> is <code>&quot;Horizontal&quot;</code>/<code>&quot;Vertical&quot;</code>). Ignored when a <code>controller</code> is given.</td></tr><tr><td><code>className</code></td><td><code>string</code></td><td>no</td><td><code>&quot;&quot;</code></td><td>Extra class(es) on the <strong>root</strong> element, for both orientations. Put the kit theme here (<code>mn-modern</code>).</td></tr><tr><td><code>ariaLabel</code></td><td><code>string</code></td><td>no</td><td><code>&quot;Menu&quot;</code></td><td><code>aria-label</code> of the root <code>role=&quot;navigation&quot;</code>.</td></tr><tr><td><code>onItemClick</code></td><td><code>(item: any) =&gt; void</code></td><td>no</td><td>--</td><td>Called with the clicked item when the click was accepted (not cancelled by <code>menuItemClick</code> in controller mode).</td></tr></tbody></table></div>\n<p>Behaviour:</p>\n<ul><li><strong>Flyouts are real.</strong> Items with children (and <code>enabled</code>) get <code>a.has-popup</code>, <code>aria-haspopup=&quot;menu&quot;</code> and <code>aria-expanded</code>. A flyout opens on hover, on click (when the item has no <code>navigateUrl</code>) and with the keyboard; it closes after <code>disappearAfter</code> ms (default 500) once the pointer leaves, on Escape, or after a click.</li><li>Keys: Arrow keys move between siblings, Down (horizontal top level) or Right opens a flyout, Left/Escape closes it, Space activates an item without a URL.</li><li><code>enabled: false</code> renders <code>disabled</code> + <code>aria-disabled</code> and ignores clicks. <code>selected</code> renders <code>selected active</code> on the link. <code>target</code> and <code>tooltip</code> are applied as <code>target</code> and <code>title</code>.</li><li>In plain mode <code>onItemClick</code> does not call <code>preventDefault()</code>; navigation still happens. In controller mode the cancellable <code>menuItemClick</code> event fires first, but an async cancel cannot stop native anchor navigation.</li><li>Link text = <code>item.text ?? item.title ?? &quot;Item N&quot;</code>; href = <code>item.navigateUrl ?? item.url</code>.</li><li>The type does not include <code>SiteMapNode</code> (<code>title</code>/<code>url</code>); convert with <code>MenuItem.fromSiteMapNode</code> or let <code>MenuController.dataBind(siteMap)</code> do it.</li><li><code>imageUrl</code> and <code>separatorImageUrl</code> are not rendered.</li></ul>\n<p>Markup:</p>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">html</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-html\"><span class=\"tok-c\">&lt;!-- horizontal root --&gt;</span>\n<span class=\"tok-t\">&lt;div</span><span class=\"tok-k\"> role</span>=<span class=\"tok-s\">&quot;navigation&quot;</span><span class=\"tok-k\"> aria-label</span>=<span class=\"tok-s\">&quot;Menu&quot;</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;{className} navbar navbar-expand navbar-light bg-light rounded px-3&quot;</span>&gt;\n<span class=\"tok-c\">&lt;!-- vertical root --&gt;</span>\n<span class=\"tok-t\">&lt;div</span><span class=\"tok-k\"> role</span>=<span class=\"tok-s\">&quot;navigation&quot;</span><span class=\"tok-k\"> aria-label</span>=<span class=\"tok-s\">&quot;Menu&quot;</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;{className} nav flex-column mn-vertical&quot;</span>&gt;\n  <span class=\"tok-t\">&lt;ul</span><span class=\"tok-k\"> role</span>=<span class=\"tok-s\">&quot;menubar&quot;</span><span class=\"tok-k\"> aria-orientation</span>=<span class=\"tok-s\">&quot;horizontal&quot;</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;static navbar-nav me-auto&quot;</span>&gt;\n    <span class=\"tok-t\">&lt;li</span><span class=\"tok-k\"> role</span>=<span class=\"tok-s\">&quot;none&quot;</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;nav-item position-relative&quot;</span>&gt;\n      <span class=\"tok-t\">&lt;a</span><span class=\"tok-k\"> role</span>=<span class=\"tok-s\">&quot;menuitem&quot;</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;nav-link selected active has-popup&quot;</span> href<span class=\"tok-k\"> aria-haspopup</span>=<span class=\"tok-s\">&quot;menu&quot;</span><span class=\"tok-k\"> aria-expanded</span>=<span class=\"tok-s\">&quot;true&quot;</span>&gt;Products<span class=\"tok-t\">&lt;/a</span>&gt;\n      <span class=\"tok-t\">&lt;ul</span><span class=\"tok-k\"> role</span>=<span class=\"tok-s\">&quot;menu&quot;</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;dynamic dropdown-menu show position-absolute&quot;</span>&gt;<span class=\"tok-t\">&lt;li</span><span class=\"tok-k\"> role</span>=<span class=\"tok-s\">&quot;none&quot;</span>&gt;...<span class=\"tok-t\">&lt;/li</span>&gt;<span class=\"tok-t\">&lt;/ul</span>&gt;\n    <span class=\"tok-t\">&lt;/li</span>&gt;\n  <span class=\"tok-t\">&lt;/ul</span>&gt;\n<span class=\"tok-t\">&lt;/div</span>&gt;</code></pre></div>\n<p>The root is a <code>div[role=navigation]</code> (not a <code>&lt;nav&gt;</code>). The Bootstrap classes on the root and lists are kept for projects that use Bootstrap; the kit's <code>div.mn-&lt;theme&gt;</code> selector matches because <code>className</code> is on the same element. For the kit, load <code>adapters.css</code> after the theme (it resets the absolute positioning of flyouts).</p>\n","breadcrumb":"<h3 id=\"82-breadcrumb\">8.2 <code>Breadcrumb</code><a class=\"anchor\" href=\"#82-breadcrumb\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Prop</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>items</code></td><td><code>BreadcrumbItem[]</code></td><td>no</td><td><strong>demo data</strong>: <code>Home (/)</code>, <code>Section (#)</code>, <code>Current Page</code></td><td><code>BreadcrumbItem = { text?, title?, url?, navigateUrl? }</code> (all optional). The last item is the current page.</td></tr><tr><td><code>controller</code></td><td><code>SiteMapPathController</code></td><td>no</td><td>--</td><td>Wins over <code>items</code>. Items come from <code>controller.getItems()</code> (honours <code>pathDirection</code>, <code>parentLevelsDisplayed</code>, <code>renderCurrentNodeAsLink</code>, <code>showToolTips</code>). Call <code>dataBind(currentUrl)</code> yourself.</td></tr><tr><td><code>separator</code></td><td><code>ReactNode</code></td><td>no</td><td>controller <code>pathSeparator</code>, else <code>&quot; / &quot;</code></td><td>A string or number is exposed on each separator as <code>data-separator</code>. The glyph itself is drawn by CSS.</td></tr><tr><td><code>className</code></td><td><code>string</code></td><td>no</td><td><code>&quot;&quot;</code></td><td>Class on the <strong>inner <code>&lt;span&gt;</code></strong>. Put the kit theme here (<code>nv-modern</code>).</td></tr><tr><td><code>ariaLabel</code></td><td><code>string</code></td><td>no</td><td><code>&quot;breadcrumb&quot;</code></td><td><code>aria-label</code> of the <code>&lt;nav&gt;</code>.</td></tr><tr><td><code>onItemClick</code></td><td><code>(item: BreadcrumbItem | SiteMapPathItem) =&gt; void</code></td><td>no</td><td>--</td><td>When provided, link clicks call <code>preventDefault()</code> and then this callback (SPA routing). Without it, normal navigation.</td></tr></tbody></table></div>\n<p>Markup (the kit's SiteMapPath structure, not Bootstrap's <code>ol.breadcrumb</code>):</p>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">html</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-html\"><span class=\"tok-t\">&lt;nav</span><span class=\"tok-k\"> aria-label</span>=<span class=\"tok-s\">&quot;breadcrumb&quot;</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;wf-breadcrumb&quot;</span>&gt;\n  <span class=\"tok-t\">&lt;span</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;{className}&quot;</span>&gt;\n    <span class=\"tok-t\">&lt;a</span><span class=\"tok-k\"> href</span>=<span class=\"tok-s\">&quot;/&quot;</span>&gt;Home<span class=\"tok-t\">&lt;/a</span>&gt;<span class=\"tok-t\">&lt;span</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;sep&quot;</span><span class=\"tok-k\"> aria-hidden</span>=<span class=\"tok-s\">&quot;true&quot;</span><span class=\"tok-k\"> data-separator</span>=<span class=\"tok-s\">&quot; / &quot;</span>&gt;<span class=\"tok-t\">&lt;/span</span>&gt;\n    <span class=\"tok-t\">&lt;a</span><span class=\"tok-k\"> href</span>=<span class=\"tok-s\">&quot;/products&quot;</span>&gt;Products<span class=\"tok-t\">&lt;/a</span>&gt;<span class=\"tok-t\">&lt;span</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;sep&quot;</span><span class=\"tok-k\"> aria-hidden</span>=<span class=\"tok-s\">&quot;true&quot;</span><span class=\"tok-k\"> data-separator</span>=<span class=\"tok-s\">&quot; / &quot;</span>&gt;<span class=\"tok-t\">&lt;/span</span>&gt;\n    <span class=\"tok-t\">&lt;span</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;current&quot;</span><span class=\"tok-k\"> aria-current</span>=<span class=\"tok-s\">&quot;page&quot;</span>&gt;Phones<span class=\"tok-t\">&lt;/span</span>&gt;\n  <span class=\"tok-t\">&lt;/span</span>&gt;\n<span class=\"tok-t\">&lt;/nav</span>&gt;</code></pre></div>\n<p>Gotchas:</p>\n<ul><li><strong>Omitting <code>items</code> (and <code>controller</code>) renders the demo breadcrumb</strong> (Home / Section / Current Page), not an empty one. Pass <code>items={[]}</code> to render nothing.</li><li>In plain mode the last item, and any item without an href, is a non-link <code>span.current</code>. In controller mode the current node is a link only when the controller says so (<code>isLink</code>).</li><li>Without the kit (or your own CSS for <code>.sep::before</code>) the separator is invisible, because the element is empty.</li><li>Mapping <code>SiteMapPathController.getItems()</code> to plain items is no longer needed: pass the controller.</li></ul>\n","treeview":"<h3 id=\"83-treeview\">8.3 <code>TreeView</code><a class=\"anchor\" href=\"#83-treeview\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Prop</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>nodes</code></td><td><code>TreeNode[]</code> (adapter interface)</td><td>no</td><td><code>[]</code></td><td><code>{ text; value?; navigateUrl?; expanded?; selected?; imageUrl?; expandedImageUrl?; children?: TreeNode[] }</code>.</td></tr><tr><td><code>controller</code></td><td><code>TreeViewController</code></td><td>no</td><td>--</td><td>Wins over <code>nodes</code>. Checkboxes (<code>showCheckBoxes</code>), selection, expand/collapse and <code>showLines</code> come from the controller. Call <code>dataBind()</code> / <code>setNodes()</code> yourself.</td></tr><tr><td><code>showLines</code></td><td><code>boolean</code></td><td>no</td><td>controller <code>showLines</code></td><td>Adds <code>wf-treeview-lines</code> to the root.</td></tr><tr><td><code>className</code></td><td><code>string</code></td><td>no</td><td><code>&quot;&quot;</code></td><td>Appended to the root <code>div.wf-treeview</code>. Put the kit theme here (<code>tv-modern</code>).</td></tr><tr><td><code>ariaLabel</code></td><td><code>string</code></td><td>no</td><td><code>&quot;Tree&quot;</code></td><td><code>aria-label</code> of the <code>ul[role=tree]</code>.</td></tr><tr><td><code>onNodeClick</code></td><td><code>(node: TreeNode) =&gt; void</code></td><td>no</td><td>--</td><td>Plain mode: fired when a node row is selected (click, Enter or Space).</td></tr><tr><td><code>onNodeToggle</code></td><td><code>(node: TreeNode, isExpanded: boolean) =&gt; void</code></td><td>no</td><td>--</td><td>Plain mode: fired when a node is expanded or collapsed.</td></tr></tbody></table></div>\n<p>Behaviour and gotchas:</p>\n<ul><li><strong>Plain mode</strong> keeps expansion and selection locally, keyed by node path: nodes are <strong>expanded by default</strong> (core <code>TreeNode.expanded</code> defaults to <code>false</code>) unless <code>node.expanded</code> says otherwise; <code>selected: true</code> sets the initial selection. There are no checkboxes in plain mode.</li><li><strong>Controller mode</strong> reads <code>node.expanded</code>, <code>node.selected</code>, <code>node.checked</code> and <code>controller.shouldShowCheckBox(node)</code>, and calls <code>expandNode</code>, <code>collapseNode</code>, <code>selectNode</code>, <code>toggleNode</code>, <code>checkNode</code>. <code>onNodeClick</code> / <code>onNodeToggle</code> are not used; subscribe to the controller events.</li><li>Core <code>TreeNode</code> objects use <code>childNodes</code>, not <code>children</code>: in plain mode you must convert; in controller mode you do not.</li><li>Keyboard (on the focused row): Right expands, Left collapses, Enter/Space selects.</li><li>Images: <code>imageUrl</code> / <code>expandedImageUrl</code> render as an <code>&lt;img&gt;</code> before the label.</li></ul>\n<p>Markup:</p>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">html</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-html\"><span class=\"tok-t\">&lt;div</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;wf-treeview {wf-treeview-lines} {className}&quot;</span>&gt;\n  <span class=\"tok-t\">&lt;ul</span><span class=\"tok-k\"> role</span>=<span class=\"tok-s\">&quot;tree&quot;</span><span class=\"tok-k\"> aria-label</span>=<span class=\"tok-s\">&quot;Tree&quot;</span>&gt;\n    <span class=\"tok-t\">&lt;li</span><span class=\"tok-k\"> role</span>=<span class=\"tok-s\">&quot;treeitem&quot;</span><span class=\"tok-k\"> aria-level</span>=<span class=\"tok-s\">&quot;1&quot;</span><span class=\"tok-k\"> aria-expanded</span>=<span class=\"tok-s\">&quot;true&quot;</span><span class=\"tok-k\"> aria-selected</span>=<span class=\"tok-s\">&quot;false&quot;</span>&gt;\n      <span class=\"tok-t\">&lt;div</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;d-flex ...&quot;</span><span class=\"tok-k\"> tabindex</span>=<span class=\"tok-s\">&quot;0&quot;</span>&gt;\n        <span class=\"tok-t\">&lt;button</span><span class=\"tok-k\"> type</span>=<span class=\"tok-s\">&quot;button&quot;</span><span class=\"tok-k\"> aria-label</span>=<span class=\"tok-s\">&quot;Collapse Root&quot;</span>&gt;v<span class=\"tok-t\">&lt;/button</span>&gt;   <span class=\"tok-c\">&lt;!-- or a bullet span for a leaf; a checkbox in controller mode --&gt;</span>\n        <span class=\"tok-t\">&lt;a</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;root parent selected&quot;</span><span class=\"tok-k\"> href</span>=<span class=\"tok-s\">&quot;#&quot;</span><span class=\"tok-k\"> role</span>=<span class=\"tok-s\">&quot;button&quot;</span>&gt;Root<span class=\"tok-t\">&lt;/a</span>&gt;   <span class=\"tok-c\">&lt;!-- root | parent | leaf, plus selected --&gt;</span>\n      <span class=\"tok-t\">&lt;/div</span>&gt;\n      <span class=\"tok-t\">&lt;div</span><span class=\"tok-k\"> id</span>=<span class=\"tok-s\">&quot;{treeId}_n0Nodes&quot;</span><span class=\"tok-k\"> role</span>=<span class=\"tok-s\">&quot;group&quot;</span>&gt;<span class=\"tok-t\">&lt;ul</span><span class=\"tok-k\"> role</span>=<span class=\"tok-s\">&quot;none&quot;</span>&gt; ...child li... <span class=\"tok-t\">&lt;/ul</span>&gt;<span class=\"tok-t\">&lt;/div</span>&gt;\n    <span class=\"tok-t\">&lt;/li</span>&gt;\n  <span class=\"tok-t\">&lt;/ul</span>&gt;\n<span class=\"tok-t\">&lt;/div</span>&gt;</code></pre></div>\n<p>Node labels are <code>&lt;a&gt;</code> with class <code>root</code> (depth 0), <code>parent</code> or <code>leaf</code>, and <code>selected</code>; a node without <code>navigateUrl</code> is <code>&lt;a href=&quot;#&quot; role=&quot;button&quot;&gt;</code> with the click default-prevented. Child groups are <code>div[role=group]</code> whose id ends in <code>Nodes</code>, which is the kit's <code>div[id$=&quot;Nodes&quot;]</code> selector. Nodes are laid out as <code>ul</code>/<code>li</code>, not as the nested tables ASP.NET emits, so load <code>adapters.css</code> after the theme (it removes the list bullets and styles the toggle button).</p>\n<hr>\n"},"react-webformsmodal":{"overview":"<p>A dialog that can be driven by a core <code>ModalBehavior</code>, by a controlled <code>isOpen</code> prop, or by neither (it then only opens if <code>isOpen</code> is initially true and closes itself).</p>\n","props":"<h3 id=\"91-props\">9.1 Props<a class=\"anchor\" href=\"#91-props\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Prop</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>behavior</code></td><td><code>ModalBehavior</code></td><td>no</td><td>--</td><td>If provided, the component subscribes to <code>behavior.shown</code> / <code>behavior.hidden</code> and delegates OK/Cancel to <code>behavior.handleOk()</code> / <code>behavior.handleCancel()</code>. Initial state = <code>behavior.isOpen</code>.</td></tr><tr><td><code>isOpen</code></td><td><code>boolean</code></td><td>no</td><td>--</td><td><strong>Controlled mode.</strong> When defined (even <code>false</code>) it overrides the behavior/internal state for visibility.</td></tr><tr><td><code>title</code></td><td><code>string</code></td><td>no</td><td><code>&quot;Dialog&quot;</code></td><td>Header text (<code>&lt;h5 class=&quot;modal-title&quot;&gt;</code>).</td></tr><tr><td><code>onClose</code></td><td><code>() =&gt; void</code></td><td>no</td><td>--</td><td>Called after Cancel button and header &quot;X&quot; (after <code>behavior.handleCancel()</code> resolves). <strong>Not</strong> called for OK.</td></tr><tr><td><code>onOk</code></td><td><code>() =&gt; void</code></td><td>no</td><td>--</td><td>Called after the OK button (after <code>behavior.handleOk()</code> resolves).</td></tr><tr><td><code>okText</code></td><td><code>string</code></td><td>no</td><td><code>&quot;OK&quot;</code></td><td>OK button label.</td></tr><tr><td><code>cancelText</code></td><td><code>string</code></td><td>no</td><td><code>&quot;Cancel&quot;</code></td><td>Cancel button label.</td></tr><tr><td><code>showFooter</code></td><td><code>boolean</code></td><td>no</td><td><code>true</code></td><td>Hides the OK/Cancel footer when <code>false</code>.</td></tr><tr><td><code>className</code></td><td><code>string</code></td><td>no</td><td><code>&quot;&quot;</code></td><td>Appended to the backdrop <code>&lt;div class=&quot;modal ...&quot;&gt;</code>.</td></tr><tr><td><code>children</code></td><td><code>ReactNode</code></td><td>no</td><td>--</td><td>Body content.</td></tr></tbody></table></div>\n","state-and-command-flow":"<h3 id=\"92-state-and-command-flow\">9.2 State and command flow<a class=\"anchor\" href=\"#92-state-and-command-flow\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Situation</th><th>What happens</th></tr></thead><tbody><tr><td><code>await modal.show()</code> / <code>hide()</code> on the behavior</td><td>Fires <code>shown</code> / <code>hidden</code>; the component flips its internal state.</td></tr><tr><td>OK clicked, with behavior</td><td><code>behavior.handleOk()</code>: runs <code>options.onOk</code> -&gt; emits <code>ok</code> -&gt; <code>hide()</code> (-&gt; <code>hidden</code>). Then the <code>onOk</code> prop runs.</td></tr><tr><td>Cancel / X clicked, with behavior</td><td><code>behavior.handleCancel()</code>: runs <code>options.onCancel</code> -&gt; emits <code>cancel</code> -&gt; <code>hide()</code>. Then <code>onClose</code>.</td></tr><tr><td>OK / Cancel without behavior</td><td>Internal state set to <code>false</code>, then <code>onOk</code> / <code>onClose</code>.</td></tr><tr><td><code>isOpen</code> provided</td><td>Visibility follows the prop only. The component <strong>cannot close itself</strong>; update your state in <code>onOk</code>/<code>onClose</code>.</td></tr></tbody></table></div>\n<p>Gotchas:</p>\n<ul><li>If you pass both <code>behavior</code> and <code>isOpen</code>, the prop wins; the behavior's <code>hidden</code> event will not hide the dialog.</li><li><code>ModalBehaviorOptions</code> fields <code>targetControlId</code>, <code>popupControlId</code>, <code>okControlId</code>, <code>cancelControlId</code>, <code>backgroundCssClass</code>, <code>dropShadow</code> are <strong>not used</strong> by the adapter. Only <code>onOk</code> / <code>onCancel</code> (and the events) matter.</li><li>The behavior's <code>onOk</code> option is awaited, but if it throws, the dialog stays open and the <code>onOk</code> prop is not called.</li><li>The component only reads <code>behavior.isOpen</code> for the initial state; it assumes the behavior instance is stable (<code>useMemo</code>/<code>useRef</code>). A re-created instance is re-subscribed, but its current open state is not re-read, so a dialog shown through the old instance will not appear.</li><li>Dismissal and focus: <strong>Escape</strong> and a <strong>backdrop click</strong> cancel (same path as the Cancel button: <code>behavior.handleCancel()</code>, then <code>onClose</code>). On open the dialog receives focus, <strong>Tab / Shift+Tab are trapped</strong> inside it, <code>document.body</code> scroll is <strong>locked</strong> (<code>overflow: hidden</code>, restored on close) and focus <strong>returns</strong> to the previously focused element on close. Clicks inside the dialog do not bubble to the backdrop.</li><li>Renders <code>null</code> when closed (children are unmounted).</li></ul>\n","markup-styling-and-accessibility":"<h3 id=\"93-markup-styling-and-accessibility\">9.3 Markup, styling and accessibility<a class=\"anchor\" href=\"#93-markup-styling-and-accessibility\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">html</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-html\"><span class=\"tok-t\">&lt;div</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;modal fade show d-block {className}&quot;</span><span class=\"tok-k\"> tabindex</span>=<span class=\"tok-s\">&quot;-1&quot;</span><span class=\"tok-k\"> role</span>=<span class=\"tok-s\">&quot;dialog&quot;</span><span class=\"tok-k\"> aria-modal</span>=<span class=\"tok-s\">&quot;true&quot;</span><span class=\"tok-k\"> aria-labelledby</span>=<span class=\"tok-s\">&quot;{id}&quot;</span>\n    <span class=\"tok-k\"> style</span>=<span class=\"tok-s\">&quot;background-color: var(--wf-backdrop, rgba(0,0,0,0.5))&quot;</span>&gt;\n  <span class=\"tok-t\">&lt;div</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;modal-dialog modal-dialog-centered&quot;</span><span class=\"tok-k\"> role</span>=<span class=\"tok-s\">&quot;document&quot;</span>&gt;\n    <span class=\"tok-t\">&lt;div</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;modal-content shadow&quot;</span>&gt;\n      <span class=\"tok-t\">&lt;div</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;modal-header&quot;</span>&gt;<span class=\"tok-t\">&lt;h5</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;modal-title&quot;</span><span class=\"tok-k\"> id</span>=<span class=\"tok-s\">&quot;{id}&quot;</span>&gt;{title}<span class=\"tok-t\">&lt;/h5</span>&gt;<span class=\"tok-t\">&lt;button</span><span class=\"tok-k\"> type</span>=<span class=\"tok-s\">&quot;button&quot;</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;btn-close&quot;</span><span class=\"tok-k\"> aria-label</span>=<span class=\"tok-s\">&quot;Close&quot;</span>&gt;<span class=\"tok-t\">&lt;/button</span>&gt;<span class=\"tok-t\">&lt;/div</span>&gt;\n      <span class=\"tok-t\">&lt;div</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;modal-body&quot;</span>&gt;{children}<span class=\"tok-t\">&lt;/div</span>&gt;\n      <span class=\"tok-t\">&lt;div</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;modal-footer&quot;</span>&gt;   <span class=\"tok-c\">&lt;!-- showFooter --&gt;</span>\n        <span class=\"tok-t\">&lt;button</span><span class=\"tok-k\"> type</span>=<span class=\"tok-s\">&quot;button&quot;</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;btn btn-secondary&quot;</span>&gt;{cancelText}<span class=\"tok-t\">&lt;/button</span>&gt;\n        <span class=\"tok-t\">&lt;button</span><span class=\"tok-k\"> type</span>=<span class=\"tok-s\">&quot;button&quot;</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;btn btn-primary&quot;</span>&gt;{okText}<span class=\"tok-t\">&lt;/button</span>&gt;\n      <span class=\"tok-t\">&lt;/div</span>&gt;\n    <span class=\"tok-t\">&lt;/div</span>&gt;\n  <span class=\"tok-t\">&lt;/div</span>&gt;\n<span class=\"tok-t\">&lt;/div</span>&gt;</code></pre></div>\n<p>Accessibility emitted: <code>role=&quot;dialog&quot;</code>, <code>aria-modal=&quot;true&quot;</code>, <code>aria-labelledby</code> (pointing at the <code>h5.modal-title</code>, id from <code>useId()</code>), <code>role=&quot;document&quot;</code>, <code>tabIndex=-1</code> and <code>aria-label=&quot;Close&quot;</code> on the X button. <strong>Not</strong> emitted: <code>aria-describedby</code> (add it yourself if the body is a short message).</p>\n<p><strong>Backdrop colour:</strong> the overlay's inline <code>background-color</code> is <code>var(--wf-backdrop, rgba(0,0,0,0.5))</code>. Set the variable on <code>:root</code> or on the dialog's class (for example <code>.md-dark { --wf-backdrop: rgba(0,0,0,.75) }</code>) to change it.</p>\n<p><strong>Theming:</strong> pass <code>className=&quot;md-modern&quot;</code> (appended to <code>div.modal</code>) and load <code>@wf-controls/styles/bundles/modern-full.css</code>. The <code>md-&lt;theme&gt;</code> family makes <code>div.modal</code> a full-viewport overlay, centres the dialog and styles header, close button, body form controls and the OK / Cancel buttons (primary = theme accent). Without the kit you need Bootstrap or your own <code>.modal</code> rules.</p>\n<hr>\n"},"react-webformstabs":{"props":"<h3 id=\"101-props\">10.1 Props<a class=\"anchor\" href=\"#101-props\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Prop</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>controller</code></td><td><code>TabsController</code></td><td>no</td><td>--</td><td>Source of active index (subscribes to <code>activeTabChanged</code>) and, if <code>tabs</code> is empty, of the tab list. Initial index = <code>controller.activeTabIndex</code>.</td></tr><tr><td><code>tabs</code></td><td><code>TabDefinition[]</code></td><td>no</td><td><code>[]</code></td><td><code>TabDefinition = TabItem &amp; { content?: ReactNode }</code>; <code>TabItem = { id: string; headerText: string; enabled?: boolean; visible?: boolean }</code>. When non-empty, takes precedence over <code>controller.tabs</code>.</td></tr><tr><td><code>activeTabIndex</code></td><td><code>number</code></td><td>no</td><td>--</td><td><strong>Controlled mode.</strong> When defined, overrides the controller/internal index.</td></tr><tr><td><code>onActiveTabChanged</code></td><td><code>(newIndex: number) =&gt; void</code></td><td>no</td><td>--</td><td>Called on every tab-button click and on keyboard navigation (see gotchas).</td></tr><tr><td><code>className</code></td><td><code>string</code></td><td>no</td><td><code>&quot;&quot;</code></td><td>Appended to the wrapper <code>wf-tabs</code>. Put the kit theme here (<code>tb-modern</code>).</td></tr><tr><td><code>children</code></td><td><code>ReactNode</code></td><td>no</td><td>--</td><td>Rendered inside <code>.tab-content</code> after the active pane.</td></tr></tbody></table></div>\n","command-flow":"<h3 id=\"102-command-flow\">10.2 Command flow<a class=\"anchor\" href=\"#102-command-flow\" aria-label=\"Link to this section\">#</a></h3>\n<p>Tab click (enabled, visible tabs only) -&gt; <code>controller.setActiveTab(idx)</code> if a controller exists (validates the index, ignores no-ops, emits <code>activeTabChanged</code> -&gt; component re-renders), <strong>else</strong> internal state is set -&gt; then <code>onActiveTabChanged(idx)</code> fires in both cases.</p>\n<p>Keyboard (on the tab list): ArrowRight/ArrowLeft move to the next/previous <strong>selectable</strong> tab (enabled and visible), Home/End jump to the first/last selectable tab; focus follows the selection. Only the active tab is in the tab order (roving <code>tabindex</code>).</p>\n<p>Gotchas:</p>\n<ul><li><code>onActiveTabChanged</code> fires on click even if the controller ignores the change (e.g. re-clicking the active tab), and fires <strong>before</strong> the controller's async event completes. To react to real changes subscribe to <code>controller.activeTabChanged</code>.</li><li>In controlled mode with no controller, internal state is irrelevant; you must set <code>activeTabIndex</code> from <code>onActiveTabChanged</code>, otherwise the UI will not change.</li><li><strong>Pane content comes only from <code>TabDefinition.content</code>.</strong> A <code>TabsController</code>'s <code>TabItem</code>s have no content, so with a controller alone you must supply <code>children</code> -- and <code>children</code> are rendered <strong>all the time</strong> (not per tab); switch them yourself on <code>controller.activeTabIndex</code> (example 7). You must also re-render the parent when the active tab changes (subscribe to <code>activeTabChanged</code>), as <code>children</code> are evaluated by the parent.</li><li><code>visible: false</code> is honoured: the header and its pane are not rendered, and the tab is skipped by keyboard navigation. <code>enabled: false</code> disables the button and adds the <code>disabled</code> class.</li><li>The adapter does not subscribe to tab-list changes (<code>controller.setTabs</code>); it re-renders only on index change or parent re-render.</li><li>The key of each tab is <code>tab.id || idx</code>.</li></ul>\n","markup-and-accessibility":"<h3 id=\"103-markup-and-accessibility\">10.3 Markup and accessibility<a class=\"anchor\" href=\"#103-markup-and-accessibility\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">html</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-html\"><span class=\"tok-t\">&lt;div</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;wf-tabs {className}&quot;</span>&gt;\n  <span class=\"tok-t\">&lt;ul</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;ajax__tab_header nav nav-tabs mb-3&quot;</span><span class=\"tok-k\"> role</span>=<span class=\"tok-s\">&quot;tablist&quot;</span>&gt;\n    <span class=\"tok-t\">&lt;li</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;nav-item&quot;</span><span class=\"tok-k\"> role</span>=<span class=\"tok-s\">&quot;presentation&quot;</span>&gt;\n      <span class=\"tok-t\">&lt;span</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;ajax__tab_outer ajax__tab_active&quot;</span>&gt;           <span class=\"tok-c\">&lt;!-- ajax__tab_active on the active tab only --&gt;</span>\n        <span class=\"tok-t\">&lt;span</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;ajax__tab_inner&quot;</span>&gt;\n          <span class=\"tok-t\">&lt;button</span><span class=\"tok-k\"> type</span>=<span class=\"tok-s\">&quot;button&quot;</span><span class=\"tok-k\"> id</span>=<span class=\"tok-s\">&quot;..-tab-a&quot;</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;ajax__tab_tab nav-link active|disabled&quot;</span><span class=\"tok-k\"> role</span>=<span class=\"tok-s\">&quot;tab&quot;</span>\n                 <span class=\"tok-k\"> aria-selected</span>=<span class=\"tok-s\">&quot;true&quot;</span><span class=\"tok-k\"> aria-controls</span>=<span class=\"tok-s\">&quot;..-panel-a&quot;</span><span class=\"tok-k\"> tabindex</span>=<span class=\"tok-s\">&quot;0|-1&quot;</span> disabled&gt;Header<span class=\"tok-t\">&lt;/button</span>&gt;\n        <span class=\"tok-t\">&lt;/span</span>&gt;\n      <span class=\"tok-t\">&lt;/span</span>&gt;\n    <span class=\"tok-t\">&lt;/li</span>&gt;\n  <span class=\"tok-t\">&lt;/ul</span>&gt;\n  <span class=\"tok-t\">&lt;div</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;tab-content&quot;</span>&gt;\n    <span class=\"tok-t\">&lt;div</span><span class=\"tok-k\"> id</span>=<span class=\"tok-s\">&quot;..-panel-a&quot;</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;tab-pane active ajax__tab_body&quot;</span><span class=\"tok-k\"> role</span>=<span class=\"tok-s\">&quot;tabpanel&quot;</span><span class=\"tok-k\"> aria-labelledby</span>=<span class=\"tok-s\">&quot;..-tab-a&quot;</span>&gt;{tab.content}<span class=\"tok-t\">&lt;/div</span>&gt;   <span class=\"tok-c\">&lt;!-- active tab only --&gt;</span>\n    {children}\n  <span class=\"tok-t\">&lt;/div</span>&gt;\n<span class=\"tok-t\">&lt;/div</span>&gt;</code></pre></div>\n<p>The ids come from <code>useId()</code> plus the tab id, so several tab strips on one page stay unique. Emitted ARIA: <code>role=tablist|presentation|tab|tabpanel</code>, <code>aria-selected</code>, <code>aria-controls</code> (tab to panel), <code>aria-labelledby</code> (panel to tab), roving <code>tabindex</code>.</p>\n<p>The structure follows the AjaxControlToolkit <code>ajax__tab_*</code> classes that the kit's tab sheet (<code>.tb-&lt;theme&gt;</code>) styles. The header is a <code>ul</code>, not the <code>div</code> of the toolkit, and the kit's &quot;menu + panel&quot; tab variant is not emitted.</p>\n<hr>\n"},"react-10a-the-account-components":{"overview":"<p>Seven components draw the Login family and its siblings. They all take a <code>controller</code> (required) and a <code>className</code> that you set to the theme class, for example <code>lg-modern</code> (see section 14). They emit the ASP.NET-style markup the <code>lg-&lt;theme&gt;</code> sheet targets: a <code>table.lg-&lt;theme&gt;</code> for the forms, <code>a.lg-&lt;theme&gt;</code> for <code>WebFormsLoginStatus</code> and <code>span.lg-&lt;theme&gt;</code> for <code>WebFormsLoginName</code>. Each root also carries a fixed hook class (<code>wf-login</code>, <code>wf-change-password</code>, <code>wf-password-recovery</code>, <code>wf-create-user</code>, <code>wf-login-status</code>, <code>wf-login-name</code>, <code>wf-login-view</code>).</p>\n<div class=\"table-scroll\"><table><thead><tr><th>Component</th><th>Controller</th><th>Extra props (all optional)</th><th>Renders</th></tr></thead><tbody><tr><td><code>WebFormsLogin</code></td><td><code>LoginController</code></td><td><code>titleText</code>, <code>userNameLabelText</code>, <code>passwordLabelText</code>, <code>rememberMeText</code>, <code>loginButtonText</code>, <code>onLoggedIn(user)</code></td><td>Title, user name, password, remember-me (if <code>displayRememberMe</code>), failure text, Log In button, and the help / recovery / sign-up links when their URLs are set. Renders nothing while signed in unless <code>visibleWhenLoggedIn</code>.</td></tr><tr><td><code>WebFormsLoginStatus</code></td><td><code>LoginStatusController</code></td><td><code>onLoggedOut()</code></td><td>One link reading <code>loginText</code> or <code>logoutText</code>; clicking it while signed in calls <code>logout()</code>.</td></tr><tr><td><code>WebFormsLoginName</code></td><td><code>LoginNameController</code></td><td>none</td><td>A span with the formatted greeting; renders nothing when nobody is signed in.</td></tr><tr><td><code>WebFormsLoginView</code></td><td><code>LoginViewController&lt;React.ReactNode&gt;</code></td><td>none</td><td>The template of the active view: anonymous, the first matching role group, or logged-in.</td></tr><tr><td><code>WebFormsChangePassword</code></td><td><code>ChangePasswordController</code></td><td><code>titleText</code>, <code>successTitleText</code>, <code>currentPasswordLabelText</code>, <code>newPasswordLabelText</code>, <code>confirmPasswordLabelText</code>, <code>changeButtonText</code>, <code>continueButtonText</code>, <code>onContinue()</code></td><td>The three password fields, then the success view with a Continue button.</td></tr><tr><td><code>WebFormsPasswordRecovery</code></td><td><code>PasswordRecoveryController</code></td><td><code>titleText</code>, <code>userNameInstructionText</code>, <code>userNameLabelText</code>, <code>answerLabelText</code>, <code>submitButtonText</code></td><td>The user-name step, the optional question step, then the success text.</td></tr><tr><td><code>WebFormsCreateUserWizard</code></td><td><code>CreateUserWizardController</code></td><td><code>titleText</code>, <code>completeTitleText</code>, <code>completeText</code>, the label texts, <code>createButtonText</code>, <code>continueButtonText</code>, <code>displayQuestionAndAnswer</code>, <code>onCreated(user)</code>, <code>onContinue()</code></td><td>User name, password, confirm, e-mail (and question / answer), then the complete step.</td></tr></tbody></table></div>\n<p><strong>State.</strong> Each component keeps the controller's <code>getState()</code> snapshot in React state and refreshes it on <code>stateChanged</code>. <code>WebFormsLogin</code> also refreshes when <code>SecurityManager.currentUserChanged</code> fires, so it reappears after another control (for example <code>WebFormsLoginStatus</code>) signs the user out.</p>\n<p><strong>Validation messages.</strong> <code>ChangePasswordController.getState()</code> recomputes <code>validationErrors</code> on every call, so they exist while the user is still typing. The adapters show them only after the first submit attempt; a provider failure (<code>failureMessage</code>) is shown straight away.</p>\n<p><strong>Commands.</strong> Submit calls <code>login()</code>, <code>changePassword()</code>, <code>submitUserName()</code> / <code>submitAnswer()</code> or <code>createUser()</code> on the controller. Their cancellable events (<code>loggingIn</code>, <code>changingPassword</code>, <code>verifyingUser</code>, <code>creatingUser</code>) still run and can veto the action.</p>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">tsx</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-tsx\"><span class=\"tok-k\">const</span> provider = <span class=\"tok-k\">new</span> <span class=\"tok-t\">InMemoryAuthProvider</span>({ users: [{ userName: <span class=\"tok-s\">&quot;ann&quot;</span>, password: <span class=\"tok-s\">&quot;pw&quot;</span>, roles: [<span class=\"tok-s\">&quot;Admin&quot;</span>] }] });\n<span class=\"tok-k\">const</span> login = <span class=\"tok-k\">new</span> <span class=\"tok-t\">LoginController</span>({ provider });\n<span class=\"tok-k\">const</span> status = <span class=\"tok-k\">new</span> <span class=\"tok-t\">LoginStatusController</span>({ provider, loginPageUrl: <span class=\"tok-s\">&quot;#login&quot;</span> });\n<span class=\"tok-k\">const</span> name = <span class=\"tok-k\">new</span> <span class=\"tok-t\">LoginNameController</span>({ provider });\n\n&lt;<span class=\"tok-t\">WebFormsLogin</span> controller={login} className=<span class=\"tok-s\">&quot;lg-modern&quot;</span> /&gt;\n&lt;<span class=\"tok-t\">WebFormsLoginName</span> controller={name} className=<span class=\"tok-s\">&quot;lg-modern&quot;</span> /&gt;{<span class=\"tok-s\">&quot; &quot;</span>}\n&lt;<span class=\"tok-t\">WebFormsLoginStatus</span> controller={status} className=<span class=\"tok-s\">&quot;lg-modern&quot;</span> /&gt;</code></pre></div>\n<p>The runnable version is <code>samples/react/src/LoginDemo.tsx</code> and <code>AccountDemo.tsx</code>.</p>\n<hr>\n"},"react-examples":{"examples":"<p>All examples below are in one verified file (see section 12) and assume:</p>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">tsx</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-tsx\"><span class=\"tok-k\">interface</span> <span class=\"tok-t\">Product</span> { id: number; name: string; category: string; price: number; }\n<span class=\"tok-k\">const</span> products: <span class=\"tok-t\">Product</span>[] = [\n  { id: <span class=\"tok-n\">1</span>, name: <span class=\"tok-s\">&quot;Hammer&quot;</span>, category: <span class=\"tok-s\">&quot;Hardware&quot;</span>, price: <span class=\"tok-n\">12.5</span> },\n  { id: <span class=\"tok-n\">2</span>, name: <span class=\"tok-s\">&quot;Saw&quot;</span>, category: <span class=\"tok-s\">&quot;Hardware&quot;</span>, price: <span class=\"tok-n\">20</span> },\n  { id: <span class=\"tok-n\">3</span>, name: <span class=\"tok-s\">&quot;Paint&quot;</span>, category: <span class=\"tok-s\">&quot;Decor&quot;</span>, price: <span class=\"tok-n\">8</span> }\n];</code></pre></div>\n<ul class=\"aa-doc-index\"><li><a href=\"#/api/adapters/react-examples/examples/111-quick-start\">Quick start</a></li><li><a href=\"#/api/adapters/react-examples/examples/112-gridview-with-paging-sorting-and-inline-edit\">GridView with paging, sorting and inline edit</a></li><li><a href=\"#/api/adapters/react-examples/examples/113-custom-template-column-and-full-row-editor\">Custom template column and full-row editor</a></li><li><a href=\"#/api/adapters/react-examples/examples/114-repeater-with-edit-delete-and-add\">Repeater with edit, delete and add</a></li><li><a href=\"#/api/adapters/react-examples/examples/115-datalist-2-column-card-layout\">DataList (2-column card layout)</a></li><li><a href=\"#/api/adapters/react-examples/examples/116-modal-confirm-behavior-driven-and-controlled\">Modal confirm (behavior-driven and controlled)</a></li><li><a href=\"#/api/adapters/react-examples/examples/117-tabs-controller--children-and-inline-definitions\">Tabs (controller + children, and inline definitions)</a></li><li><a href=\"#/api/adapters/react-examples/examples/118-menu-breadcrumb-and-tree-from-a-site-map\">Menu, breadcrumb and tree from a site map</a></li></ul><h3 id=\"111-quick-start\">11.1 Quick start<a class=\"anchor\" href=\"#111-quick-start\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">tsx</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-tsx\"><span class=\"tok-k\">import</span> { useEffect, useMemo } <span class=\"tok-k\">from</span> <span class=\"tok-s\">&quot;react&quot;</span>;\n<span class=\"tok-k\">import</span> { <span class=\"tok-t\">GridViewController</span> } <span class=\"tok-k\">from</span> <span class=\"tok-s\">&quot;@wf-controls/core&quot;</span>;\n<span class=\"tok-k\">import</span> { <span class=\"tok-t\">WebFormsGridView</span> } <span class=\"tok-k\">from</span> <span class=\"tok-s\">&quot;@wf-controls/react&quot;</span>;\n\n<span class=\"tok-k\">export</span> <span class=\"tok-k\">function</span> <span class=\"tok-t\">QuickStart</span>() {\n  <span class=\"tok-k\">const</span> grid = <span class=\"tok-f\">useMemo</span>(() =&gt; <span class=\"tok-k\">new</span> <span class=\"tok-t\">GridViewController</span>&lt;<span class=\"tok-t\">Product</span>&gt;({\n    id: <span class=\"tok-s\">&quot;gv&quot;</span>, dataKeyField: <span class=\"tok-s\">&quot;id&quot;</span>, dataSource: products,\n    columns: [\n      { <span class=\"tok-k\">type</span>: <span class=\"tok-s\">&quot;bound&quot;</span>, key: <span class=\"tok-s\">&quot;name&quot;</span>, dataField: <span class=\"tok-s\">&quot;name&quot;</span>, headerText: <span class=\"tok-s\">&quot;Name&quot;</span>, sortable: <span class=\"tok-k\">true</span> },\n      { <span class=\"tok-k\">type</span>: <span class=\"tok-s\">&quot;bound&quot;</span>, key: <span class=\"tok-s\">&quot;price&quot;</span>, dataField: <span class=\"tok-s\">&quot;price&quot;</span>, headerText: <span class=\"tok-s\">&quot;Price&quot;</span>, sortable: <span class=\"tok-k\">true</span>,\n        format: (v) =&gt; <span class=\"tok-s\">`$${Number(v).toFixed(2)}`</span> }\n    ],\n    allowSorting: <span class=\"tok-k\">true</span>, allowPaging: <span class=\"tok-k\">true</span>, pageSize: <span class=\"tok-n\">2</span>\n  }), []);\n  <span class=\"tok-f\">useEffect</span>(() =&gt; { <span class=\"tok-k\">void</span> grid.<span class=\"tok-f\">dataBind</span>(); }, [grid]);\n  <span class=\"tok-k\">return</span> &lt;<span class=\"tok-t\">WebFormsGridView</span> controller={grid} className=<span class=\"tok-s\">&quot;table table-striped&quot;</span> /&gt;;\n}</code></pre></div>\n<p>Create the controller once (<code>useMemo</code>/<code>useRef</code>/module scope) -- a new instance on every render would reset all state.</p>\n<h3 id=\"112-gridview-with-paging-sorting-and-inline-edit\">11.2 GridView with paging, sorting and inline edit<a class=\"anchor\" href=\"#112-gridview-with-paging-sorting-and-inline-edit\" aria-label=\"Link to this section\">#</a></h3>\n<p>Header buttons sort, the pager pages, the actions column issues commands, and the default text-input editor is combined with Update/Cancel buttons supplied through <code>editCellTemplate</code> (returning <code>undefined</code> for other columns falls back to the built-in input).</p>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">tsx</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-tsx\"><span class=\"tok-k\">export</span> <span class=\"tok-k\">function</span> <span class=\"tok-t\">EditableGrid</span>() {\n  <span class=\"tok-k\">const</span> grid = <span class=\"tok-f\">useMemo</span>(() =&gt; {\n    <span class=\"tok-k\">const</span> g = <span class=\"tok-k\">new</span> <span class=\"tok-t\">GridViewController</span>&lt;<span class=\"tok-t\">Product</span>&gt;({\n      id: <span class=\"tok-s\">&quot;gvEdit&quot;</span>, dataKeyField: <span class=\"tok-s\">&quot;id&quot;</span>, dataSource: products,\n      allowPaging: <span class=\"tok-k\">true</span>, pageSize: <span class=\"tok-n\">2</span>, allowSorting: <span class=\"tok-k\">true</span>,\n      editRowCssClass: <span class=\"tok-s\">&quot;table-warning&quot;</span>, selectedRowCssClass: <span class=\"tok-s\">&quot;table-active&quot;</span>,\n      columns: [\n        { <span class=\"tok-k\">type</span>: <span class=\"tok-s\">&quot;bound&quot;</span>, key: <span class=\"tok-s\">&quot;name&quot;</span>, dataField: <span class=\"tok-s\">&quot;name&quot;</span>, headerText: <span class=\"tok-s\">&quot;Name&quot;</span>, sortable: <span class=\"tok-k\">true</span> },\n        { <span class=\"tok-k\">type</span>: <span class=\"tok-s\">&quot;bound&quot;</span>, key: <span class=\"tok-s\">&quot;category&quot;</span>, dataField: <span class=\"tok-s\">&quot;category&quot;</span>, headerText: <span class=\"tok-s\">&quot;Category&quot;</span> },\n        { <span class=\"tok-k\">type</span>: <span class=\"tok-s\">&quot;template&quot;</span>, key: <span class=\"tok-s\">&quot;actions&quot;</span>, headerText: <span class=\"tok-s\">&quot;&quot;</span> }\n      ]\n    });\n    g.rowUpdating.<span class=\"tok-f\">subscribe</span>((_s, e) =&gt; {\n      <span class=\"tok-k\">if</span> (e.values.name !== <span class=\"tok-k\">undefined</span> &amp;&amp; e.values.name.<span class=\"tok-f\">trim</span>() === <span class=\"tok-s\">&quot;&quot;</span>) e.cancel = <span class=\"tok-k\">true</span>;  <span class=\"tok-c\">// veto blank names</span>\n    });\n    <span class=\"tok-k\">return</span> g;\n  }, []);\n  <span class=\"tok-f\">useEffect</span>(() =&gt; { <span class=\"tok-k\">void</span> grid.<span class=\"tok-f\">dataBind</span>(); }, [grid]);\n  <span class=\"tok-k\">return</span> (\n    &lt;<span class=\"tok-t\">WebFormsGridView</span>\n      controller={grid}\n      template={(key, _row, index) =&gt; key === <span class=\"tok-s\">&quot;actions&quot;</span> ? (\n        &lt;&gt;\n          &lt;button onClick={() =&gt; <span class=\"tok-k\">void</span> grid.<span class=\"tok-f\">executeCommand</span>(index, <span class=\"tok-s\">&quot;Select&quot;</span>)}&gt;<span class=\"tok-t\">Select</span>&lt;/button&gt;\n          &lt;button onClick={() =&gt; <span class=\"tok-k\">void</span> grid.<span class=\"tok-f\">executeCommand</span>(index, <span class=\"tok-s\">&quot;Edit&quot;</span>)}&gt;<span class=\"tok-t\">Edit</span>&lt;/button&gt;\n          &lt;button onClick={() =&gt; <span class=\"tok-k\">void</span> grid.<span class=\"tok-f\">executeCommand</span>(index, <span class=\"tok-s\">&quot;Delete&quot;</span>)}&gt;<span class=\"tok-t\">Delete</span>&lt;/button&gt;\n        &lt;/&gt;\n      ) : <span class=\"tok-k\">null</span>}\n      editCellTemplate={(key, _row, _index, _values, _set, save, cancel) =&gt;\n        key === <span class=\"tok-s\">&quot;actions&quot;</span> ? (\n          &lt;&gt;\n            &lt;button onClick={() =&gt; <span class=\"tok-k\">void</span> <span class=\"tok-f\">save</span>()}&gt;<span class=\"tok-t\">Update</span>&lt;/button&gt;\n            &lt;button onClick={() =&gt; <span class=\"tok-k\">void</span> <span class=\"tok-f\">cancel</span>()}&gt;<span class=\"tok-t\">Cancel</span>&lt;/button&gt;\n          &lt;/&gt;\n        ) : <span class=\"tok-k\">undefined</span>}\n    /&gt;\n  );\n}</code></pre></div>\n<h3 id=\"113-custom-template-column-and-full-row-editor\">11.3 Custom template column and full-row editor<a class=\"anchor\" href=\"#113-custom-template-column-and-full-row-editor\" aria-label=\"Link to this section\">#</a></h3>\n<p>A <code>template</code> column (e.g. <code>{ type: &quot;template&quot;, key: &quot;badge&quot;, headerText: &quot;Tier&quot; }</code>) plus an <code>editTemplate</code> that owns its own form state in a child component:</p>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">tsx</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-tsx\"><span class=\"tok-k\">import</span> { useState } <span class=\"tok-k\">from</span> <span class=\"tok-s\">&quot;react&quot;</span>;\n\n<span class=\"tok-k\">function</span> <span class=\"tok-t\">RowEditor</span>(props: { row: <span class=\"tok-t\">Product</span>; save: (v: <span class=\"tok-t\">Partial</span>&lt;<span class=\"tok-t\">Product</span>&gt;) =&gt; <span class=\"tok-t\">Promise</span>&lt;boolean&gt;; cancel: () =&gt; <span class=\"tok-t\">Promise</span>&lt;boolean&gt; }) {\n  <span class=\"tok-k\">const</span> [name, setName] = <span class=\"tok-f\">useState</span>(props.row.name);\n  <span class=\"tok-k\">return</span> (\n    &lt;form onSubmit={(e) =&gt; { e.<span class=\"tok-f\">preventDefault</span>(); <span class=\"tok-k\">void</span> props.<span class=\"tok-f\">save</span>({ name }); }}&gt;\n      &lt;input value={name} onChange={(e) =&gt; <span class=\"tok-f\">setName</span>(e.target.value)} /&gt;\n      &lt;button <span class=\"tok-k\">type</span>=<span class=\"tok-s\">&quot;submit&quot;</span>&gt;<span class=\"tok-t\">Save</span>&lt;/button&gt;\n      &lt;button <span class=\"tok-k\">type</span>=<span class=\"tok-s\">&quot;button&quot;</span> onClick={() =&gt; <span class=\"tok-k\">void</span> props.<span class=\"tok-f\">cancel</span>()}&gt;<span class=\"tok-t\">Cancel</span>&lt;/button&gt;\n    &lt;/form&gt;\n  );\n}\n\n<span class=\"tok-k\">export</span> <span class=\"tok-k\">function</span> <span class=\"tok-t\">GridWithRowEditor</span>({ grid }: { grid: <span class=\"tok-t\">GridViewController</span>&lt;<span class=\"tok-t\">Product</span>&gt; }) {\n  <span class=\"tok-k\">return</span> (\n    &lt;<span class=\"tok-t\">WebFormsGridView</span> controller={grid}\n      template={(key, row, index) =&gt; key === <span class=\"tok-s\">&quot;badge&quot;</span>\n        ? &lt;span className=<span class=\"tok-s\">&quot;badge&quot;</span>&gt;{row.price &gt; <span class=\"tok-n\">10</span> ? <span class=\"tok-s\">&quot;Premium&quot;</span> : <span class=\"tok-s\">&quot;Basic&quot;</span>} #{index}&lt;/span&gt; : <span class=\"tok-k\">null</span>}\n      editTemplate={(row, _i, save, cancel) =&gt; &lt;<span class=\"tok-t\">RowEditor</span> row={row} save={save} cancel={cancel} /&gt;} /&gt;\n  );\n}</code></pre></div>\n<h3 id=\"114-repeater-with-edit-delete-and-add\">11.4 Repeater with edit, delete and add<a class=\"anchor\" href=\"#114-repeater-with-edit-delete-and-add\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">tsx</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-tsx\"><span class=\"tok-k\">export</span> <span class=\"tok-k\">function</span> <span class=\"tok-t\">RepeaterDemo</span>() {\n  <span class=\"tok-k\">const</span> rep = <span class=\"tok-f\">useMemo</span>(() =&gt; <span class=\"tok-k\">new</span> <span class=\"tok-t\">RepeaterController</span>&lt;<span class=\"tok-t\">Product</span>&gt;({\n    id: <span class=\"tok-s\">&quot;rp&quot;</span>, dataKeyField: <span class=\"tok-s\">&quot;id&quot;</span>, dataSource: products, allowUserToAddItems: <span class=\"tok-k\">true</span>,\n    allowUserToDeleteItems: <span class=\"tok-k\">true</span>, itemHeaderVisible: <span class=\"tok-k\">false</span>, emptyText: <span class=\"tok-s\">&quot;Nothing here&quot;</span>\n  }), []);\n  <span class=\"tok-f\">useEffect</span>(() =&gt; { <span class=\"tok-k\">void</span> rep.<span class=\"tok-f\">dataBind</span>(); }, [rep]);\n  <span class=\"tok-k\">return</span> (\n    &lt;<span class=\"tok-t\">WebFormsRepeater</span> controller={rep}\n      createItem={() =&gt; ({ id: <span class=\"tok-t\">Date</span>.<span class=\"tok-f\">now</span>(), name: <span class=\"tok-s\">&quot;New&quot;</span>, category: <span class=\"tok-s\">&quot;&quot;</span>, price: <span class=\"tok-n\">0</span> })}\n      headerTemplate={() =&gt; &lt;h3&gt;<span class=\"tok-t\">Products</span>&lt;/h3&gt;}\n      itemTemplate={(item, i, command) =&gt; (\n        &lt;div&gt;{item.name} &lt;button onClick={() =&gt; <span class=\"tok-k\">void</span> <span class=\"tok-f\">command</span>(<span class=\"tok-s\">&quot;Edit&quot;</span>)}&gt;<span class=\"tok-t\">Edit</span>&lt;/button&gt;\n          &lt;button onClick={() =&gt; <span class=\"tok-k\">void</span> rep.<span class=\"tok-f\">deleteItem</span>(i)}&gt;<span class=\"tok-t\">Remove</span>&lt;/button&gt;&lt;/div&gt;)}\n      editItemTemplate={(item, i, save, cancel) =&gt; (\n        &lt;div&gt;#{i} &lt;button onClick={() =&gt; <span class=\"tok-k\">void</span> <span class=\"tok-f\">save</span>({ name: item.name + <span class=\"tok-s\">&quot;!&quot;</span> })}&gt;<span class=\"tok-t\">Save</span>&lt;/button&gt;\n          &lt;button onClick={() =&gt; <span class=\"tok-k\">void</span> <span class=\"tok-f\">cancel</span>()}&gt;<span class=\"tok-t\">Cancel</span>&lt;/button&gt;&lt;/div&gt;)}\n      separatorTemplate={() =&gt; &lt;hr /&gt;} /&gt;\n  );\n}</code></pre></div>\n<p>With <code>itemHeaderVisible: false</code> the built-in Delete button is hidden, so the item template provides &quot;Remove&quot; via <code>controller.deleteItem</code> (because the Repeater's <code>&quot;Delete&quot;</code> command is not handled).</p>\n<h3 id=\"115-datalist-2-column-card-layout\">11.5 DataList (2-column card layout)<a class=\"anchor\" href=\"#115-datalist-2-column-card-layout\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">tsx</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-tsx\"><span class=\"tok-k\">export</span> <span class=\"tok-k\">function</span> <span class=\"tok-t\">DataListDemo</span>() {\n  <span class=\"tok-k\">const</span> list = <span class=\"tok-f\">useMemo</span>(() =&gt; <span class=\"tok-k\">new</span> <span class=\"tok-t\">DataListController</span>&lt;<span class=\"tok-t\">Product</span>&gt;({\n    id: <span class=\"tok-s\">&quot;dl&quot;</span>, dataKeyField: <span class=\"tok-s\">&quot;id&quot;</span>, dataSource: products, repeatColumns: <span class=\"tok-n\">2</span>,\n    repeatDirection: <span class=\"tok-s\">&quot;Horizontal&quot;</span>, showHeader: <span class=\"tok-k\">true</span>, showFooter: <span class=\"tok-k\">true</span>\n  }), []);\n  <span class=\"tok-f\">useEffect</span>(() =&gt; { <span class=\"tok-k\">void</span> list.<span class=\"tok-f\">dataBind</span>(); }, [list]);\n  <span class=\"tok-k\">return</span> (\n    &lt;<span class=\"tok-t\">WebFormsDataList</span> controller={list}\n      headerTemplate={() =&gt; &lt;strong&gt;<span class=\"tok-t\">Catalog</span>&lt;/strong&gt;}\n      footerTemplate={() =&gt; &lt;em&gt;{list.itemCount} items&lt;/em&gt;}\n      itemTemplate={(p, _i, command) =&gt; &lt;div&gt;{p.name} &lt;button onClick={() =&gt; <span class=\"tok-k\">void</span> <span class=\"tok-f\">command</span>(<span class=\"tok-s\">&quot;Select&quot;</span>)}&gt;<span class=\"tok-t\">Pick</span>&lt;/button&gt;&lt;/div&gt;}\n      selectedItemTemplate={(p, _i, command) =&gt; &lt;div&gt;&lt;b&gt;{p.name}&lt;/b&gt; &lt;button onClick={() =&gt; <span class=\"tok-k\">void</span> <span class=\"tok-f\">command</span>(<span class=\"tok-s\">&quot;Edit&quot;</span>)}&gt;<span class=\"tok-t\">Edit</span>&lt;/button&gt;&lt;/div&gt;}\n      editItemTemplate={(p, _i, save, cancel) =&gt; (\n        &lt;div&gt;&lt;button onClick={() =&gt; <span class=\"tok-k\">void</span> <span class=\"tok-f\">save</span>({ price: p.price + <span class=\"tok-n\">1</span> })}&gt;+<span class=\"tok-n\">1</span>&lt;/button&gt;\n          &lt;button onClick={() =&gt; <span class=\"tok-k\">void</span> <span class=\"tok-f\">cancel</span>()}&gt;x&lt;/button&gt;&lt;/div&gt;)}\n      emptyTemplate={() =&gt; &lt;p&gt;<span class=\"tok-t\">Empty</span>&lt;/p&gt;} /&gt;\n  );\n}</code></pre></div>\n<h3 id=\"116-modal-confirm-behavior-driven-and-controlled\">11.6 Modal confirm (behavior-driven and controlled)<a class=\"anchor\" href=\"#116-modal-confirm-behavior-driven-and-controlled\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">tsx</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-tsx\"><span class=\"tok-k\">import</span> { useRef } <span class=\"tok-k\">from</span> <span class=\"tok-s\">&quot;react&quot;</span>;\n<span class=\"tok-k\">import</span> { <span class=\"tok-t\">ModalBehavior</span> } <span class=\"tok-k\">from</span> <span class=\"tok-s\">&quot;@wf-controls/core&quot;</span>;\n<span class=\"tok-k\">import</span> { <span class=\"tok-t\">WebFormsModal</span> } <span class=\"tok-k\">from</span> <span class=\"tok-s\">&quot;@wf-controls/react&quot;</span>;\n\n<span class=\"tok-k\">export</span> <span class=\"tok-k\">function</span> <span class=\"tok-t\">ConfirmDelete</span>({ grid }: { grid: <span class=\"tok-t\">GridViewController</span>&lt;<span class=\"tok-t\">Product</span>&gt; }) {\n  <span class=\"tok-k\">const</span> pending = <span class=\"tok-f\">useRef</span>(-<span class=\"tok-n\">1</span>);\n  <span class=\"tok-k\">const</span> modal = <span class=\"tok-f\">useMemo</span>(() =&gt; <span class=\"tok-k\">new</span> <span class=\"tok-t\">ModalBehavior</span>({\n    id: <span class=\"tok-s\">&quot;confirm&quot;</span>,\n    onOk: <span class=\"tok-k\">async</span> () =&gt; { <span class=\"tok-k\">if</span> (pending.current &gt;= <span class=\"tok-n\">0</span>) <span class=\"tok-k\">await</span> grid.<span class=\"tok-f\">deleteRow</span>(pending.current); pending.current = -<span class=\"tok-n\">1</span>; },\n    onCancel: () =&gt; { pending.current = -<span class=\"tok-n\">1</span>; }\n  }), [grid]);\n  <span class=\"tok-k\">return</span> (\n    &lt;&gt;\n      &lt;<span class=\"tok-t\">WebFormsGridView</span> controller={grid}\n        template={(_k, _r, index) =&gt; (\n          &lt;button onClick={() =&gt; { pending.current = index; <span class=\"tok-k\">void</span> modal.<span class=\"tok-f\">show</span>(); }}&gt;<span class=\"tok-t\">Delete</span>&lt;/button&gt;)} /&gt;\n      &lt;<span class=\"tok-t\">WebFormsModal</span> behavior={modal} title=<span class=\"tok-s\">&quot;Delete?&quot;</span> okText=<span class=\"tok-s\">&quot;Delete&quot;</span> cancelText=<span class=\"tok-s\">&quot;Keep&quot;</span>&gt;\n        <span class=\"tok-t\">Delete</span> the selected row?\n      &lt;/<span class=\"tok-t\">WebFormsModal</span>&gt;\n    &lt;/&gt;\n  );\n}\n\n<span class=\"tok-k\">export</span> <span class=\"tok-k\">function</span> <span class=\"tok-t\">ControlledModal</span>() {\n  <span class=\"tok-k\">const</span> [open, setOpen] = <span class=\"tok-f\">useState</span>(<span class=\"tok-k\">false</span>);\n  <span class=\"tok-k\">return</span> (\n    &lt;&gt;\n      &lt;button onClick={() =&gt; <span class=\"tok-f\">setOpen</span>(<span class=\"tok-k\">true</span>)}&gt;<span class=\"tok-t\">Open</span>&lt;/button&gt;\n      &lt;<span class=\"tok-t\">WebFormsModal</span> isOpen={open} title=<span class=\"tok-s\">&quot;Hello&quot;</span> onClose={() =&gt; <span class=\"tok-f\">setOpen</span>(<span class=\"tok-k\">false</span>)} onOk={() =&gt; <span class=\"tok-f\">setOpen</span>(<span class=\"tok-k\">false</span>)}&gt;<span class=\"tok-t\">Body</span>&lt;/<span class=\"tok-t\">WebFormsModal</span>&gt;\n    &lt;/&gt;\n  );\n}</code></pre></div>\n<p>The pending row index is kept in a <code>useRef</code> so the <code>ModalBehavior</code> instance stays stable. <strong>Do not recreate the behavior per render</strong>: <code>WebFormsModal</code> takes its initial open state from <code>behavior.isOpen</code> only on first mount, so a <code>show()</code> on an old instance would never reach a new instance's subscriptions and the dialog would never open. <code>rowDeleting</code> on the grid can still veto the delete.</p>\n<h3 id=\"117-tabs-controller--children-and-inline-definitions\">11.7 Tabs (controller + children, and inline definitions)<a class=\"anchor\" href=\"#117-tabs-controller--children-and-inline-definitions\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">tsx</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-tsx\"><span class=\"tok-k\">import</span> { useReducer } <span class=\"tok-k\">from</span> <span class=\"tok-s\">&quot;react&quot;</span>;\n<span class=\"tok-k\">import</span> { <span class=\"tok-t\">TabsController</span> } <span class=\"tok-k\">from</span> <span class=\"tok-s\">&quot;@wf-controls/core&quot;</span>;\n<span class=\"tok-k\">import</span> { <span class=\"tok-t\">WebFormsTabs</span>, <span class=\"tok-k\">type</span> <span class=\"tok-t\">TabDefinition</span> } <span class=\"tok-k\">from</span> <span class=\"tok-s\">&quot;@wf-controls/react&quot;</span>;\n\n<span class=\"tok-k\">export</span> <span class=\"tok-k\">function</span> <span class=\"tok-t\">TabsDemo</span>() {\n  <span class=\"tok-k\">const</span> tabs = <span class=\"tok-f\">useMemo</span>(() =&gt; <span class=\"tok-k\">new</span> <span class=\"tok-t\">TabsController</span>({\n    tabs: [{ id: <span class=\"tok-s\">&quot;a&quot;</span>, headerText: <span class=\"tok-s\">&quot;Details&quot;</span> }, { id: <span class=\"tok-s\">&quot;b&quot;</span>, headerText: <span class=\"tok-s\">&quot;History&quot;</span> }, { id: <span class=\"tok-s\">&quot;c&quot;</span>, headerText: <span class=\"tok-s\">&quot;Locked&quot;</span>, enabled: <span class=\"tok-k\">false</span> }]\n  }), []);\n  <span class=\"tok-k\">const</span> [, refresh] = <span class=\"tok-f\">useReducer</span>((n: number) =&gt; n + <span class=\"tok-n\">1</span>, <span class=\"tok-n\">0</span>);\n  <span class=\"tok-f\">useEffect</span>(() =&gt; tabs.activeTabChanged.<span class=\"tok-f\">subscribe</span>(() =&gt; <span class=\"tok-f\">refresh</span>()), [tabs]);  <span class=\"tok-c\">// re-render parent so `children` update</span>\n  <span class=\"tok-k\">return</span> (\n    &lt;<span class=\"tok-t\">WebFormsTabs</span> controller={tabs} onActiveTabChanged={(i) =&gt; console.<span class=\"tok-f\">log</span>(i)}&gt;\n      {tabs.activeTabIndex === <span class=\"tok-n\">0</span> &amp;&amp; &lt;p&gt;<span class=\"tok-t\">Details</span> body&lt;/p&gt;}\n      {tabs.activeTabIndex === <span class=\"tok-n\">1</span> &amp;&amp; &lt;p&gt;<span class=\"tok-t\">History</span> body&lt;/p&gt;}\n    &lt;/<span class=\"tok-t\">WebFormsTabs</span>&gt;\n  );\n}\n\n<span class=\"tok-k\">export</span> <span class=\"tok-k\">function</span> <span class=\"tok-t\">TabsInline</span>() {\n  <span class=\"tok-k\">const</span> defs: <span class=\"tok-t\">TabDefinition</span>[] = [\n    { id: <span class=\"tok-s\">&quot;x&quot;</span>, headerText: <span class=\"tok-s\">&quot;One&quot;</span>, content: &lt;p&gt;<span class=\"tok-t\">One</span>&lt;/p&gt; },\n    { id: <span class=\"tok-s\">&quot;y&quot;</span>, headerText: <span class=\"tok-s\">&quot;Two&quot;</span>, content: &lt;p&gt;<span class=\"tok-t\">Two</span>&lt;/p&gt; }\n  ];\n  <span class=\"tok-k\">const</span> [idx, setIdx] = <span class=\"tok-f\">useState</span>(<span class=\"tok-n\">0</span>);\n  <span class=\"tok-k\">return</span> &lt;<span class=\"tok-t\">WebFormsTabs</span> tabs={defs} activeTabIndex={idx} onActiveTabChanged={setIdx} /&gt;;\n}</code></pre></div>\n<h3 id=\"118-menu-breadcrumb-and-tree-from-a-site-map\">11.8 Menu, breadcrumb and tree from a site map<a class=\"anchor\" href=\"#118-menu-breadcrumb-and-tree-from-a-site-map\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">tsx</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-tsx\"><span class=\"tok-k\">import</span> {\n  <span class=\"tok-t\">SiteMapDataSource</span>, <span class=\"tok-t\">SiteMapPathController</span>, <span class=\"tok-t\">MenuController</span>, <span class=\"tok-t\">TreeViewController</span>, <span class=\"tok-t\">MenuItem</span>,\n  <span class=\"tok-k\">type</span> <span class=\"tok-t\">TreeNode</span> <span class=\"tok-k\">as</span> <span class=\"tok-t\">CoreTreeNode</span>\n} <span class=\"tok-k\">from</span> <span class=\"tok-s\">&quot;@wf-controls/core&quot;</span>;\n<span class=\"tok-k\">import</span> { <span class=\"tok-t\">NavigationMenu</span>, <span class=\"tok-t\">Breadcrumb</span>, <span class=\"tok-t\">TreeView</span>, <span class=\"tok-k\">type</span> <span class=\"tok-t\">TreeNode</span>, <span class=\"tok-k\">type</span> <span class=\"tok-t\">BreadcrumbItem</span> } <span class=\"tok-k\">from</span> <span class=\"tok-s\">&quot;@wf-controls/react&quot;</span>;\n\n<span class=\"tok-k\">const</span> siteMap = <span class=\"tok-k\">new</span> <span class=\"tok-t\">SiteMapDataSource</span>({\n  id: <span class=\"tok-s\">&quot;sm&quot;</span>,\n  siteMap: { key: <span class=\"tok-s\">&quot;home&quot;</span>, url: <span class=\"tok-s\">&quot;/&quot;</span>, title: <span class=\"tok-s\">&quot;Home&quot;</span>, childNodes: [\n    { key: <span class=\"tok-s\">&quot;prod&quot;</span>, url: <span class=\"tok-s\">&quot;/products&quot;</span>, title: <span class=\"tok-s\">&quot;Products&quot;</span>, childNodes: [{ key: <span class=\"tok-s\">&quot;hw&quot;</span>, url: <span class=\"tok-s\">&quot;/products/hw&quot;</span>, title: <span class=\"tok-s\">&quot;Hardware&quot;</span> }] },\n    { key: <span class=\"tok-s\">&quot;about&quot;</span>, url: <span class=\"tok-s\">&quot;/about&quot;</span>, title: <span class=\"tok-s\">&quot;About&quot;</span> }\n  ] }\n});\n\n<span class=\"tok-k\">function</span> <span class=\"tok-f\">toAdapterNode</span>(n: <span class=\"tok-t\">CoreTreeNode</span>): <span class=\"tok-t\">TreeNode</span> {\n  <span class=\"tok-k\">return</span> { text: n.text, value: n.value, navigateUrl: n.navigateUrl || <span class=\"tok-k\">undefined</span>,\n    expanded: n.expanded, children: n.childNodes.<span class=\"tok-f\">map</span>(toAdapterNode) };\n}\n\n<span class=\"tok-k\">export</span> <span class=\"tok-k\">function</span> <span class=\"tok-t\">SiteNav</span>({ current }: { current: string }) {\n  <span class=\"tok-k\">const</span> [items, setItems] = useState&lt;<span class=\"tok-t\">MenuItem</span>[]&gt;([]);\n  <span class=\"tok-k\">const</span> [crumbs, setCrumbs] = useState&lt;<span class=\"tok-t\">BreadcrumbItem</span>[]&gt;([]);\n  <span class=\"tok-k\">const</span> [nodes, setNodes] = useState&lt;<span class=\"tok-t\">TreeNode</span>[]&gt;([]);\n  <span class=\"tok-f\">useEffect</span>(() =&gt; {\n    <span class=\"tok-k\">void</span> (<span class=\"tok-k\">async</span> () =&gt; {\n      <span class=\"tok-k\">const</span> menu = <span class=\"tok-k\">new</span> <span class=\"tok-t\">MenuController</span>({ id: <span class=\"tok-s\">&quot;m&quot;</span>, orientation: <span class=\"tok-s\">&quot;Horizontal&quot;</span>, dataSource: siteMap });\n      <span class=\"tok-k\">await</span> menu.<span class=\"tok-f\">dataBind</span>();\n      <span class=\"tok-f\">setItems</span>(menu.items[<span class=\"tok-n\">0</span>]?.childItems ?? []);        <span class=\"tok-c\">// SiteMapDataSource returns the root; show its children</span>\n      <span class=\"tok-k\">const</span> path = <span class=\"tok-k\">new</span> <span class=\"tok-t\">SiteMapPathController</span>({ id: <span class=\"tok-s\">&quot;p&quot;</span>, siteMapProvider: siteMap });\n      <span class=\"tok-k\">const</span> list = <span class=\"tok-k\">await</span> path.<span class=\"tok-f\">dataBind</span>(current);\n      <span class=\"tok-f\">setCrumbs</span>(list.<span class=\"tok-f\">map</span>((i) =&gt; i.isLink ? { text: i.text, url: i.url } : { text: i.text }));\n      <span class=\"tok-k\">const</span> tree = <span class=\"tok-k\">new</span> <span class=\"tok-t\">TreeViewController</span>({ id: <span class=\"tok-s\">&quot;t&quot;</span>, dataSource: siteMap, expandDepth: <span class=\"tok-n\">2</span> });\n      <span class=\"tok-k\">await</span> tree.<span class=\"tok-f\">dataBind</span>();\n      <span class=\"tok-f\">setNodes</span>(tree.nodes.<span class=\"tok-f\">map</span>(toAdapterNode));\n    })();\n  }, [current]);\n  <span class=\"tok-k\">return</span> (\n    &lt;&gt;\n      &lt;<span class=\"tok-t\">NavigationMenu</span> items={items} orientation=<span class=\"tok-s\">&quot;horizontal&quot;</span> onItemClick={(i) =&gt; console.<span class=\"tok-f\">log</span>(i.text)} /&gt;\n      &lt;<span class=\"tok-t\">Breadcrumb</span> items={crumbs} onItemClick={(i) =&gt; console.<span class=\"tok-f\">log</span>(i.url)} /&gt;\n      &lt;<span class=\"tok-t\">TreeView</span> nodes={nodes} onNodeClick={(n) =&gt; console.<span class=\"tok-f\">log</span>(n.text)} onNodeToggle={(n, open) =&gt; console.<span class=\"tok-f\">log</span>(n.text, open)} /&gt;\n    &lt;/&gt;\n  );\n}</code></pre></div>\n<p><code>exactOptionalPropertyTypes</code> is on in this repo: <code>navigateUrl: x || undefined</code> type-checks because the adapter props declare <code>| undefined</code> explicitly. The <code>SiteMapDataSource.select()</code> result is the root node when <code>showStartingNode</code> is true (default), hence <code>menu.items[0]?.childItems</code>.</p>\n<p>This example uses the plain-data mode. Since the components accept controllers, the conversion code can be dropped: <code>&lt;NavigationMenu controller={menu} className=&quot;mn-modern&quot; /&gt;</code>, <code>&lt;Breadcrumb controller={path} className=&quot;nv-modern&quot; /&gt;</code> and <code>&lt;TreeView controller={tree} className=&quot;tv-modern&quot; /&gt;</code> (after the same <code>dataBind()</code> calls) render the same trees with flyouts, <code>pathDirection</code>, checkboxes and selection handled by the controllers.</p>\n<hr>\n"},"react-known-issues-and-inconsistencies-v1-0-0":{"overview":"<ul><li><code>NavigationMenu</code> <code>orientation</code> is lower-case, core <code>MenuOrientation</code> is title-case. A <code>controller</code> overrides it.</li><li><code>Breadcrumb</code> renders demo data when neither <code>items</code> nor <code>controller</code> is given.</li><li><code>TreeView</code> plain mode has no checkboxes, and <code>onNodeClick</code> / <code>onNodeToggle</code> are not called in controller mode; use the controller events there.</li><li><code>RepeaterController.executeCommand</code> does not handle <code>&quot;Delete&quot;</code>, while <code>GridViewController</code> and <code>DataListController</code> do.</li><li><code>NavigationMenu.onItemClick</code> is typed <code>(item: any) =&gt; void</code>.</li><li>The kit's GridView pager selector <code>.pager table</code> (a nested table) and <code>.ajax__tab_hover</code> are not produced, and the &quot;menu + panel&quot; tab variant is not emitted. See <a href=\"#/api/guides/issues-needs-your-attention-first\">Known issues</a>.</li><li>Calendar, Accordion and AdRotator (core-only, no React adapter) are not themed; the Validation sheet exists but has no adapter, so you add its classes to your own markup. The Login sheet is drawn by the account components (section 10A). Modal, Repeater, DataList and grid edit rows are themed (section 14).</li><li><code>validation-input-highlight.js</code> needs the ASP.NET <code>WebUIValidation</code> globals, so in React toggle the <code>is-invalid</code> class on your inputs yourself.</li></ul>\n<hr>\n"},"react-styling-with-wf-controls-styles":{"overview":"<p><code>@wf-controls/styles</code> is a framework-neutral CSS package: five themes (<code>modern</code>, <code>dark</code>, <code>classic</code>, <code>minimal</code>, <code>corporate</code>) for GridView (<code>gv-</code>, plus the <code>gv-&lt;t&gt;-edit.css</code> sheet for edit and insert rows), the Login family (<code>lg-</code>), Menu (<code>mn-</code>), TreeView (<code>tv-</code>), Tabs (<code>tb-</code>), Navigation (<code>nv-</code>: SiteMapPath/Breadcrumb, DataPager, link list), Validation (<code>vl-</code>) and three added families: popup dialog / Modal (<code>md-</code>), Repeater (<code>rp-</code>) and DataList (<code>dl-</code>). It does not cover Calendar, Accordion or AdRotator. The full markup contract is in <code>packages/styles/README.md</code>.</p>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">bash</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-bash\"><span class=\"tok-f\">npm</span> install @wf-controls/styles</code></pre></div>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">ts</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-ts\"><span class=\"tok-c\">// once, in your entry file (Vite, webpack, Next)</span>\n<span class=\"tok-k\">import</span> <span class=\"tok-s\">&quot;@wf-controls/styles/bundles/modern-full.css&quot;</span>;  <span class=\"tok-c\">// all ten families for one theme (kit + modal + repeater + datalist + grid edit rows)</span>\n<span class=\"tok-c\">// modern-all.css is the kit's seven families only (no md-/rp-/dl-, no edit-row sheet)</span>\n<span class=\"tok-k\">import</span> <span class=\"tok-s\">&quot;@wf-controls/styles/adapters.css&quot;</span>;             <span class=\"tok-c\">// structural glue, AFTER the theme</span>\n<span class=\"tok-c\">// one family only: import &quot;@wf-controls/styles/gridview/gv-dark.css&quot;;</span></code></pre></div>\n<p>Then give each control the theme class:</p>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">tsx</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-tsx\"><span class=\"tok-k\">const</span> grid = <span class=\"tok-k\">new</span> <span class=\"tok-t\">GridViewController</span>&lt;<span class=\"tok-t\">Employee</span>&gt;({ id: <span class=\"tok-s\">&quot;g&quot;</span>, dataKeyField: <span class=\"tok-s\">&quot;id&quot;</span>, columns,\n  allowPaging: <span class=\"tok-k\">true</span>, pageSize: <span class=\"tok-n\">5</span>, cssClass: <span class=\"tok-s\">&quot;gv-modern&quot;</span> });   <span class=\"tok-c\">// table.gv-modern</span>\n\n&lt;<span class=\"tok-t\">WebFormsGridView</span> controller={grid} /&gt;\n&lt;<span class=\"tok-t\">NavigationMenu</span> controller={menu} className=<span class=\"tok-s\">&quot;mn-modern&quot;</span> /&gt;\n&lt;<span class=\"tok-t\">NavigationMenu</span> items={items} orientation=<span class=\"tok-s\">&quot;vertical&quot;</span> className=<span class=\"tok-s\">&quot;mn-modern&quot;</span> /&gt;   {<span class=\"tok-c\">/* mn-vertical is added for you */</span>}\n&lt;<span class=\"tok-t\">TreeView</span> controller={tree} className=<span class=\"tok-s\">&quot;tv-modern&quot;</span> /&gt;\n&lt;<span class=\"tok-t\">Breadcrumb</span> controller={path} className=<span class=\"tok-s\">&quot;nv-modern&quot;</span> /&gt;\n&lt;<span class=\"tok-t\">WebFormsTabs</span> controller={tabs} className=<span class=\"tok-s\">&quot;tb-modern&quot;</span>&gt;...&lt;/<span class=\"tok-t\">WebFormsTabs</span>&gt;\n&lt;<span class=\"tok-t\">WebFormsRepeater</span> controller={rep} className=<span class=\"tok-s\">&quot;rp-modern&quot;</span> itemTemplate={...} /&gt;\n&lt;<span class=\"tok-t\">WebFormsDataList</span> controller={list} className=<span class=\"tok-s\">&quot;dl-modern&quot;</span> itemTemplate={...} /&gt;\n&lt;<span class=\"tok-t\">WebFormsModal</span> behavior={modal} className=<span class=\"tok-s\">&quot;md-modern&quot;</span> title=<span class=\"tok-s\">&quot;Delete?&quot;</span>&gt;...&lt;/<span class=\"tok-t\">WebFormsModal</span>&gt;</code></pre></div>\n<p><strong>Edit templates.</strong> The kit itself only styles <code>text</code> and <code>date</code> inputs inside a GridView <code>tr.edit</code> / <code>tr.footer</code>. The <code>gv-&lt;t&gt;-edit.css</code> sheet (included in <code>&lt;theme&gt;-full.css</code>) adds <code>select</code>, <code>textarea</code>, <code>number</code> / <code>email</code> / untyped <code>input</code>, checkbox, label and button there, so an <code>editTemplate</code> that uses those controls is themed. Use <code>modern-full.css</code> (or import <code>gridview/gv-modern-edit.css</code> next to <code>gv-modern.css</code>); with <code>modern-all.css</code> only text and date inputs are themed in edit rows. Likewise <code>.wf-item.edit</code> (Repeater) and the DataList edit item are themed by <code>rp-</code> / <code>dl-</code>.</p>\n<p><strong>Switching theme:</strong> load the bundles you want to offer and change the one class on each control root (<code>gv-modern</code> to <code>gv-dark</code>, <code>mn-modern</code> to <code>mn-dark</code>, and so on). Every rule is scoped to its class, so several themes can be loaded at once.</p>\n<p><strong><code>adapters.css</code></strong> carries no colours or sizes. It resets what the kit did not expect from list and button markup: tree bullets and toggle buttons, tab buttons, absolutely positioned menu flyouts, and the disabled pager link (the kit paints every <code>.pager span</code> as the current page). Load it after the theme.</p>\n","option-to-class-table":"<h3 id=\"option-to-class-table\">Option-to-class table<a class=\"anchor\" href=\"#option-to-class-table\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Controller option / prop</th><th>Value for the kit</th><th>What the adapter does</th></tr></thead><tbody><tr><td>GridView <code>cssClass</code> / <code>tableCssClass</code> / <code>className</code> prop</td><td><code>gv-&lt;t&gt;</code></td><td>on <code>table</code> (<code>cssClass</code> also on the wrapper <code>div</code>)</td></tr><tr><td><code>rowCssClass</code> / <code>alternatingRowCssClass</code></td><td>none needed; add your own class for zebra</td><td>on <code>tr</code> (alternating on odd page positions)</td></tr><tr><td><code>selectedRowCssClass</code></td><td>none needed</td><td><code>tr.selected</code> + your class; <code>aria-selected=&quot;true&quot;</code></td></tr><tr><td><code>editRowCssClass</code></td><td>none needed</td><td><code>tr.edit</code> + your class; <code>aria-selected=&quot;true&quot;</code> when it is the selected row</td></tr><tr><td><code>headerCssClass</code></td><td>none needed</td><td>on <code>thead</code> and its <code>tr</code></td></tr><tr><td><code>footerCssClass</code></td><td>none needed</td><td><code>tr.footer</code> + your class (needs <code>showFooter</code>)</td></tr><tr><td><code>pagerCssClass</code></td><td>none needed</td><td><code>tr.pager</code> + your class (needs <code>allowPaging</code>)</td></tr><tr><td><code>emptyDataText</code></td><td>--</td><td><code>tr.empty &gt; td.empty</code></td></tr><tr><td>Menu / NavigationMenu <code>className</code></td><td><code>mn-&lt;t&gt;</code></td><td>root <code>div[role=navigation]</code>; <code>mn-vertical</code> added for vertical</td></tr><tr><td>TreeView <code>className</code></td><td><code>tv-&lt;t&gt;</code></td><td>root <code>div.wf-treeview</code>; labels <code>a.root/parent/leaf(.selected)</code></td></tr><tr><td>Tabs <code>className</code></td><td><code>tb-&lt;t&gt;</code></td><td>wrapper <code>div.wf-tabs</code>; <code>ajax__tab_*</code> inside</td></tr><tr><td>Breadcrumb <code>className</code></td><td><code>nv-&lt;t&gt;</code></td><td>inner <code>span</code>; <code>a</code>, <code>span.sep[data-separator]</code>, <code>span.current</code></td></tr><tr><td>Login family, validators</td><td><code>lg-&lt;t&gt;</code>, <code>vl-&lt;t&gt;</code></td><td>no React adapter; add the class to your own markup</td></tr><tr><td>Repeater <code>className</code> / <code>cssClass</code></td><td><code>rp-&lt;t&gt;</code></td><td>root <code>div.wf-repeater</code>; items <code>div.wf-item</code> (+ <code>alt</code>, <code>active</code>, <code>edit</code>), <code>button.add</code>, <code>header.wf-item-header</code>, <code>div.empty</code></td></tr><tr><td>DataList <code>className</code></td><td><code>dl-&lt;t&gt;</code></td><td>Flow <code>div.wf-datalist</code>, items <code>div.datalist-item</code> (+ <code>alt</code> / <code>selected</code> / <code>edit</code>); Table <code>table.datalist-table.wf-datalist</code>, cells <code>td.datalist-cell</code>; <code>p.empty</code></td></tr><tr><td><code>itemCssClass</code>, <code>alternatingItemCssClass</code> (Repeater)</td><td>none needed</td><td>appended to the item next to the adapter's own classes</td></tr><tr><td>Modal <code>className</code></td><td><code>md-&lt;t&gt;</code></td><td>on the overlay <code>div.modal</code>; backdrop colour via <code>--wf-backdrop</code></td></tr><tr><td>Calendar, Accordion, AdRotator</td><td>not covered</td><td>style yourself</td></tr></tbody></table></div>\n<p>Validation highlighting: the kit styles <code>.is-invalid</code> inputs, but its <code>validation-input-highlight.js</code> only works with the ASP.NET <code>WebUIValidation</code> globals. In React set <code>className={invalid ? &quot;is-invalid&quot; : &quot;&quot;}</code> from the validator state yourself.</p>"},"angular-installation-and-peer-dependencies":{"overview":"<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">powershell</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-powershell\"><span class=\"tok-f\">npm</span> install @wf-controls/angular @wf-controls/core @angular/core @angular/common</code></pre></div>\n<p>From <code>packages/angular/package.json</code>:</p>\n<div class=\"table-scroll\"><table><thead><tr><th>Field</th><th>Value</th><th>Notes</th></tr></thead><tbody><tr><td><code>peerDependencies</code></td><td><code>@angular/common &gt;= 21.2.0</code>, <code>@angular/core &gt;= 21.2.0</code>, <code>rxjs &gt;= 7</code></td><td>The repo's sample uses Angular 21.2.</td></tr><tr><td><code>dependencies</code></td><td><code>@wf-controls/core 1.0.0</code></td><td>Installed automatically; also pulls <code>@wf-controls/data</code>.</td></tr><tr><td>Module format</td><td><code>&quot;type&quot;: &quot;module&quot;</code>, <code>module: dist/fesm2022/wf-controls-angular.mjs</code>, <code>typings: dist/types/wf-controls-angular.d.ts</code>, an <code>exports</code> map, <code>&quot;sideEffects&quot;: false</code>, <code>files: [&quot;dist&quot;]</code></td><td>ESM only; built with <code>ng-packagr</code> as a single partial-Ivy FESM bundle.</td></tr></tbody></table></div>\n<p>Public exports (<code>packages/angular/src/index.ts</code>): the fifteen components (<code>WebFormsGridViewComponent</code>, <code>WebFormsRepeaterComponent</code>, <code>WebFormsDataListComponent</code>, <code>WebFormsTabsComponent</code>, <code>WebFormsModalComponent</code>, <code>WebFormsTreeViewComponent</code>, <code>WebFormsBreadcrumbComponent</code>, <code>WebFormsMenuComponent</code>, and the account family <code>WebFormsLoginComponent</code>, <code>WebFormsLoginStatusComponent</code>, <code>WebFormsLoginNameComponent</code>, <code>WebFormsLoginViewComponent</code>, <code>WebFormsChangePasswordComponent</code>, <code>WebFormsPasswordRecoveryComponent</code>, <code>WebFormsCreateUserWizardComponent</code>) and the helpers <code>viewModel</code>, <code>fromDispatcher</code>, <code>onEvent</code>, plus the context interfaces declared next to the components. There is <strong>no NgModule</strong>, no provider function, no services or pipes. Import the standalone components directly in the <code>imports</code> array of your component or <code>NgModule</code>.</p>\n<p><strong>Packaging.</strong> The package is built with <code>ng-packagr</code> (<code>npm run build:angular</code>) into partial-Ivy output (<code>dist/fesm2022/wf-controls-angular.mjs</code> plus <code>dist/types/*.d.ts</code>), the format the Angular CLI's linker expects, so an AOT app can consume the published package. The in-repo sample (<code>samples/angular</code>) imports the adapters from the package source path instead. <code>ng-packagr</code> 21 rejects TypeScript 6, so the package is built with TypeScript 5.9 (<code>typescript ^5.9.2</code> in its devDependencies).</p>\n<p><strong>Styling.</strong> No CSS is shipped by this package. The grid and repeater emit the kit's class hooks (<code>wf-repeater</code>, <code>wf-item</code>, <code>edit</code>, <code>active</code>, ... and the grid's <code>tr.edit</code> / <code>selected</code> / <code>pager</code>); the six newer components (section 5) emit Bootstrap class names (the modal) or the kit's structure. The sister package <code>@wf-controls/styles</code> themes all of them, including the Modal, Repeater and DataList (section 12).</p>\n<hr>\n"},"angular-which-package-do-i-use":{"overview":"<div class=\"table-scroll\"><table><thead><tr><th>You want to...</th><th>Use</th><th>Notes</th></tr></thead><tbody><tr><td>Run grid/paging/sort/edit/validation logic in Node, a worker, tests or any non-UI code</td><td><code>@wf-controls/core</code></td><td>Zero DOM dependencies.</td></tr><tr><td>Use the in-memory ADO.NET layer on its own</td><td><code>@wf-controls/data</code></td><td>Re-exported by core.</td></tr><tr><td>GridView or Repeater in Angular</td><td><code>@wf-controls/angular</code> + <code>@wf-controls/core</code></td><td>Sections 3 and 4.</td></tr><tr><td>DataList, Tabs, Modal, TreeView, Breadcrumb or Menu in Angular</td><td><code>@wf-controls/angular</code> + <code>@wf-controls/core</code></td><td>Section 5.</td></tr><tr><td>Accordion, Calendar, validators, Login family, AdRotator, AutoComplete, other behaviors</td><td><code>@wf-controls/core</code> controllers + your own template (+ <code>viewModel</code> / <code>onEvent</code>)</td><td>No adapter exists. See sections 6 and 8.</td></tr><tr><td>Any control in React</td><td><code>@wf-controls/react</code> + <code>@wf-controls/core</code></td><td>See <code>react-adapters.md</code> (grid, repeater, data list, menu, breadcrumb, tree, modal, tabs).</td></tr><tr><td>jQuery / plain HTML</td><td><code>@wf-controls/core</code> directly</td><td>There is no jQuery package; wrap the controllers yourself (see the JavaScript/HTML guide).</td></tr><tr><td>Theme the controls</td><td><code>@wf-controls/styles</code></td><td>Five themes for GridView (incl. edit rows), Login family, Menu, TreeView, Tabs, Navigation, Validation, Modal, Repeater and DataList. Load <code>&lt;theme&gt;-full.css</code>. See section 12.</td></tr></tbody></table></div>\n<hr>\n"},"angular-wf-grid-view-webformsgridviewcomponent":{"overview":"<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">ts</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-ts\">@<span class=\"tok-t\">Component</span>({ selector: <span class=\"tok-s\">&quot;wf-grid-view&quot;</span>, standalone: <span class=\"tok-k\">true</span>, imports: [<span class=\"tok-t\">CommonModule</span>], changeDetection: <span class=\"tok-t\">OnPush</span>, ... })\n<span class=\"tok-k\">export</span> <span class=\"tok-k\">class</span> <span class=\"tok-t\">WebFormsGridViewComponent</span>&lt;<span class=\"tok-t\">T</span> <span class=\"tok-k\">extends</span> object&gt; <span class=\"tok-k\">implements</span> <span class=\"tok-t\">OnInit</span>, <span class=\"tok-t\">OnDestroy</span></code></pre></div>\n","how-it-observes-state":"<h3 id=\"31-how-it-observes-state\">3.1 How it observes state<a class=\"anchor\" href=\"#31-how-it-observes-state\" aria-label=\"Link to this section\">#</a></h3>\n<p><code>ngOnInit</code> subscribes: <code>controller.stateChanged.subscribe(() =&gt; cdr.markForCheck())</code>; <code>ngOnDestroy</code> unsubscribes. The template reads <code>controller.options</code>, <code>controller.visibleRows</code> and <code>controller.pageCount</code> directly.</p>\n<p>Gotchas:</p>\n<ul><li><strong>The subscription is made once in <code>ngOnInit</code>.</strong> Swapping the <code>[controller]</code> input to a different instance later is not re-subscribed (the new controller's changes will not trigger a re-render until something else marks the view dirty). Keep one controller instance per component.</li><li>The component never calls <code>dataBind()</code>. Call it yourself (e.g. in <code>ngOnInit</code> of the host).</li><li>In-place mutation of <code>controller.options.*</code> from outside does not emit <code>stateChanged</code>; use controller methods.</li></ul>\n","inputs-outputs-content-slots":"<h3 id=\"32-inputs-outputs-content-slots\">3.2 Inputs, outputs, content slots<a class=\"anchor\" href=\"#32-inputs-outputs-content-slots\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Kind</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>controller</code></td><td><code>@Input({ required: true })</code></td><td><code>GridViewController&lt;T&gt;</code></td><td>yes</td><td>--</td><td>Controller to render. Styling comes from its options (<code>cssClass</code>, <code>tableCssClass</code>, row/header/footer/pager classes, <code>showFooter</code>; see 3.4).</td></tr><tr><td><code>editTemplate</code></td><td><code>@ContentChild(&quot;editTemplate&quot;, { static: true })</code></td><td><code>TemplateRef&lt;unknown&gt;</code></td><td>no</td><td>--</td><td>Full-row edit form slot (see 3.3).</td></tr></tbody></table></div>\n<p>There are <strong>no <code>@Output()</code>s</strong>. Subscribe to controller events (<code>controller.rowUpdating.subscribe(...)</code>) instead.</p>\n<p>Selector: <code>wf-grid-view</code>. Standalone: yes. Template-context type is <code>unknown</code> (no strict typing of <code>let-</code> variables).</p>\n<p>Column definitions come from <code>controller.options.columns</code>:</p>\n<div class=\"table-scroll\"><table><thead><tr><th>Column field</th><th>Effect in the Angular template</th></tr></thead><tbody><tr><td><code>type: &quot;bound&quot;</code></td><td>Cell text = <code>format(value, row)</code> if given, else <code>String(row[dataField] ?? &quot;&quot;)</code>. Header text is an <code>&lt;a href=&quot;#&quot; role=&quot;button&quot;&gt;</code> (with <code>aria-sort</code> on the <code>&lt;th&gt;</code>) when <code>sortable</code> and <code>options.allowSorting</code>.</td></tr><tr><td><code>type: &quot;template&quot;</code></td><td>Renders <strong>three hard-coded links</strong>: Select, Edit, Delete (<code>a.btn-link</code>, Delete also <code>text-danger</code>; see below). It is <strong>not</strong> a user template slot.</td></tr><tr><td><code>visible: false</code></td><td>Column filtered out.</td></tr></tbody></table></div>\n","slots-and-contracts":"<h3 id=\"33-slots-and-contracts\">3.3 Slots and contracts<a class=\"anchor\" href=\"#33-slots-and-contracts\" aria-label=\"Link to this section\">#</a></h3>\n<p><strong>There is no per-cell template slot</strong> (the React adapter's <code>template</code> / <code>editCellTemplate</code> have no Angular equivalent, and a <code>&lt;ng-template #template&gt;</code> inside <code>&lt;wf-grid-view&gt;</code> is ignored). The Angular snippet in <code>docs/v1.0.0/grid-view.md</code> section 4 now describes the real <code>#editTemplate</code> contract (it used to show an unimplemented <code>#template</code> / <code>[(ngModel)]</code> slot). What you can customise:</p>\n<ol><li><strong>Cell text of bound columns</strong> via the column's <code>format(value, row)</code> function.</li><li><strong>The whole edit row</strong> via the <code>#editTemplate</code> content template.</li></ol>\n<p><code>#editTemplate</code> context:</p>\n<div class=\"table-scroll\"><table><thead><tr><th>Variable</th><th>Type</th><th>Meaning</th></tr></thead><tbody><tr><td><code>$implicit</code> (<code>let-row</code>)</td><td><code>T</code> (typed <code>unknown</code> in templates)</td><td>Row being edited.</td></tr><tr><td><code>index</code></td><td><code>number</code></td><td><strong>Absolute</strong> row index (page offset included).</td></tr><tr><td><code>save</code></td><td><code>(values: Partial&lt;T&gt;) =&gt; Promise&lt;boolean&gt;</code></td><td>Calls <code>controller.updateRow(index, values)</code>. <code>false</code> when vetoed / invalid.</td></tr><tr><td><code>cancel</code></td><td><code>() =&gt; Promise&lt;boolean&gt;</code></td><td>Calls <code>controller.cancelEdit()</code>.</td></tr></tbody></table></div>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">html</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-html\"><span class=\"tok-t\">&lt;wf-grid-view</span><span class=\"tok-k\"> [controller]</span>=<span class=\"tok-s\">&quot;grid&quot;</span>&gt;\n  <span class=\"tok-t\">&lt;ng-template</span> #editTemplate let-row<span class=\"tok-k\"> let-index</span>=<span class=\"tok-s\">&quot;index&quot;</span><span class=\"tok-k\"> let-save</span>=<span class=\"tok-s\">&quot;save&quot;</span><span class=\"tok-k\"> let-cancel</span>=<span class=\"tok-s\">&quot;cancel&quot;</span>&gt;\n    <span class=\"tok-t\">&lt;input</span> #nameBox<span class=\"tok-k\"> [value]</span>=<span class=\"tok-s\">&quot;row.name&quot;</span> /&gt;\n    <span class=\"tok-t\">&lt;button</span><span class=\"tok-k\"> type</span>=<span class=\"tok-s\">&quot;button&quot;</span><span class=\"tok-k\"> (click)</span>=<span class=\"tok-s\">&quot;save({ name: nameBox.value })&quot;</span>&gt;Update<span class=\"tok-t\">&lt;/button</span>&gt;\n    <span class=\"tok-t\">&lt;button</span><span class=\"tok-k\"> type</span>=<span class=\"tok-s\">&quot;button&quot;</span><span class=\"tok-k\"> (click)</span>=<span class=\"tok-s\">&quot;cancel()&quot;</span>&gt;Cancel<span class=\"tok-t\">&lt;/button</span>&gt;\n  <span class=\"tok-t\">&lt;/ng-template</span>&gt;\n<span class=\"tok-t\">&lt;/wf-grid-view</span>&gt;</code></pre></div>\n<p>Gotchas:</p>\n<ul><li>The query is <code>{ static: true }</code>: the <code>&lt;ng-template #editTemplate&gt;</code> must be a <strong>direct, unconditional</strong> child of <code>&lt;wf-grid-view&gt;</code>. Wrapping it in <code>@if</code> / <code>*ngIf</code> / <code>@for</code> makes it invisible to the component.</li><li><strong>Without <code>#editTemplate</code> there is no inline editor at all.</strong> The Edit link still calls <code>beginEdit</code> (so <code>controller.options.editIndex</code> changes and <code>rowEditing</code> fires) and the row gets the <code>edit</code> class, but its cells are unchanged and there are no Update/Cancel controls. Always provide <code>#editTemplate</code> if you expose Edit.</li><li>While editing, the row is replaced by a single <code>&lt;td [attr.colspan]=&quot;columns.length&quot;&gt;</code> hosting your template; other rows stay normal.</li><li>Values from native <code>&lt;input&gt;</code> are strings; convert numbers/dates yourself before <code>save()</code>.</li><li><code>save()</code> and <code>cancel</code> return promises; the template ignores them, so errors thrown inside the controller become unhandled rejections (wrap in your own method if you need handling).</li></ul>\n","markup-and-styling-hooks":"<h3 id=\"34-markup-and-styling-hooks\">3.4 Markup and styling hooks<a class=\"anchor\" href=\"#34-markup-and-styling-hooks\" aria-label=\"Link to this section\">#</a></h3>\n<p>The markup is identical to the React adapter and is what the <code>@wf-controls/styles</code> GridView sheets (<code>table.gv-&lt;theme&gt;</code>) expect.</p>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">html</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-html\"><span class=\"tok-t\">&lt;div</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;{cssClass}&quot;</span>&gt;                                   <span class=\"tok-c\">&lt;!-- wrapper: cssClass --&gt;</span>\n  <span class=\"tok-t\">&lt;table</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;{cssClass} {tableCssClass}&quot;</span>&gt;                <span class=\"tok-c\">&lt;!-- table: cssClass + tableCssClass --&gt;</span>\n    <span class=\"tok-t\">&lt;thead</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;{headerCssClass}&quot;</span>&gt;<span class=\"tok-t\">&lt;tr</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;{headerCssClass}&quot;</span>&gt;\n      <span class=\"tok-t\">&lt;th</span><span class=\"tok-k\"> scope</span>=<span class=\"tok-s\">&quot;col&quot;</span><span class=\"tok-k\"> aria-sort</span>=<span class=\"tok-s\">&quot;ascending|descending|none&quot;</span>&gt;<span class=\"tok-t\">&lt;a</span><span class=\"tok-k\"> href</span>=<span class=\"tok-s\">&quot;#&quot;</span><span class=\"tok-k\"> role</span>=<span class=\"tok-s\">&quot;button&quot;</span>&gt;Name<span class=\"tok-t\">&lt;/a</span>&gt;<span class=\"tok-t\">&lt;/th</span>&gt;   <span class=\"tok-c\">&lt;!-- sortable bound column --&gt;</span>\n      <span class=\"tok-t\">&lt;th</span><span class=\"tok-k\"> scope</span>=<span class=\"tok-s\">&quot;col&quot;</span>&gt;Plain header<span class=\"tok-t\">&lt;/th</span>&gt;\n    <span class=\"tok-t\">&lt;/tr</span>&gt;<span class=\"tok-t\">&lt;/thead</span>&gt;\n    <span class=\"tok-t\">&lt;tbody</span>&gt;\n      <span class=\"tok-t\">&lt;tr</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;empty&quot;</span>&gt;<span class=\"tok-t\">&lt;td</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;empty&quot;</span><span class=\"tok-k\"> colspan</span>=<span class=\"tok-s\">&quot;N&quot;</span>&gt;{{ emptyDataText }}<span class=\"tok-t\">&lt;/td</span>&gt;<span class=\"tok-t\">&lt;/tr</span>&gt;   <span class=\"tok-c\">&lt;!-- when no visible rows --&gt;</span>\n      <span class=\"tok-t\">&lt;tr</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;{row class}&quot;</span><span class=\"tok-k\"> aria-selected</span>=<span class=\"tok-s\">&quot;true&quot;</span>&gt;<span class=\"tok-t\">&lt;td</span>&gt;cell<span class=\"tok-t\">&lt;/td</span>&gt;...<span class=\"tok-t\">&lt;/tr</span>&gt;\n      <span class=\"tok-t\">&lt;tr</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;edit {editRowCssClass}&quot;</span>&gt;<span class=\"tok-t\">&lt;td</span><span class=\"tok-k\"> colspan</span>=<span class=\"tok-s\">&quot;N&quot;</span>&gt;<span class=\"tok-c\">&lt;!-- #editTemplate --&gt;</span><span class=\"tok-t\">&lt;/td</span>&gt;<span class=\"tok-t\">&lt;/tr</span>&gt;  <span class=\"tok-c\">&lt;!-- editing row, with #editTemplate --&gt;</span>\n    <span class=\"tok-t\">&lt;/tbody</span>&gt;\n    <span class=\"tok-t\">&lt;tfoot</span>&gt;\n      <span class=\"tok-t\">&lt;tr</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;footer {footerCssClass}&quot;</span>&gt;<span class=\"tok-t\">&lt;td</span>&gt;<span class=\"tok-t\">&lt;/td</span>&gt;...<span class=\"tok-t\">&lt;/tr</span>&gt;                       <span class=\"tok-c\">&lt;!-- showFooter --&gt;</span>\n      <span class=\"tok-t\">&lt;tr</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;pager {pagerCssClass}&quot;</span>&gt;<span class=\"tok-t\">&lt;td</span><span class=\"tok-k\"> colspan</span>=<span class=\"tok-s\">&quot;N&quot;</span>&gt;                          <span class=\"tok-c\">&lt;!-- allowPaging --&gt;</span>\n        <span class=\"tok-t\">&lt;a</span><span class=\"tok-k\"> href</span>=<span class=\"tok-s\">&quot;#&quot;</span><span class=\"tok-k\"> role</span>=<span class=\"tok-s\">&quot;button&quot;</span>&gt;Previous<span class=\"tok-t\">&lt;/a</span>&gt; <span class=\"tok-t\">&lt;a</span><span class=\"tok-k\"> href</span>=<span class=\"tok-s\">&quot;#&quot;</span>&gt;1<span class=\"tok-t\">&lt;/a</span>&gt; <span class=\"tok-t\">&lt;span</span><span class=\"tok-k\"> aria-current</span>=<span class=\"tok-s\">&quot;page&quot;</span>&gt;2<span class=\"tok-t\">&lt;/span</span>&gt; <span class=\"tok-t\">&lt;a</span><span class=\"tok-k\"> href</span>=<span class=\"tok-s\">&quot;#&quot;</span>&gt;3<span class=\"tok-t\">&lt;/a</span>&gt; <span class=\"tok-t\">&lt;a</span><span class=\"tok-k\"> href</span>=<span class=\"tok-s\">&quot;#&quot;</span><span class=\"tok-k\"> role</span>=<span class=\"tok-s\">&quot;button&quot;</span>&gt;Next<span class=\"tok-t\">&lt;/a</span>&gt;\n        <span class=\"tok-t\">&lt;span</span><span class=\"tok-k\"> style</span>=<span class=\"tok-s\">&quot;visually hidden&quot;</span>&gt;Page 2 of 3<span class=\"tok-t\">&lt;/span</span>&gt;\n      <span class=\"tok-t\">&lt;/td</span>&gt;<span class=\"tok-t\">&lt;/tr</span>&gt;\n    <span class=\"tok-t\">&lt;/tfoot</span>&gt;\n  <span class=\"tok-t\">&lt;/table</span>&gt;\n<span class=\"tok-t\">&lt;/div</span>&gt;</code></pre></div>\n<p>Template-column cell: <code>&lt;a href=&quot;#&quot; class=&quot;btn-link&quot; role=&quot;button&quot;&gt;Select&lt;/a&gt; &lt;a ...&gt;Edit&lt;/a&gt; &lt;a href=&quot;#&quot; class=&quot;btn-link text-danger&quot; role=&quot;button&quot;&gt;Delete&lt;/a&gt;</code>.</p>\n<p>Row class priority: editing row -&gt; <code>edit</code> + <code>editRowCssClass</code>; selected row -&gt; <code>selected</code> + <code>selectedRowCssClass</code> (and <code>aria-selected=&quot;true&quot;</code>); odd visible index with <code>alternatingRowCssClass</code> set -&gt; <code>alternatingRowCssClass</code>; else <code>rowCssClass</code>. The kit defaults <code>edit</code>, <code>selected</code>, <code>footer</code>, <code>pager</code> and <code>empty</code> are always present and your classes are appended.</p>\n<p>Details:</p>\n<ul><li>All of <code>cssClass</code>, <code>tableCssClass</code>, <code>rowCssClass</code>, <code>alternatingRowCssClass</code>, <code>selectedRowCssClass</code>, <code>editRowCssClass</code>, <code>headerCssClass</code>, <code>footerCssClass</code>, <code>pagerCssClass</code> and <code>showFooter</code> are honoured (earlier versions ignored all but <code>cssClass</code>). <code>cssClass</code> lands on <strong>both</strong> the wrapper <code>div</code> and the table; the table additionally gets <code>tableCssClass</code>.</li><li>The pager row is rendered whenever <code>allowPaging</code> is true, <strong>even when there is only one page</strong> (Previous and Next are then disabled <code>span.aspNetDisabled</code>). It lists a window of at most 10 page numbers around the current page; the current page is <code>span[aria-current=page]</code>. A visually hidden &quot;Page X of Y&quot; is included. Previous/Next labels are hard-coded English.</li><li>Alternation is by position on the <strong>page</strong>, not the absolute index.</li><li><code>ngFor</code> has no <code>trackBy</code>, so rows are re-created when the array identity changes (e.g. after <code>dataBind</code>).</li><li>The kit's nested-table pager selector (<code>.pager table</code>) is not produced; see <a href=\"#/api/guides/issues-needs-your-attention-first\">Known issues</a>.</li></ul>\n","accessibility-emitted":"<h3 id=\"35-accessibility-emitted\">3.5 Accessibility emitted<a class=\"anchor\" href=\"#35-accessibility-emitted\" aria-label=\"Link to this section\">#</a></h3>\n<p><code>&lt;table&gt;/&lt;thead&gt;/&lt;tbody&gt;/&lt;tfoot&gt;</code>, <code>th[scope=col]</code>, <code>aria-sort</code> on sortable headers, <code>aria-selected</code> on the selected row, <code>aria-current=&quot;page&quot;</code> on the current pager page, a visually hidden &quot;Page X of Y&quot;, and anchors with <code>role=&quot;button&quot;</code> for sorting, paging and the Select/Edit/Delete commands. There are no live regions and no data attributes.</p>\n","command-flow-ui-controller":"<h3 id=\"36-command-flow-ui---controller\">3.6 Command flow (UI -&gt; controller)<a class=\"anchor\" href=\"#36-command-flow-ui---controller\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>UI action</th><th>Component method</th><th>Controller call</th><th>Events</th></tr></thead><tbody><tr><td>Header link</td><td><code>sort(column)</code></td><td><code>controller.sort(column.dataField)</code> (bound columns only)</td><td><code>sorting</code> (cancellable) -&gt; <code>sorted</code> -&gt; <code>stateChanged(&quot;sort&quot;)</code>; toggles asc/desc</td></tr><tr><td>Previous / Next / page number</td><td><code>page(-1 / +1)</code></td><td><code>controller.changePage(pageIndex + delta)</code></td><td><code>pageIndexChanging</code> (cancellable) -&gt; <code>pageIndexChanged</code> -&gt; <code>stateChanged(&quot;changePage&quot;)</code>; re-runs <code>dataBind()</code> for <code>IDataSourceControl</code> sources</td></tr><tr><td>Select link</td><td><code>command(i, &quot;Select&quot;, row)</code></td><td><code>controller.executeCommand(absIndex, &quot;Select&quot;, dataKey)</code></td><td><code>rowCommand</code>, then <code>selectedIndexChanging</code> (cancellable) / <code>selectedIndexChanged</code></td></tr><tr><td>Edit link</td><td><code>command(i, &quot;Edit&quot;, row)</code></td><td><code>executeCommand(absIndex, &quot;Edit&quot;, dataKey)</code></td><td><code>rowCommand</code>, then <code>rowEditing</code> (cancellable) -&gt; <code>editIndex</code> set</td></tr><tr><td>Delete link</td><td><code>command(i, &quot;Delete&quot;, row)</code></td><td><code>executeCommand(absIndex, &quot;Delete&quot;, dataKey)</code></td><td><code>rowCommand</code>, then <code>rowDeleting</code> (cancellable) -&gt; data-source <code>delete</code> (if applicable) -&gt; <code>rowDeleted</code></td></tr><tr><td><code>save(values)</code></td><td><code>saveFor(absIndex)</code></td><td><code>controller.updateRow(absIndex, values)</code></td><td>optional validation (<code>causesValidation</code>) -&gt; <code>rowUpdating</code> (cancellable, <code>e.values</code>) -&gt; data-source <code>update</code> -&gt; <code>rowUpdated</code> -&gt; <code>stateChanged(&quot;updateRow&quot;)</code></td></tr><tr><td><code>cancel()</code></td><td><code>cancel</code></td><td><code>controller.cancelEdit()</code></td><td><code>rowCancelingEdit</code> (cancellable)</td></tr></tbody></table></div>\n<p>Notes:</p>\n<ul><li><code>commandArgument</code> sent with the built-in links is the row's <strong>data key</strong> (<code>controller.getDataKey(row)</code>), so <code>rowCommand</code> handlers can read <code>e.commandName</code> and <code>e.commandArgument</code>.</li><li>Command names are matched case-insensitively in the controller; <code>update</code> is not a command name. A <code>Cancel</code> command is only reachable through the <code>cancel</code> template function.</li><li>The hard-coded Delete link deletes immediately unless a <code>rowDeleting</code> handler sets <code>e.cancel = true</code>; build confirmation into that handler (async handlers are awaited) or drive deletion from your own UI (section 8.3).</li></ul>\n<hr>\n"},"angular-wf-repeater-webformsrepeatercomponent":{"overview":"<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">ts</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-ts\">@<span class=\"tok-t\">Component</span>({ selector: <span class=\"tok-s\">&quot;wf-repeater&quot;</span>, standalone: <span class=\"tok-k\">true</span>, imports: [<span class=\"tok-t\">CommonModule</span>], changeDetection: <span class=\"tok-t\">OnPush</span>, ... })\n<span class=\"tok-k\">export</span> <span class=\"tok-k\">class</span> <span class=\"tok-t\">WebFormsRepeaterComponent</span>&lt;<span class=\"tok-t\">T</span> <span class=\"tok-k\">extends</span> object&gt; <span class=\"tok-k\">implements</span> <span class=\"tok-t\">OnInit</span>, <span class=\"tok-t\">OnDestroy</span></code></pre></div>\n","state":"<h3 id=\"41-state\">4.1 State<a class=\"anchor\" href=\"#41-state\" aria-label=\"Link to this section\">#</a></h3>\n<p>Same pattern as the grid: subscribes to <code>controller.stateChanged</code> in <code>ngOnInit</code>, marks for check, unsubscribes in <code>ngOnDestroy</code> (same &quot;controller swap is not re-subscribed&quot; caveat). Renders nothing while <code>controller.isResetting</code>. You call <code>dataBind()</code> yourself.</p>\n","inputs-outputs-content-slots":"<h3 id=\"42-inputs-outputs-content-slots\">4.2 Inputs, outputs, content slots<a class=\"anchor\" href=\"#42-inputs-outputs-content-slots\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Kind</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>controller</code></td><td><code>@Input({ required: true })</code></td><td><code>RepeaterController&lt;T&gt;</code></td><td>yes</td><td>--</td><td>Controller to render.</td></tr><tr><td><code>createItem</code></td><td><code>@Input()</code></td><td><code>() =&gt; T | Promise&lt;T&gt;</code></td><td>no</td><td>--</td><td>Factory used by the built-in &quot;Add item&quot; button. Without it, the button does nothing.</td></tr><tr><td><code>itemTemplate</code></td><td><code>@ContentChild(&quot;itemTemplate&quot;, { static: true })</code></td><td><code>TemplateRef&lt;unknown&gt;</code></td><td><strong>yes (in practice)</strong></td><td>--</td><td>Renders each item.</td></tr><tr><td><code>editItemTemplate</code></td><td><code>@ContentChild(&quot;editItemTemplate&quot;, { static: true })</code></td><td><code>TemplateRef&lt;unknown&gt;</code></td><td>no</td><td>--</td><td>Renders the item currently in edit mode.</td></tr></tbody></table></div>\n<p>No <code>@Output()</code>s. There are <strong>no</strong> header, footer, separator, alternating-item or empty templates (the React repeater has them; Angular does not).</p>\n<p>Slot contexts:</p>\n<div class=\"table-scroll\"><table><thead><tr><th>Slot</th><th>Context variables</th></tr></thead><tbody><tr><td><code>#itemTemplate</code></td><td><code>$implicit</code> (<code>let-item</code>): the item; <code>index</code>: item index; <code>command</code>: <code>(name: string, argument?: unknown) =&gt; Promise&lt;void&gt;</code> -&gt; <code>controller.executeCommand(index, name, argument)</code></td></tr><tr><td><code>#editItemTemplate</code></td><td><code>$implicit</code>: the item; <code>index</code>; <code>save</code>: <code>(values: Partial&lt;T&gt;) =&gt; Promise&lt;boolean&gt;</code> -&gt; <code>controller.updateItem(index, values)</code>; <code>cancel</code>: <code>() =&gt; Promise&lt;boolean&gt;</code> -&gt; <code>controller.cancelEdit()</code></td></tr></tbody></table></div>\n<p>Gotchas:</p>\n<ul><li>Both queries are <code>static: true</code>; the <code>&lt;ng-template&gt;</code>s must be direct, unconditional children of <code>&lt;wf-repeater&gt;</code>.</li><li><code>itemTemplate</code> is declared non-optional but is not validated: omit it and items render as empty wrappers (no error).</li><li>There is no <code>alternatingItemTemplate</code>; use <code>index % 2</code> inside your template.</li><li>The edit template is used only when <code>controller.editItemIndex === index</code> <strong>and</strong> <code>#editItemTemplate</code> exists; otherwise the item template renders even in edit mode.</li></ul>\n","controller-options-used":"<h3 id=\"43-controller-options-used\">4.3 Controller options used<a class=\"anchor\" href=\"#43-controller-options-used\" aria-label=\"Link to this section\">#</a></h3>\n<p><code>cssClass</code> (root class; the component's own <code>cssClass</code> input is appended to it), <code>itemCssClass</code>, <code>alternatingItemCssClass</code> (added to each item), <code>itemHeaderVisible</code> (only <code>false</code> hides the header), <code>allowUserToAddItems</code>, <code>allowUserToDeleteItems</code>, <code>emptyText</code> (falls back to <code>'No records found.'</code> when falsy). <code>dataKeyField</code> is <strong>not</strong> used by the Angular template (no <code>trackBy</code>).</p>\n","markup-and-styling-hooks":"<h3 id=\"44-markup-and-styling-hooks\">4.4 Markup and styling hooks<a class=\"anchor\" href=\"#44-markup-and-styling-hooks\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">html</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-html\"><span class=\"tok-t\">&lt;div</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;wf-repeater {controller.options.cssClass} {cssClass input}&quot;</span>&gt;     <span class=\"tok-c\">&lt;!-- e.g. rp-modern --&gt;</span>\n  <span class=\"tok-t\">&lt;button</span><span class=\"tok-k\"> type</span>=<span class=\"tok-s\">&quot;button&quot;</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;add&quot;</span>&gt;Add item<span class=\"tok-t\">&lt;/button</span>&gt;        <span class=\"tok-c\">&lt;!-- allowUserToAddItems --&gt;</span>\n  <span class=\"tok-t\">&lt;div</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;wf-item {itemCssClass} [alt {alternatingItemCssClass}] [active] [edit]&quot;</span>&gt;  <span class=\"tok-c\">&lt;!-- one per item; click selects --&gt;</span>\n    <span class=\"tok-t\">&lt;header</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;wf-item-header&quot;</span>&gt;                           <span class=\"tok-c\">&lt;!-- unless itemHeaderVisible === false --&gt;</span>\n      <span class=\"tok-t\">&lt;span</span>&gt;Item N<span class=\"tok-t\">&lt;/span</span>&gt;\n      <span class=\"tok-t\">&lt;button</span><span class=\"tok-k\"> type</span>=<span class=\"tok-s\">&quot;button&quot;</span>&gt;Delete<span class=\"tok-t\">&lt;/button</span>&gt;                   <span class=\"tok-c\">&lt;!-- allowUserToDeleteItems; stops propagation --&gt;</span>\n    <span class=\"tok-t\">&lt;/header</span>&gt;\n    <span class=\"tok-c\">&lt;!-- #editItemTemplate or #itemTemplate output --&gt;</span>\n  <span class=\"tok-t\">&lt;/div</span>&gt;\n  <span class=\"tok-c\">&lt;!-- empty: &lt;div class=&quot;empty&quot;&gt;emptyText || 'No records found.'&lt;/div&gt; --&gt;</span>\n<span class=\"tok-t\">&lt;/div</span>&gt;</code></pre></div>\n<p>Class hooks (identical to the React adapter): <code>alt</code> on odd items, <code>active</code> on the current item, <code>edit</code> on the item shown through <code>#editItemTemplate</code>. Theme it with the <strong><code>cssClass</code> input</strong> (<code>&lt;wf-repeater [controller]=&quot;rep&quot; cssClass=&quot;rp-modern&quot;&gt;</code>) or the controller's <code>cssClass</code> option, and load <code>modern-full.css</code> (section 12). No ARIA/data attributes. &quot;Add item&quot;, &quot;Item N&quot; and &quot;Delete&quot; are hard-coded English; use <code>itemHeaderVisible: false</code> to hide the header.</p>\n","command-flow":"<h3 id=\"45-command-flow\">4.5 Command flow<a class=\"anchor\" href=\"#45-command-flow\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>UI action</th><th>Component method</th><th>Controller call / events</th></tr></thead><tbody><tr><td>Click an item wrapper</td><td><code>select(i)</code></td><td><code>setCurrentItemIndex(i)</code> -&gt; <code>currentItemIndexChanged</code>, <code>stateChanged</code>. Bubbles from buttons inside your template (your Edit button also selects).</td></tr><tr><td>Built-in Delete</td><td><code>delete(i)</code></td><td><code>deleteItem(i)</code> -&gt; <code>stateChanged(&quot;deleteItem&quot;)</code> (no cancellable event)</td></tr><tr><td>Built-in Add</td><td><code>add()</code></td><td><code>addItem(await createItem())</code> -&gt; <code>onItemValuePushed</code>, <code>stateChanged(&quot;addItem&quot;)</code></td></tr><tr><td><code>command('Edit')</code></td><td><code>commandFor(i)</code></td><td><code>executeCommand</code> -&gt; <code>itemCommand</code>, then <code>beginEdit(i)</code> (<code>itemEditing</code>, cancellable)</td></tr><tr><td><code>command('Select')</code></td><td></td><td><code>itemCommand</code>, then <code>setCurrentItemIndex(i)</code></td></tr><tr><td><code>command('Cancel')</code></td><td></td><td><code>itemCommand</code>, then <code>cancelEdit()</code> (<code>itemCancelingEdit</code>)</td></tr><tr><td><code>save(values)</code></td><td><code>saveFor(i)</code></td><td><code>updateItem(i, values)</code> -&gt; <code>itemUpdating</code> (cancellable) -&gt; <code>itemUpdated</code> -&gt; <code>stateChanged</code></td></tr></tbody></table></div>\n<p>Gotcha: <code>RepeaterController.executeCommand</code> does <strong>not</strong> handle <code>&quot;Delete&quot;</code>; call <code>controller.deleteItem(index)</code> from your template (example 7.3). Items added/deleted live only in the controller's internal copy, not in the original <code>dataSource</code>.</p>\n<hr>\n"},"angular-the-navigation-dialog-and-list-components":{"overview":"<p>These six components share one pattern: decorator <code>@Input</code>s, optional <code>static: true</code> <code>@ContentChild</code> named templates (so each <code>&lt;ng-template&gt;</code> must be a direct, unconditional child of the component tag), <code>OnPush</code>, and <code>markForCheck()</code> on the controller's events. Unlike <code>wf-grid-view</code> and <code>wf-repeater</code>, all six <strong>re-subscribe when the controller input is replaced</strong> (<code>ngOnChanges</code>). None of them calls <code>dataBind()</code> for you (except <code>wf-breadcrumb</code> with <code>currentUrl</code>). Markup uses Bootstrap class names (<code>nav-tabs</code>, <code>modal</code>, <code>breadcrumb</code>, ...) but no CSS is shipped.</p>\n","wf-data-list-webformsdatalistcomponent":"<h3 id=\"51-wf-data-list-webformsdatalistcomponent\">5.1 <code>wf-data-list</code> (<code>WebFormsDataListComponent&lt;T&gt;</code>)<a class=\"anchor\" href=\"#51-wf-data-list-webformsdatalistcomponent\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Kind</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>controller</code></td><td><code>@Input({ required: true })</code></td><td><code>DataListController&lt;T&gt;</code></td><td>Controller to render.</td></tr><tr><td><code>cssClass</code></td><td><code>@Input()</code></td><td><code>string</code></td><td>Flow: appended to the root <code>div.wf-datalist</code>. Table: class of the wrapper <code>&lt;div&gt;</code> and of <code>table.datalist-table.wf-datalist</code>. Put the kit theme here: <code>cssClass=&quot;dl-modern&quot;</code>.</td></tr><tr><td><code>#itemTemplate</code></td><td><code>@ContentChild</code></td><td><code>TemplateRef</code></td><td>Required in practice.</td></tr><tr><td><code>#alternatingItemTemplate</code>, <code>#selectedItemTemplate</code>, <code>#editItemTemplate</code></td><td><code>@ContentChild</code></td><td><code>TemplateRef</code></td><td>Optional; fall back to <code>#itemTemplate</code> when absent.</td></tr><tr><td><code>#headerTemplate</code>, <code>#footerTemplate</code></td><td><code>@ContentChild</code></td><td><code>TemplateRef</code></td><td>Shown only when <code>controller.showHeader</code> / <code>showFooter</code> is true.</td></tr><tr><td><code>#separatorTemplate</code></td><td><code>@ContentChild</code></td><td><code>TemplateRef</code></td><td>Between items, <strong>Flow layout only</strong>.</td></tr><tr><td><code>#emptyTemplate</code></td><td><code>@ContentChild</code></td><td><code>TemplateRef</code></td><td>Replaces the default <code>&lt;p&gt;{{ controller.emptyText }}&lt;/p&gt;</code>.</td></tr></tbody></table></div>\n<p>Contexts: item, alternating and selected templates get <code>{ $implicit: item, index, command(name, argument?) =&gt; Promise&lt;void&gt; }</code>. The edit template adds <code>save(values) =&gt; Promise&lt;boolean&gt;</code> and <code>cancel() =&gt; Promise&lt;boolean&gt;</code>.</p>\n<p>Layouts: <code>repeatLayout === 'Flow'</code> renders one <code>div.datalist-item.datalist-&lt;itemtype&gt;</code> per item inside <code>div.wf-datalist</code>. Otherwise a <code>&lt;table class=&quot;datalist-table wf-datalist&quot;&gt;</code> is built from <code>controller.getLayoutMatrix()</code> (<code>repeatColumns</code>, <code>showTableBorder</code>), with <code>td.datalist-cell.datalist-&lt;itemtype&gt;</code> cells and <code>td.datalist-cell-empty</code> for padding. Items and cells also get a semantic class: <code>alt</code>, <code>selected</code>, <code>edit</code> (and <code>header</code> / <code>footer</code> / <code>separator</code> for those item types), which the <code>dl-&lt;theme&gt;</code> family styles. The empty state is <code>p.empty</code>. Header and footer go in <code>&lt;thead&gt;</code> / <code>&lt;tfoot&gt;</code> rows spanning <code>repeatColumns</code>.</p>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">html</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-html\"><span class=\"tok-t\">&lt;wf-data-list</span><span class=\"tok-k\"> [controller]</span>=<span class=\"tok-s\">&quot;contacts&quot;</span><span class=\"tok-k\"> cssClass</span>=<span class=\"tok-s\">&quot;contacts&quot;</span>&gt;\n  <span class=\"tok-t\">&lt;ng-template</span> #itemTemplate let-c<span class=\"tok-k\"> let-command</span>=<span class=\"tok-s\">&quot;command&quot;</span>&gt;\n    <span class=\"tok-t\">&lt;strong</span>&gt;{{ c.name }}<span class=\"tok-t\">&lt;/strong</span>&gt; <span class=\"tok-t\">&lt;button</span><span class=\"tok-k\"> type</span>=<span class=\"tok-s\">&quot;button&quot;</span><span class=\"tok-k\"> (click)</span>=<span class=\"tok-s\">&quot;command('Edit')&quot;</span>&gt;Edit<span class=\"tok-t\">&lt;/button</span>&gt;\n  <span class=\"tok-t\">&lt;/ng-template</span>&gt;\n  <span class=\"tok-t\">&lt;ng-template</span> #editItemTemplate let-c<span class=\"tok-k\"> let-save</span>=<span class=\"tok-s\">&quot;save&quot;</span><span class=\"tok-k\"> let-cancel</span>=<span class=\"tok-s\">&quot;cancel&quot;</span>&gt;\n    <span class=\"tok-t\">&lt;input</span> #box<span class=\"tok-k\"> [value]</span>=<span class=\"tok-s\">&quot;c.name&quot;</span> /&gt;\n    <span class=\"tok-t\">&lt;button</span><span class=\"tok-k\"> type</span>=<span class=\"tok-s\">&quot;button&quot;</span><span class=\"tok-k\"> (click)</span>=<span class=\"tok-s\">&quot;save({ name: box.value })&quot;</span>&gt;Save<span class=\"tok-t\">&lt;/button</span>&gt;\n    <span class=\"tok-t\">&lt;button</span><span class=\"tok-k\"> type</span>=<span class=\"tok-s\">&quot;button&quot;</span><span class=\"tok-k\"> (click)</span>=<span class=\"tok-s\">&quot;cancel()&quot;</span>&gt;Cancel<span class=\"tok-t\">&lt;/button</span>&gt;\n  <span class=\"tok-t\">&lt;/ng-template</span>&gt;\n  <span class=\"tok-t\">&lt;ng-template</span> #emptyTemplate&gt;<span class=\"tok-t\">&lt;em</span>&gt;No contacts.<span class=\"tok-t\">&lt;/em</span>&gt;<span class=\"tok-t\">&lt;/ng-template</span>&gt;\n<span class=\"tok-t\">&lt;/wf-data-list</span>&gt;</code></pre></div>\n<p>Gotchas: a header or footer template renders nothing unless the controller flag is also on. Bind data yourself (<code>void contacts.dataBind(rows)</code>).</p>\n","wf-tabs-webformstabscomponent":"<h3 id=\"52-wf-tabs-webformstabscomponent\">5.2 <code>wf-tabs</code> (<code>WebFormsTabsComponent</code>)<a class=\"anchor\" href=\"#52-wf-tabs-webformstabscomponent\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Kind</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>controller</code></td><td><code>@Input({ required: true })</code></td><td><code>TabsController</code></td><td>Tab headers come from <code>controller.tabs</code>.</td></tr><tr><td><code>cssClass</code></td><td><code>@Input()</code></td><td><code>string</code></td><td>Appended to the root <code>div.wf-tabs</code>.</td></tr><tr><td><code>#tabContent</code></td><td><code>@ContentChild</code></td><td><code>TemplateRef</code></td><td>Context <code>{ $implicit: tab, index }</code>; rendered for the <strong>active tab only</strong> (inactive panels are not mounted). Switch on <code>tab.id</code> or <code>index</code>.</td></tr></tbody></table></div>\n<p>Markup:</p>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">html</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-html\"><span class=\"tok-t\">&lt;div</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;wf-tabs {cssClass}&quot;</span>&gt;\n  <span class=\"tok-t\">&lt;ul</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;ajax__tab_header nav nav-tabs mb-3&quot;</span><span class=\"tok-k\"> role</span>=<span class=\"tok-s\">&quot;tablist&quot;</span>&gt;\n    <span class=\"tok-t\">&lt;li</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;nav-item&quot;</span><span class=\"tok-k\"> role</span>=<span class=\"tok-s\">&quot;presentation&quot;</span>&gt;\n      <span class=\"tok-t\">&lt;span</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;ajax__tab_outer ajax__tab_active&quot;</span>&gt;          <span class=\"tok-c\">&lt;!-- ajax__tab_active on the active tab only --&gt;</span>\n        <span class=\"tok-t\">&lt;span</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;ajax__tab_inner&quot;</span>&gt;\n          <span class=\"tok-t\">&lt;button</span><span class=\"tok-k\"> type</span>=<span class=\"tok-s\">&quot;button&quot;</span><span class=\"tok-k\"> role</span>=<span class=\"tok-s\">&quot;tab&quot;</span><span class=\"tok-k\"> id</span>=<span class=\"tok-s\">&quot;wf-tabs-1-tab-a&quot;</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;ajax__tab_tab nav-link active|disabled&quot;</span>\n                 <span class=\"tok-k\"> aria-selected</span>=<span class=\"tok-s\">&quot;true&quot;</span><span class=\"tok-k\"> aria-controls</span>=<span class=\"tok-s\">&quot;wf-tabs-1-panel-a&quot;</span><span class=\"tok-k\"> tabindex</span>=<span class=\"tok-s\">&quot;0|-1&quot;</span> disabled&gt;Header<span class=\"tok-t\">&lt;/button</span>&gt;\n        <span class=\"tok-t\">&lt;/span</span>&gt;\n      <span class=\"tok-t\">&lt;/span</span>&gt;\n    <span class=\"tok-t\">&lt;/li</span>&gt;\n  <span class=\"tok-t\">&lt;/ul</span>&gt;\n  <span class=\"tok-t\">&lt;div</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;tab-content&quot;</span>&gt;\n    <span class=\"tok-t\">&lt;div</span><span class=\"tok-k\"> id</span>=<span class=\"tok-s\">&quot;wf-tabs-1-panel-a&quot;</span><span class=\"tok-k\"> class</span>=<span class=\"tok-s\">&quot;tab-pane active ajax__tab_body&quot;</span><span class=\"tok-k\"> role</span>=<span class=\"tok-s\">&quot;tabpanel&quot;</span><span class=\"tok-k\"> aria-labelledby</span>=<span class=\"tok-s\">&quot;wf-tabs-1-tab-a&quot;</span>&gt;...<span class=\"tok-t\">&lt;/div</span>&gt;  <span class=\"tok-c\">&lt;!-- active tab only --&gt;</span>\n  <span class=\"tok-t\">&lt;/div</span>&gt;\n<span class=\"tok-t\">&lt;/div</span>&gt;</code></pre></div>\n<p>The structure follows the AjaxControlToolkit <code>ajax__tab_*</code> classes that the kit's tab sheet (<code>.tb-&lt;theme&gt;</code>) styles; put the theme in <code>cssClass</code> (<code>cssClass=&quot;tb-modern&quot;</code>). Ids are unique per component instance. <code>TabItem.visible: false</code> is honoured (header and panel are not rendered and the tab is skipped by the keyboard); <code>enabled: false</code> disables the button. Keyboard: ArrowLeft/ArrowRight move to the previous/next <strong>selectable</strong> tab (enabled and visible), Home/End jump to the first/last one. The header is a <code>ul</code>, not the toolkit's <code>div</code>, and the kit's &quot;menu + panel&quot; tab variant is not emitted.</p>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">html</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-html\"><span class=\"tok-t\">&lt;wf-tabs</span><span class=\"tok-k\"> [controller]</span>=<span class=\"tok-s\">&quot;tabs&quot;</span>&gt;\n  <span class=\"tok-t\">&lt;ng-template</span> #tabContent let-tab&gt;\n    @switch (tab.id) {\n      @case (<span class=\"tok-s\">&quot;overview&quot;</span>) { <span class=\"tok-t\">&lt;p</span>&gt;Overview panel.<span class=\"tok-t\">&lt;/p</span>&gt; }\n      @case (<span class=\"tok-s\">&quot;details&quot;</span>) { <span class=\"tok-t\">&lt;p</span>&gt;Details panel.<span class=\"tok-t\">&lt;/p</span>&gt; }\n    }\n  <span class=\"tok-t\">&lt;/ng-template</span>&gt;\n<span class=\"tok-t\">&lt;/wf-tabs</span>&gt;</code></pre></div>\n<p>Gotchas: the component subscribes to <code>activeTabChanged</code> only. <code>TabsController.setTabs()</code> emits nothing, so call the component's public <code>refresh()</code> (for example through a <code>viewChild</code>) after replacing tabs. Replacing the <code>controller</code> input refreshes automatically.</p>\n","wf-modal-webformsmodalcomponent":"<h3 id=\"53-wf-modal-webformsmodalcomponent\">5.3 <code>wf-modal</code> (<code>WebFormsModalComponent</code>)<a class=\"anchor\" href=\"#53-wf-modal-webformsmodalcomponent\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Kind</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>behavior</code></td><td><code>@Input({ required: true })</code></td><td><code>ModalBehavior</code></td><td>--</td><td>Behavior to render.</td></tr><tr><td><code>title</code></td><td><code>@Input()</code></td><td><code>string</code></td><td><code>&quot;Dialog&quot;</code></td><td>Header text.</td></tr><tr><td><code>okText</code> / <code>cancelText</code></td><td><code>@Input()</code></td><td><code>string</code></td><td><code>&quot;OK&quot;</code> / <code>&quot;Cancel&quot;</code></td><td>Footer button labels.</td></tr><tr><td><code>showFooter</code></td><td><code>@Input()</code></td><td><code>boolean</code></td><td><code>true</code></td><td>Show the OK/Cancel footer.</td></tr><tr><td><code>cssClass</code></td><td><code>@Input()</code></td><td><code>string</code></td><td><code>&quot;&quot;</code></td><td>Appended to the backdrop element.</td></tr></tbody></table></div>\n<p>The body is projected with <code>&lt;ng-content&gt;</code>. Nothing is rendered unless <code>behavior.isOpen</code>; open it with <code>behavior.show()</code>. The component subscribes to the behavior's <code>shown</code> and <code>hidden</code> events. Escape (a document-level key listener) and a click on the backdrop call <code>behavior.handleCancel()</code>; the header close button does the same; the OK button calls <code>behavior.handleOk()</code>. Markup: <code>div.modal.fade.show.d-block[role=dialog][aria-modal=true][aria-labelledby]</code> (inline backdrop <code>background-color: var(--wf-backdrop, rgba(0,0,0,0.5))</code>) containing <code>.modal-dialog &gt; .modal-content</code> with <code>.modal-header</code> (<code>h5.modal-title</code>, <code>button.btn-close</code>), <code>.modal-body</code> and <code>.modal-footer</code>.</p>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">html</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-html\"><span class=\"tok-t\">&lt;button</span><span class=\"tok-k\"> type</span>=<span class=\"tok-s\">&quot;button&quot;</span><span class=\"tok-k\"> (click)</span>=<span class=\"tok-s\">&quot;modal.show()&quot;</span>&gt;Delete...<span class=\"tok-t\">&lt;/button</span>&gt;\n<span class=\"tok-t\">&lt;wf-modal</span><span class=\"tok-k\"> [behavior]</span>=<span class=\"tok-s\">&quot;modal&quot;</span><span class=\"tok-k\"> title</span>=<span class=\"tok-s\">&quot;Confirm&quot;</span><span class=\"tok-k\"> okText</span>=<span class=\"tok-s\">&quot;Delete&quot;</span><span class=\"tok-k\"> cancelText</span>=<span class=\"tok-s\">&quot;Keep&quot;</span>&gt;\n  <span class=\"tok-t\">&lt;p</span>&gt;Delete this record?<span class=\"tok-t\">&lt;/p</span>&gt;\n<span class=\"tok-t\">&lt;/wf-modal</span>&gt;</code></pre></div>\n<p>Focus and scrolling (same as the React adapter): when the dialog opens it receives focus, Tab / Shift+Tab are trapped inside it, <code>document.body</code> scroll is locked (<code>overflow: hidden</code>, restored on close) and focus returns to the previously focused element on close. Change the backdrop colour with the CSS variable <code>--wf-backdrop</code> (for example <code>.md-dark { --wf-backdrop: rgba(0,0,0,.75) }</code>). Theme it with <code>cssClass=&quot;md-modern&quot;</code> plus <code>modern-full.css</code>.</p>\n<p>Gotchas: <code>onOk</code> / <code>onCancel</code> belong on the <code>ModalBehavior</code> options, not on the component (it has no <code>@Output</code>s). <code>aria-describedby</code> is not emitted.</p>\n","wf-tree-view-webformstreeviewcomponent":"<h3 id=\"54-wf-tree-view-webformstreeviewcomponent\">5.4 <code>wf-tree-view</code> (<code>WebFormsTreeViewComponent</code>)<a class=\"anchor\" href=\"#54-wf-tree-view-webformstreeviewcomponent\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Kind</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>controller</code></td><td><code>@Input({ required: true })</code></td><td><code>TreeViewController</code></td><td>--</td><td>Call <code>dataBind()</code> / <code>setNodes()</code> yourself.</td></tr><tr><td><code>cssClass</code></td><td><code>@Input()</code></td><td><code>string | string[] | Set&lt;string&gt; | { [klass: string]: unknown }</code></td><td><code>&quot;&quot;</code></td><td>Class(es) on the root <code>div.wf-treeview</code> (<code>ngClass</code> semantics). Put the kit theme here: <code>cssClass=&quot;tv-modern&quot;</code>.</td></tr><tr><td><code>ariaLabel</code></td><td><code>@Input()</code></td><td><code>string</code></td><td><code>&quot;Tree&quot;</code></td><td>Accessible name of the tree.</td></tr><tr><td><code>#nodeTemplate</code></td><td><code>@ContentChild</code></td><td><code>TemplateRef</code></td><td>--</td><td>Replaces the node label. Context <code>{ $implicit: TreeNode, level }</code>.</td></tr></tbody></table></div>\n<p>Behavior: the component re-renders on <code>controller.stateChanged</code>. Clicking a row selects the node; the arrow button toggles expansion; checkboxes appear when <code>controller.shouldShowCheckBox(node)</code> is true (<code>showCheckBoxes</code>). Keyboard: ArrowLeft and ArrowRight collapse and expand. <code>showLines</code> adds <code>wf-treeview-lines</code> to the root. <code>expandDepth: -1</code> leaves each node's <code>expanded</code> flag alone. Roles: <code>ul[role=tree]</code>, <code>li[role=treeitem]</code> (<code>aria-level</code>, <code>aria-expanded</code>, <code>aria-selected</code>), <code>div[role=group]</code> for children.</p>\n<p>Markup: <code>div.wf-treeview.{cssClass} &gt; ul[role=tree] &gt; li[role=treeitem]</code>. Every default node label is an <code>&lt;a&gt;</code> with class <code>root</code> (depth 0), <code>parent</code> or <code>leaf</code>, plus <code>selected</code> (<code>&lt;a href=&quot;#&quot; role=&quot;button&quot;&gt;</code> when the node has no <code>navigateUrl</code>; the click is default-prevented). Child groups are <code>&lt;div id=&quot;wftvN_n&lt;path&gt;Nodes&quot; role=&quot;group&quot;&gt;&lt;ul&gt;...&lt;/ul&gt;&lt;/div&gt;</code>: the id always ends in <code>Nodes</code>, matching the kit's <code>div[id$=&quot;Nodes&quot;]</code>. Node images (<code>imageUrl</code> / <code>expandedImageUrl</code>) render as <code>&lt;img&gt;</code> before the label. Nodes are <code>ul</code>/<code>li</code>, not the nested tables of ASP.NET, so load <code>adapters.css</code> after the theme. <code>#nodeTemplate</code> replaces only the label <code>&lt;a&gt;</code>.</p>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">html</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-html\"><span class=\"tok-t\">&lt;wf-tree-view</span><span class=\"tok-k\"> [controller]</span>=<span class=\"tok-s\">&quot;tree&quot;</span><span class=\"tok-k\"> ariaLabel</span>=<span class=\"tok-s\">&quot;Site map&quot;</span>&gt;\n  <span class=\"tok-t\">&lt;ng-template</span> #nodeTemplate let-node<span class=\"tok-k\"> let-level</span>=<span class=\"tok-s\">&quot;level&quot;</span>&gt;{{ level }}: <span class=\"tok-t\">&lt;b</span>&gt;{{ node.text }}<span class=\"tok-t\">&lt;/b</span>&gt;<span class=\"tok-t\">&lt;/ng-template</span>&gt;\n<span class=\"tok-t\">&lt;/wf-tree-view</span>&gt;</code></pre></div>\n","wf-breadcrumb-webformsbreadcrumbcomponent":"<h3 id=\"55-wf-breadcrumb-webformsbreadcrumbcomponent\">5.5 <code>wf-breadcrumb</code> (<code>WebFormsBreadcrumbComponent</code>)<a class=\"anchor\" href=\"#55-wf-breadcrumb-webformsbreadcrumbcomponent\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Kind</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>controller</code></td><td><code>@Input()</code></td><td><code>SiteMapPathController</code></td><td>--</td><td>Wins when both <code>controller</code> and <code>items</code> are set.</td></tr><tr><td><code>items</code></td><td><code>@Input()</code></td><td><code>{ text?, title?, url?, navigateUrl? }[]</code></td><td>--</td><td>Plain trail; the last item is the current page. <code>text</code> falls back to <code>title</code>.</td></tr><tr><td><code>currentUrl</code></td><td><code>@Input()</code></td><td><code>string</code></td><td>--</td><td>With a controller, calls <code>controller.dataBind(currentUrl)</code> on every change.</td></tr><tr><td><code>cssClass</code></td><td><code>@Input()</code></td><td><code>string | string[] | Set&lt;string&gt; | { [klass: string]: unknown }</code></td><td><code>&quot;&quot;</code></td><td>Class(es) on the <strong>inner <code>&lt;span&gt;</code></strong>. Put the kit theme here: <code>cssClass=&quot;nv-modern&quot;</code>.</td></tr><tr><td><code>separator</code></td><td><code>@Input()</code></td><td><code>string</code></td><td>controller <code>pathSeparator</code>, else <code>&quot; / &quot;</code></td><td>Exposed on each separator as <code>data-separator</code>; the glyph is drawn by CSS.</td></tr><tr><td><code>ariaLabel</code></td><td><code>@Input()</code></td><td><code>string</code></td><td><code>&quot;breadcrumb&quot;</code></td><td>Label of the <code>&lt;nav&gt;</code>.</td></tr><tr><td><code>itemClick</code></td><td><code>@Output()</code></td><td><code>EventEmitter&lt;item&gt;</code></td><td>--</td><td>Emits the clicked plain item or <code>SiteMapPathItem</code>.</td></tr></tbody></table></div>\n<p>Markup (the kit's SiteMapPath structure; Bootstrap's <code>ol.breadcrumb</code> is gone): <code>nav.wf-breadcrumb &gt; span.{cssClass}</code> containing <code>a</code>, <code>span.sep[data-separator][aria-hidden]</code> and <code>span.current[aria-current=page]</code>. With plain <code>items</code> the last item is a non-link <code>span.current</code>; with a controller the current node is a link only when the controller says so (<code>isLink</code>). Without the kit or your own <code>.sep::before</code> rule the separator is invisible because the element is empty.</p>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">html</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-html\"><span class=\"tok-t\">&lt;wf-breadcrumb</span><span class=\"tok-k\"> [controller]</span>=<span class=\"tok-s\">&quot;path&quot;</span><span class=\"tok-k\"> currentUrl</span>=<span class=\"tok-s\">&quot;/staff/engineering&quot;</span><span class=\"tok-k\"> (itemClick)</span>=<span class=\"tok-s\">&quot;log($event)&quot;</span> /&gt;\n<span class=\"tok-t\">&lt;wf-breadcrumb</span><span class=\"tok-k\"> [items]</span>=<span class=\"tok-s\">&quot;[{ text: 'Home', url: '/' }, { text: 'Staff' }]&quot;</span> /&gt;</code></pre></div>\n<p>Gotchas: without <code>currentUrl</code> a controller is <strong>not</strong> data-bound by the component; call <code>dataBind()</code> yourself. <code>itemClick</code> does not prevent navigation.</p>\n","wf-menu-webformsmenucomponent":"<h3 id=\"56-wf-menu-webformsmenucomponent\">5.6 <code>wf-menu</code> (<code>WebFormsMenuComponent</code>)<a class=\"anchor\" href=\"#56-wf-menu-webformsmenucomponent\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Kind</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>controller</code></td><td><code>@Input()</code></td><td><code>MenuController</code></td><td>--</td><td>Wins over <code>items</code>. Orientation, <code>staticDisplayLevels</code>, <code>maximumDynamicDisplayLevels</code> and <code>disappearAfter</code> come from it. Call <code>dataBind()</code> yourself.</td></tr><tr><td><code>items</code></td><td><code>@Input()</code></td><td><code>(MenuItem | MenuItemOptions)[]</code></td><td>--</td><td>Plain items; an internal controller is built.</td></tr><tr><td><code>orientation</code></td><td><code>@Input()</code></td><td><code>'horizontal' | 'vertical'</code></td><td><code>'horizontal'</code></td><td>Plain-items mode only.</td></tr><tr><td><code>cssClass</code></td><td><code>@Input()</code></td><td><code>string</code></td><td><code>&quot;&quot;</code></td><td>Extra class(es) on the root. Put the kit theme here: <code>cssClass=&quot;mn-modern&quot;</code>; <code>mn-vertical</code> is added for vertical menus.</td></tr><tr><td><code>ariaLabel</code></td><td><code>@Input()</code></td><td><code>string</code></td><td><code>&quot;Menu&quot;</code></td><td><code>aria-label</code> of the root <code>role=&quot;navigation&quot;</code> element.</td></tr><tr><td><code>itemClick</code></td><td><code>@Output()</code></td><td><code>EventEmitter&lt;MenuItem&gt;</code></td><td>--</td><td>Emitted after <code>controller.clickItem</code> succeeded (not cancelled).</td></tr></tbody></table></div>\n<p>Flyouts open on hover, click and keys (Arrow keys move between items, Down/Right opens a flyout, Left/Escape closes it) and close after <code>controller.disappearAfter</code> ms once the pointer leaves, or on Escape. Roles: <code>ul[role=menubar]</code>, <code>ul[role=menu]</code>, <code>a[role=menuitem]</code> with <code>aria-haspopup</code> / <code>aria-expanded</code>.</p>\n<p>Markup: <code>div[role=navigation].{cssClass} (navbar ... | nav flex-column mn-vertical) &gt; ul.static[role=menubar] &gt; li &gt; a.nav-link</code> (<code>selected active</code> for a selected item, <code>has-popup</code> for an item with a flyout) and flyouts as <code>ul.dynamic[role=menu]</code>. The root is a <code>div</code> (not a <code>&lt;nav&gt;</code>) so the kit's <code>div.mn-&lt;theme&gt;</code> selector matches. Load <code>adapters.css</code> after the theme to reset flyout positioning.</p>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">html</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-html\"><span class=\"tok-t\">&lt;wf-menu</span><span class=\"tok-k\"> [controller]</span>=<span class=\"tok-s\">&quot;menu&quot;</span><span class=\"tok-k\"> (itemClick)</span>=<span class=\"tok-s\">&quot;onPick($event)&quot;</span> /&gt;\n<span class=\"tok-t\">&lt;wf-menu</span><span class=\"tok-k\"> [items]</span>=<span class=\"tok-s\">&quot;[{ text: 'Home', navigateUrl: '/' }]&quot;</span><span class=\"tok-k\"> orientation</span>=<span class=\"tok-s\">&quot;vertical&quot;</span> /&gt;</code></pre></div>\n<p>Gotchas:</p>\n<ul><li>A cancel in the <code>menuItemClick</code> event blocks selection and <code>itemClick</code>, but it <strong>cannot stop the anchor's native navigation</strong>.</li><li><code>getStaticItems()</code> is flat, so nested static levels render as sibling <code>li</code> elements rather than nested lists.</li></ul>\n<hr>\n"},"angular-5a-the-account-components":{"overview":"<p>Seven standalone components draw the Login family and its siblings. They all take a required <code>controller</code> input and a <code>cssClass</code> input that you set to the theme class, for example <code>lg-modern</code> (see section 12). They emit the ASP.NET-style markup the <code>lg-&lt;theme&gt;</code> sheet targets: a <code>table.lg-&lt;theme&gt;</code> for the forms, <code>a.lg-&lt;theme&gt;</code> for <code>wf-login-status</code> and <code>span.lg-&lt;theme&gt;</code> for <code>wf-login-name</code>. Each root also carries a fixed hook class (<code>wf-login</code>, <code>wf-change-password</code>, <code>wf-password-recovery</code>, <code>wf-create-user</code>, <code>wf-login-status</code>, <code>wf-login-name</code>, <code>wf-login-view</code>).</p>\n<div class=\"table-scroll\"><table><thead><tr><th>Selector (class)</th><th>Controller</th><th>Other inputs / outputs</th><th>Renders</th></tr></thead><tbody><tr><td><code>wf-login</code> (<code>WebFormsLoginComponent</code>)</td><td><code>LoginController</code></td><td>inputs <code>titleText</code>, <code>userNameLabelText</code>, <code>passwordLabelText</code>, <code>rememberMeText</code>, <code>loginButtonText</code>; output <code>loggedIn</code> (the user)</td><td>Title, user name, password, remember-me, failure text, Log In button and the optional links. Hidden while signed in unless <code>visibleWhenLoggedIn</code>.</td></tr><tr><td><code>wf-login-status</code> (<code>WebFormsLoginStatusComponent</code>)</td><td><code>LoginStatusController</code></td><td>output <code>loggedOut</code></td><td>One link reading Login or Logout; clicking it while signed in calls <code>logout()</code>.</td></tr><tr><td><code>wf-login-name</code> (<code>WebFormsLoginNameComponent</code>)</td><td><code>LoginNameController</code></td><td>none</td><td>The formatted greeting; nothing when nobody is signed in.</td></tr><tr><td><code>wf-login-view</code> (<code>WebFormsLoginViewComponent</code>)</td><td><code>LoginViewController</code></td><td>content slot <code>#viewTemplate</code></td><td>Your template with context <code>{ $implicit: view }</code>; switch on <code>view.type</code> (<code>&quot;Anonymous&quot;</code>, <code>&quot;RoleGroup&quot;</code>, <code>&quot;LoggedIn&quot;</code>; also <code>view.matchedRole</code>, <code>view.user</code>).</td></tr><tr><td><code>wf-change-password</code> (<code>WebFormsChangePasswordComponent</code>)</td><td><code>ChangePasswordController</code></td><td>label and button text inputs; output <code>continued</code></td><td>The three password fields, then the success view with Continue.</td></tr><tr><td><code>wf-password-recovery</code> (<code>WebFormsPasswordRecoveryComponent</code>)</td><td><code>PasswordRecoveryController</code></td><td>label and button text inputs</td><td>The user-name step, the optional question step, then the success text.</td></tr><tr><td><code>wf-create-user-wizard</code> (<code>WebFormsCreateUserWizardComponent</code>)</td><td><code>CreateUserWizardController</code></td><td>label and button text inputs, <code>displayQuestionAndAnswer</code>; outputs <code>created</code> (the user), <code>continued</code></td><td>User name, password, confirm, e-mail (and question / answer), then the complete step.</td></tr></tbody></table></div>\n<p><strong>Binding.</strong> All seven are <code>OnPush</code>. Each keeps <code>controller.getState()</code> in a signal and refreshes it on <code>stateChanged</code>; the subscription is made in the <code>controller</code> input setter and released in <code>ngOnDestroy</code>. They do not use <code>viewModel()</code> for this, because <code>viewModel()</code> calls <code>inject()</code> and an input setter is not an injection context (it would throw <code>NG0203</code>). <code>wf-login</code> also refreshes on <code>SecurityManager.currentUserChanged</code>, so the form reappears after <code>wf-login-status</code> signs the user out.</p>\n<p><strong>Validation messages.</strong> <code>ChangePasswordController.getState()</code> recomputes <code>validationErrors</code> on every call, so they exist while the user is still typing. The components show them only after the first submit; a provider failure (<code>failureMessage</code>) is shown straight away.</p>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">ts</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-ts\">@<span class=\"tok-t\">Component</span>({\n  standalone: <span class=\"tok-k\">true</span>,\n  imports: [<span class=\"tok-t\">WebFormsLoginComponent</span>, <span class=\"tok-t\">WebFormsLoginNameComponent</span>, <span class=\"tok-t\">WebFormsLoginStatusComponent</span>],\n  template: <span class=\"tok-s\">`&lt;wf-login [controller]=&quot;login&quot; cssClass=&quot;lg-modern&quot; /&gt;\n             &lt;wf-login-name [controller]=&quot;name&quot; cssClass=&quot;lg-modern&quot; /&gt; &lt;wf-login-status [controller]=&quot;status&quot; cssClass=&quot;lg-modern&quot; /&gt;`</span>,\n})\n<span class=\"tok-k\">export</span> <span class=\"tok-k\">class</span> <span class=\"tok-t\">DemoComponent</span> {\n  <span class=\"tok-k\">private</span> provider = <span class=\"tok-k\">new</span> <span class=\"tok-t\">InMemoryAuthProvider</span>({ users: [{ userName: <span class=\"tok-s\">&quot;ann&quot;</span>, password: <span class=\"tok-s\">&quot;pw&quot;</span>, roles: [<span class=\"tok-s\">&quot;Admin&quot;</span>] }] });\n  login = <span class=\"tok-k\">new</span> <span class=\"tok-t\">LoginController</span>({ provider: <span class=\"tok-k\">this</span>.provider });\n  status = <span class=\"tok-k\">new</span> <span class=\"tok-t\">LoginStatusController</span>({ provider: <span class=\"tok-k\">this</span>.provider });\n  name = <span class=\"tok-k\">new</span> <span class=\"tok-t\">LoginNameController</span>({ provider: <span class=\"tok-k\">this</span>.provider });\n}</code></pre></div>\n<p>The runnable version is <code>samples/angular/src/app/login-demo.component.ts</code> and <code>account-demo.component.ts</code>.</p>\n<hr>\n"},"angular-helpers-viewmodel-fromdispatcher-onevent":{"overview":"<p>For controllers without an adapter, the package exports three small functions (promoted from the Volume 3 examples). Controllers expose <code>EventDispatcher</code>s, not signals or Observables; these are the whole bridge.</p>\n<div class=\"table-scroll\"><table><thead><tr><th>Function</th><th>Returns</th><th>Needs injection context</th><th>Behavior</th></tr></thead><tbody><tr><td><code>viewModel(controller, project)</code></td><td><code>Signal&lt;V&gt;</code></td><td>yes (registers <code>DestroyRef.onDestroy</code>)</td><td>Read-only signal holding <code>project(controller)</code>, recomputed after every <code>stateChanged</code>. <code>project</code> must return a <strong>new object</strong> each time (signals notify on identity change).</td></tr><tr><td><code>fromDispatcher(dispatcher)</code></td><td><code>Observable&lt;{ sender, args }&gt;</code></td><td>no</td><td>One emission per event; unsubscribes when the Observable is unsubscribed.</td></tr><tr><td><code>onEvent(dispatcher, handler)</code></td><td><code>void</code></td><td>yes</td><td>Runs <code>handler(sender, args)</code> for every emission and stops when the component is destroyed.</td></tr></tbody></table></div>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">ts</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-ts\"><span class=\"tok-k\">export</span> <span class=\"tok-k\">class</span> <span class=\"tok-t\">GridPanel</span> {\n  <span class=\"tok-k\">readonly</span> grid = <span class=\"tok-k\">new</span> <span class=\"tok-t\">GridViewController</span>&lt;<span class=\"tok-t\">Product</span>&gt;({ <span class=\"tok-c\">/* ... */</span> });\n  <span class=\"tok-k\">readonly</span> view = <span class=\"tok-f\">viewModel</span>(<span class=\"tok-k\">this</span>.grid, (g) =&gt; ({ rows: g.visibleRows, page: g.options.pageIndex }));\n  <span class=\"tok-f\">constructor</span>() { <span class=\"tok-f\">onEvent</span>(<span class=\"tok-k\">this</span>.grid.rowDeleted, () =&gt; console.<span class=\"tok-f\">log</span>(<span class=\"tok-s\">&quot;deleted&quot;</span>)); }\n}</code></pre></div>\n<p>(Illustrative, not compiled. <code>rowDeleted</code> is the GridView event listed in section 3.6.)</p>\n<hr>\n"},"angular-examples-grid-and-repeater":{"examples":"<p>All of these assume:</p>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">ts</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-ts\"><span class=\"tok-k\">import</span> { <span class=\"tok-t\">ChangeDetectionStrategy</span>, <span class=\"tok-t\">ChangeDetectorRef</span>, <span class=\"tok-t\">Component</span>, <span class=\"tok-t\">OnDestroy</span>, <span class=\"tok-t\">OnInit</span> } <span class=\"tok-k\">from</span> <span class=\"tok-s\">&quot;@angular/core&quot;</span>;\n<span class=\"tok-k\">import</span> { <span class=\"tok-t\">GridViewController</span>, <span class=\"tok-t\">RepeaterController</span> } <span class=\"tok-k\">from</span> <span class=\"tok-s\">&quot;@wf-controls/core&quot;</span>;\n<span class=\"tok-k\">import</span> { <span class=\"tok-t\">WebFormsGridViewComponent</span>, <span class=\"tok-t\">WebFormsRepeaterComponent</span> } <span class=\"tok-k\">from</span> <span class=\"tok-s\">&quot;@wf-controls/angular&quot;</span>;\n\n<span class=\"tok-k\">interface</span> <span class=\"tok-t\">Product</span> { id: number; name: string; category: string; price: number; }\n<span class=\"tok-k\">const</span> products: <span class=\"tok-t\">Product</span>[] = [\n  { id: <span class=\"tok-n\">1</span>, name: <span class=\"tok-s\">&quot;Hammer&quot;</span>, category: <span class=\"tok-s\">&quot;Hardware&quot;</span>, price: <span class=\"tok-n\">12.5</span> },\n  { id: <span class=\"tok-n\">2</span>, name: <span class=\"tok-s\">&quot;Saw&quot;</span>, category: <span class=\"tok-s\">&quot;Hardware&quot;</span>, price: <span class=\"tok-n\">20</span> }\n];</code></pre></div>\n<ul class=\"aa-doc-index\"><li><a href=\"#/api/adapters/angular-examples-grid-and-repeater/examples/71-quick-start\">Quick start</a></li><li><a href=\"#/api/adapters/angular-examples-grid-and-repeater/examples/72-grid-with-inline-edit-and-a-delete-veto\">Grid with inline edit and a delete veto</a></li><li><a href=\"#/api/adapters/angular-examples-grid-and-repeater/examples/73-repeater-with-edit-select-and-add\">Repeater with edit, select and add</a></li></ul><h3 id=\"71-quick-start\">7.1 Quick start<a class=\"anchor\" href=\"#71-quick-start\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">ts</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-ts\">@<span class=\"tok-t\">Component</span>({\n  selector: <span class=\"tok-s\">&quot;app-quick-start&quot;</span>,\n  standalone: <span class=\"tok-k\">true</span>,\n  imports: [<span class=\"tok-t\">WebFormsGridViewComponent</span>],\n  template: <span class=\"tok-s\">`&lt;wf-grid-view [controller]=&quot;grid&quot; /&gt;`</span>\n})\n<span class=\"tok-k\">export</span> <span class=\"tok-k\">class</span> <span class=\"tok-t\">QuickStartComponent</span> <span class=\"tok-k\">implements</span> <span class=\"tok-t\">OnInit</span> {\n  <span class=\"tok-k\">readonly</span> grid = <span class=\"tok-k\">new</span> <span class=\"tok-t\">GridViewController</span>&lt;<span class=\"tok-t\">Product</span>&gt;({\n    id: <span class=\"tok-s\">&quot;gv&quot;</span>, dataKeyField: <span class=\"tok-s\">&quot;id&quot;</span>, dataSource: products, allowPaging: <span class=\"tok-k\">true</span>, pageSize: <span class=\"tok-n\">5</span>, allowSorting: <span class=\"tok-k\">true</span>,\n    cssClass: <span class=\"tok-s\">&quot;table&quot;</span>,\n    columns: [\n      { <span class=\"tok-k\">type</span>: <span class=\"tok-s\">&quot;bound&quot;</span>, key: <span class=\"tok-s\">&quot;name&quot;</span>, dataField: <span class=\"tok-s\">&quot;name&quot;</span>, headerText: <span class=\"tok-s\">&quot;Name&quot;</span>, sortable: <span class=\"tok-k\">true</span> },\n      { <span class=\"tok-k\">type</span>: <span class=\"tok-s\">&quot;bound&quot;</span>, key: <span class=\"tok-s\">&quot;price&quot;</span>, dataField: <span class=\"tok-s\">&quot;price&quot;</span>, headerText: <span class=\"tok-s\">&quot;Price&quot;</span>, sortable: <span class=\"tok-k\">true</span>,\n        format: (v) =&gt; <span class=\"tok-s\">`$${Number(v).toFixed(2)}`</span> },\n      { <span class=\"tok-k\">type</span>: <span class=\"tok-s\">&quot;template&quot;</span>, key: <span class=\"tok-s\">&quot;actions&quot;</span>, headerText: <span class=\"tok-s\">&quot;Actions&quot;</span> }\n    ]\n  });\n  <span class=\"tok-f\">ngOnInit</span>(): <span class=\"tok-k\">void</span> { <span class=\"tok-k\">void</span> <span class=\"tok-k\">this</span>.grid.<span class=\"tok-f\">dataBind</span>(); }\n}</code></pre></div>\n<p>Paging (Previous/Next), sorting (header buttons) and the Select/Edit/Delete buttons in the <code>actions</code> column work with no further code.</p>\n<h3 id=\"72-grid-with-inline-edit-and-a-delete-veto\">7.2 Grid with inline edit and a delete veto<a class=\"anchor\" href=\"#72-grid-with-inline-edit-and-a-delete-veto\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">ts</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-ts\">@<span class=\"tok-t\">Component</span>({\n  selector: <span class=\"tok-s\">&quot;app-edit-grid&quot;</span>,\n  standalone: <span class=\"tok-k\">true</span>,\n  imports: [<span class=\"tok-t\">WebFormsGridViewComponent</span>],\n  template: <span class=\"tok-s\">`\n    &lt;wf-grid-view [controller]=&quot;grid&quot;&gt;\n      &lt;ng-template #editTemplate let-row let-index=&quot;index&quot; let-save=&quot;save&quot; let-cancel=&quot;cancel&quot;&gt;\n        &lt;input #nameBox [value]=&quot;row.name&quot; /&gt;\n        &lt;button type=&quot;button&quot; (click)=&quot;save({ name: nameBox.value })&quot;&gt;Update&lt;/button&gt;\n        &lt;button type=&quot;button&quot; (click)=&quot;cancel()&quot;&gt;Cancel&lt;/button&gt;\n      &lt;/ng-template&gt;\n    &lt;/wf-grid-view&gt;`</span>\n})\n<span class=\"tok-k\">export</span> <span class=\"tok-k\">class</span> <span class=\"tok-t\">EditGridComponent</span> <span class=\"tok-k\">implements</span> <span class=\"tok-t\">OnInit</span> {\n  <span class=\"tok-k\">readonly</span> grid = <span class=\"tok-k\">new</span> <span class=\"tok-t\">GridViewController</span>&lt;<span class=\"tok-t\">Product</span>&gt;({\n    id: <span class=\"tok-s\">&quot;gvEdit&quot;</span>, dataKeyField: <span class=\"tok-s\">&quot;id&quot;</span>, dataSource: products,\n    columns: [\n      { <span class=\"tok-k\">type</span>: <span class=\"tok-s\">&quot;bound&quot;</span>, key: <span class=\"tok-s\">&quot;name&quot;</span>, dataField: <span class=\"tok-s\">&quot;name&quot;</span>, headerText: <span class=\"tok-s\">&quot;Name&quot;</span> },\n      { <span class=\"tok-k\">type</span>: <span class=\"tok-s\">&quot;template&quot;</span>, key: <span class=\"tok-s\">&quot;actions&quot;</span>, headerText: <span class=\"tok-s\">&quot;&quot;</span> }\n    ]\n  });\n  <span class=\"tok-f\">constructor</span>() {\n    <span class=\"tok-k\">this</span>.grid.rowDeleting.<span class=\"tok-f\">subscribe</span>((_s, e) =&gt; { <span class=\"tok-k\">if</span> (e.dataItem.price &gt; <span class=\"tok-n\">15</span>) e.cancel = <span class=\"tok-k\">true</span>; });\n  }\n  <span class=\"tok-f\">ngOnInit</span>(): <span class=\"tok-k\">void</span> { <span class=\"tok-k\">void</span> <span class=\"tok-k\">this</span>.grid.<span class=\"tok-f\">dataBind</span>(); }\n}</code></pre></div>\n<h3 id=\"73-repeater-with-edit-select-and-add\">7.3 Repeater with edit, select and add<a class=\"anchor\" href=\"#73-repeater-with-edit-select-and-add\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">ts</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-ts\">@<span class=\"tok-t\">Component</span>({\n  selector: <span class=\"tok-s\">&quot;app-repeater&quot;</span>,\n  standalone: <span class=\"tok-k\">true</span>,\n  imports: [<span class=\"tok-t\">WebFormsRepeaterComponent</span>],\n  template: <span class=\"tok-s\">`\n    &lt;wf-repeater [controller]=&quot;rep&quot; [createItem]=&quot;make&quot;&gt;\n      &lt;ng-template #itemTemplate let-item let-i=&quot;index&quot; let-command=&quot;command&quot;&gt;\n        {{ item.name }} &lt;button type=&quot;button&quot; (click)=&quot;command('Edit')&quot;&gt;Edit&lt;/button&gt;\n      &lt;/ng-template&gt;\n      &lt;ng-template #editItemTemplate let-item let-save=&quot;save&quot; let-cancel=&quot;cancel&quot;&gt;\n        &lt;button type=&quot;button&quot; (click)=&quot;save({ name: item.name + '!' })&quot;&gt;Save&lt;/button&gt;\n        &lt;button type=&quot;button&quot; (click)=&quot;cancel()&quot;&gt;Cancel&lt;/button&gt;\n      &lt;/ng-template&gt;\n    &lt;/wf-repeater&gt;`</span>\n})\n<span class=\"tok-k\">export</span> <span class=\"tok-k\">class</span> <span class=\"tok-t\">RepeaterComponent</span> <span class=\"tok-k\">implements</span> <span class=\"tok-t\">OnInit</span> {\n  <span class=\"tok-k\">readonly</span> rep = <span class=\"tok-k\">new</span> <span class=\"tok-t\">RepeaterController</span>&lt;<span class=\"tok-t\">Product</span>&gt;({\n    id: <span class=\"tok-s\">&quot;rp&quot;</span>, dataKeyField: <span class=\"tok-s\">&quot;id&quot;</span>, dataSource: products, allowUserToAddItems: <span class=\"tok-k\">true</span>, allowUserToDeleteItems: <span class=\"tok-k\">true</span>\n  });\n  make = (): <span class=\"tok-t\">Product</span> =&gt; ({ id: <span class=\"tok-t\">Date</span>.<span class=\"tok-f\">now</span>(), name: <span class=\"tok-s\">&quot;New&quot;</span>, category: <span class=\"tok-s\">&quot;&quot;</span>, price: <span class=\"tok-n\">0</span> });\n  <span class=\"tok-f\">ngOnInit</span>(): <span class=\"tok-k\">void</span> { <span class=\"tok-k\">void</span> <span class=\"tok-k\">this</span>.rep.<span class=\"tok-f\">dataBind</span>(); }\n}</code></pre></div>\n<p>The <code>make</code> field is an arrow function so <code>this</code> is not needed; <code>createItem</code> is invoked as a plain callback.</p>\n<hr>\n"},"angular-headless-controllers-inside-angular-the-manual-pattern":{"overview":"<p>Accordion, Calendar, the validators and the other behaviors have no adapter, so drive them with controllers and <code>markForCheck()</code> (or the section 6 helpers). The example below hand-wires modal, tabs, breadcrumb and menu, which is what <code>wf-modal</code>, <code>wf-tabs</code>, <code>wf-breadcrumb</code> and <code>wf-menu</code> now do for you; it is kept as the pattern to copy for the controllers that lack an adapter. The same one-line contract as the adapters applies: subscribe to the controller event and mark the view dirty; unsubscribe in <code>ngOnDestroy</code> (every <code>subscribe</code> returns an unsubscribe function).</p>\n","the-manual-pattern-modal-tabs-breadcrumb-menu":"<h3 id=\"81-the-manual-pattern-modal-tabs-breadcrumb-menu\">8.1 The manual pattern (modal, tabs, breadcrumb, menu)<a class=\"anchor\" href=\"#81-the-manual-pattern-modal-tabs-breadcrumb-menu\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">ts</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-ts\"><span class=\"tok-k\">import</span> {\n  <span class=\"tok-t\">TabsController</span>, <span class=\"tok-t\">ModalBehavior</span>, <span class=\"tok-t\">SiteMapDataSource</span>, <span class=\"tok-t\">SiteMapPathController</span>, <span class=\"tok-t\">MenuController</span>,\n  <span class=\"tok-k\">type</span> <span class=\"tok-t\">MenuItem</span>, <span class=\"tok-k\">type</span> <span class=\"tok-t\">SiteMapPathItem</span>\n} <span class=\"tok-k\">from</span> <span class=\"tok-s\">&quot;@wf-controls/core&quot;</span>;\n\n<span class=\"tok-k\">const</span> siteMap = <span class=\"tok-k\">new</span> <span class=\"tok-t\">SiteMapDataSource</span>({\n  id: <span class=\"tok-s\">&quot;sm&quot;</span>,\n  siteMap: { key: <span class=\"tok-s\">&quot;home&quot;</span>, url: <span class=\"tok-s\">&quot;/&quot;</span>, title: <span class=\"tok-s\">&quot;Home&quot;</span>, childNodes: [{ key: <span class=\"tok-s\">&quot;about&quot;</span>, url: <span class=\"tok-s\">&quot;/about&quot;</span>, title: <span class=\"tok-s\">&quot;About&quot;</span> }] }\n});\n\n@<span class=\"tok-t\">Component</span>({\n  selector: <span class=\"tok-s\">&quot;app-headless&quot;</span>,\n  standalone: <span class=\"tok-k\">true</span>,\n  changeDetection: <span class=\"tok-t\">ChangeDetectionStrategy</span>.<span class=\"tok-t\">OnPush</span>,\n  template: <span class=\"tok-s\">`\n    &lt;nav aria-label=&quot;breadcrumb&quot;&gt;\n      @for (c of crumbs; track c.url) {\n        @if (c.isLink) { &lt;a [href]=&quot;c.url&quot;&gt;{{ c.text }}&lt;/a&gt; } @else { &lt;span aria-current=&quot;page&quot;&gt;{{ c.text }}&lt;/span&gt; }\n      }\n    &lt;/nav&gt;\n    &lt;ul role=&quot;tablist&quot;&gt;\n      @for (t of tabs.tabs; track t.id; let i = $index) {\n        &lt;li&gt;&lt;button role=&quot;tab&quot; [attr.aria-selected]=&quot;i === tabs.activeTabIndex&quot; [disabled]=&quot;t.enabled === false&quot;\n          (click)=&quot;tabs.setActiveTab(i)&quot;&gt;{{ t.headerText }}&lt;/button&gt;&lt;/li&gt;\n      }\n    &lt;/ul&gt;\n    &lt;ul&gt;@for (m of menuItems; track m.value) { &lt;li&gt;{{ m.text }}&lt;/li&gt; }&lt;/ul&gt;\n    &lt;button type=&quot;button&quot; (click)=&quot;modal.show()&quot;&gt;Open&lt;/button&gt;\n    @if (open) {\n      &lt;div role=&quot;dialog&quot; aria-modal=&quot;true&quot;&gt;\n        &lt;button type=&quot;button&quot; (click)=&quot;modal.handleOk()&quot;&gt;OK&lt;/button&gt;\n        &lt;button type=&quot;button&quot; (click)=&quot;modal.handleCancel()&quot;&gt;Cancel&lt;/button&gt;\n      &lt;/div&gt;\n    }`</span>\n})\n<span class=\"tok-k\">export</span> <span class=\"tok-k\">class</span> <span class=\"tok-t\">HeadlessComponent</span> <span class=\"tok-k\">implements</span> <span class=\"tok-t\">OnInit</span>, <span class=\"tok-t\">OnDestroy</span> {\n  crumbs: <span class=\"tok-t\">SiteMapPathItem</span>[] = [];\n  menuItems: <span class=\"tok-t\">MenuItem</span>[] = [];\n  open = <span class=\"tok-k\">false</span>;\n  <span class=\"tok-k\">readonly</span> tabs = <span class=\"tok-k\">new</span> <span class=\"tok-t\">TabsController</span>({ tabs: [{ id: <span class=\"tok-s\">&quot;a&quot;</span>, headerText: <span class=\"tok-s\">&quot;A&quot;</span> }, { id: <span class=\"tok-s\">&quot;b&quot;</span>, headerText: <span class=\"tok-s\">&quot;B&quot;</span> }] });\n  <span class=\"tok-k\">readonly</span> modal = <span class=\"tok-k\">new</span> <span class=\"tok-t\">ModalBehavior</span>({ onOk: () =&gt; console.<span class=\"tok-f\">log</span>(<span class=\"tok-s\">&quot;ok&quot;</span>) });\n  <span class=\"tok-k\">private</span> offs: <span class=\"tok-t\">Array</span>&lt;() =&gt; unknown&gt; = [];\n  <span class=\"tok-f\">constructor</span>(<span class=\"tok-k\">private</span> <span class=\"tok-k\">readonly</span> cdr: <span class=\"tok-t\">ChangeDetectorRef</span>) {}\n  <span class=\"tok-k\">async</span> <span class=\"tok-f\">ngOnInit</span>(): <span class=\"tok-t\">Promise</span>&lt;<span class=\"tok-k\">void</span>&gt; {\n    <span class=\"tok-k\">this</span>.offs.<span class=\"tok-f\">push</span>(\n      <span class=\"tok-k\">this</span>.tabs.activeTabChanged.<span class=\"tok-f\">subscribe</span>(() =&gt; <span class=\"tok-k\">this</span>.cdr.<span class=\"tok-f\">markForCheck</span>()),\n      <span class=\"tok-k\">this</span>.modal.shown.<span class=\"tok-f\">subscribe</span>(() =&gt; { <span class=\"tok-k\">this</span>.open = <span class=\"tok-k\">true</span>; <span class=\"tok-k\">this</span>.cdr.<span class=\"tok-f\">markForCheck</span>(); }),\n      <span class=\"tok-k\">this</span>.modal.hidden.<span class=\"tok-f\">subscribe</span>(() =&gt; { <span class=\"tok-k\">this</span>.open = <span class=\"tok-k\">false</span>; <span class=\"tok-k\">this</span>.cdr.<span class=\"tok-f\">markForCheck</span>(); })\n    );\n    <span class=\"tok-k\">const</span> path = <span class=\"tok-k\">new</span> <span class=\"tok-t\">SiteMapPathController</span>({ id: <span class=\"tok-s\">&quot;p&quot;</span>, siteMapProvider: siteMap });\n    <span class=\"tok-k\">this</span>.crumbs = <span class=\"tok-k\">await</span> path.<span class=\"tok-f\">dataBind</span>(<span class=\"tok-s\">&quot;/about&quot;</span>);\n    <span class=\"tok-k\">const</span> menu = <span class=\"tok-k\">new</span> <span class=\"tok-t\">MenuController</span>({ id: <span class=\"tok-s\">&quot;m&quot;</span>, dataSource: siteMap });\n    <span class=\"tok-k\">await</span> menu.<span class=\"tok-f\">dataBind</span>();\n    <span class=\"tok-k\">this</span>.menuItems = menu.items[<span class=\"tok-n\">0</span>]?.childItems ?? [];\n    <span class=\"tok-k\">this</span>.cdr.<span class=\"tok-f\">markForCheck</span>();\n  }\n  <span class=\"tok-f\">ngOnDestroy</span>(): <span class=\"tok-k\">void</span> { <span class=\"tok-k\">for</span> (<span class=\"tok-k\">const</span> off <span class=\"tok-k\">of</span> <span class=\"tok-k\">this</span>.offs) <span class=\"tok-f\">off</span>(); }\n}</code></pre></div>\n<p>Notes: <code>SiteMapDataSource.select()</code> returns the root node (when <code>showStartingNode</code> is true, the default), so the menu shows <code>menu.items[0].childItems</code>. <code>SiteMapPathController.dataBind(urlOrKey)</code> returns <code>SiteMapPathItem[]</code> (<code>itemType</code>, <code>text</code>, <code>url</code>, <code>isLink</code>); the last (current) item is a link only if <code>renderCurrentNodeAsLink</code> is set. <code>ModalBehavior.handleOk()</code> runs <code>options.onOk</code>, emits <code>ok</code>, then hides.</p>\n","tracking-a-grid-s-state-yourself":"<h3 id=\"82-tracking-a-grids-state-yourself\">8.2 Tracking a grid's state yourself<a class=\"anchor\" href=\"#82-tracking-a-grids-state-yourself\" aria-label=\"Link to this section\">#</a></h3>\n<p>If you need to display derived state (current sort, page count, selected row) next to <code>wf-grid-view</code>, read it from the same controller instance in your host template; since the grid re-renders on <code>stateChanged</code>, subscribe in the host too (<code>controller.stateChanged.subscribe(() =&gt; cdr.markForCheck())</code>) if the host is <code>OnPush</code>.</p>\n","confirm-before-delete":"<h3 id=\"83-confirm-before-delete\">8.3 Confirm-before-delete<a class=\"anchor\" href=\"#83-confirm-before-delete\" aria-label=\"Link to this section\">#</a></h3>\n<p>The built-in Delete button cannot be replaced, but deletion can be gated through the cancellable <code>rowDeleting</code> event. Handlers are awaited, so you can ask a <code>ModalBehavior</code> and resolve when the user answers:</p>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">ts</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-ts\">grid.rowDeleting.<span class=\"tok-f\">subscribe</span>(<span class=\"tok-k\">async</span> (_s, e) =&gt; {\n  <span class=\"tok-k\">const</span> ok = <span class=\"tok-k\">await</span> <span class=\"tok-f\">askUser</span>(<span class=\"tok-s\">`Delete ${e.dataItem.name}?`</span>);   <span class=\"tok-c\">// your own promise-based dialog</span>\n  <span class=\"tok-k\">if</span> (!ok) e.cancel = <span class=\"tok-k\">true</span>;\n});</code></pre></div>\n<p>(<code>askUser</code> is a placeholder for your own function; it is not part of the library, and this snippet is illustrative, not compiled.)</p>\n<hr>\n"},"angular-using-the-headless-core-without-an-adapter":{"overview":"<p>See also <code>react-adapters.md</code> section 3. The core never touches the DOM, so it runs anywhere:</p>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">ts</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-ts\"><span class=\"tok-k\">import</span> { <span class=\"tok-t\">GridViewController</span> } <span class=\"tok-k\">from</span> <span class=\"tok-s\">&quot;@wf-controls/core&quot;</span>;\n\n<span class=\"tok-k\">const</span> grid = <span class=\"tok-k\">new</span> <span class=\"tok-t\">GridViewController</span>&lt;{ id: number; name: string }&gt;({\n  id: <span class=\"tok-s\">&quot;g&quot;</span>, dataKeyField: <span class=\"tok-s\">&quot;id&quot;</span>, allowPaging: <span class=\"tok-k\">true</span>, pageSize: <span class=\"tok-n\">10</span>, allowSorting: <span class=\"tok-k\">true</span>,\n  dataSource: [{ id: <span class=\"tok-n\">1</span>, name: <span class=\"tok-s\">&quot;A&quot;</span> }], columns: [{ <span class=\"tok-k\">type</span>: <span class=\"tok-s\">&quot;bound&quot;</span>, key: <span class=\"tok-s\">&quot;name&quot;</span>, dataField: <span class=\"tok-s\">&quot;name&quot;</span>, headerText: <span class=\"tok-s\">&quot;Name&quot;</span> }]\n});\n<span class=\"tok-k\">await</span> grid.<span class=\"tok-f\">dataBind</span>();\n<span class=\"tok-k\">await</span> grid.<span class=\"tok-f\">executeCommand</span>(<span class=\"tok-n\">0</span>, <span class=\"tok-s\">&quot;Edit&quot;</span>);\n<span class=\"tok-k\">await</span> grid.<span class=\"tok-f\">updateRow</span>(<span class=\"tok-n\">0</span>, { name: <span class=\"tok-s\">&quot;B&quot;</span> });</code></pre></div>\n<hr>\n"},"angular-known-issues-and-inconsistencies-v1-0-0":{"overview":"<ul><li>The template column in <code>wf-grid-view</code> is not customisable (three fixed links: Select, Edit, Delete). <code>docs/v1.0.0/grid-view.md</code> section 4 now documents this and the real <code>#editTemplate</code> slot.</li><li>Without <code>#editTemplate</code>, the Edit link enters edit mode (the row gets class <code>edit</code>) but the cells are unchanged (no editor, no Update/Cancel).</li><li>The kit's nested-table pager selector <code>.pager table</code> and <code>.ajax__tab_hover</code> are not produced, and the kit's &quot;menu + panel&quot; tab variant is not emitted. See <a href=\"#/api/guides/issues-needs-your-attention-first\">Known issues</a>.</li><li>Calendar, Accordion and AdRotator (core-only, no Angular adapter) are not themed; the Validation sheet exists but has no adapter, so you add its classes to your own markup. The Login sheet is drawn by the account components (section 5A). Modal, Repeater, DataList and grid edit rows are themed (section 12).</li><li><code>validation-input-highlight.js</code> needs the ASP.NET <code>WebUIValidation</code> globals; toggle <code>.is-invalid</code> yourself from validator state.</li><li><code>wf-repeater</code> ignores <code>itemCssClass</code>, <code>alternatingItemCssClass</code> and has no header/footer/separator/empty/alternating templates.</li><li><code>wf-grid-view</code> and <code>wf-repeater</code> do not re-subscribe when the <code>controller</code> input is replaced after init (the six newer components do).</li><li><code>wf-menu</code>: a cancel in <code>menuItemClick</code> cannot stop native anchor navigation; nested static levels render as sibling <code>li</code> elements.</li><li><code>wf-tabs</code>: <code>TabsController.setTabs()</code> emits nothing, so call <code>refresh()</code> on the component.</li><li>There is no <code>&lt;wf-data-grid&gt;</code> and no adapter for Accordion, Calendar, the validators, AdRotator or AutoComplete.</li></ul>\n<hr>\n"},"angular-styling-with-wf-controls-styles":{"overview":"<p><code>@wf-controls/styles</code> is a framework-neutral CSS package: five themes (<code>modern</code>, <code>dark</code>, <code>classic</code>, <code>minimal</code>, <code>corporate</code>) for GridView (<code>gv-</code>, plus the <code>gv-&lt;t&gt;-edit.css</code> sheet for edit and insert rows), the Login family (<code>lg-</code>), Menu (<code>mn-</code>), TreeView (<code>tv-</code>), Tabs (<code>tb-</code>), Navigation (<code>nv-</code>: SiteMapPath/Breadcrumb, DataPager, link list), Validation (<code>vl-</code>) and three added families: popup dialog / Modal (<code>md-</code>), Repeater (<code>rp-</code>) and DataList (<code>dl-</code>). It does not cover Calendar, Accordion or AdRotator. The full markup contract is in <code>packages/styles/README.md</code>.</p>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">bash</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-bash\"><span class=\"tok-f\">npm</span> install @wf-controls/styles</code></pre></div>\n<p>In <code>angular.json</code> (theme first, then <code>adapters.css</code>, then your own sheet):</p>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">json</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-json\"><span class=\"tok-k\">&quot;styles&quot;</span>: [\n  <span class=\"tok-s\">&quot;node_modules/@wf-controls/styles/css/bundles/modern-full.css&quot;</span>,\n  <span class=\"tok-s\">&quot;node_modules/@wf-controls/styles/css/adapters.css&quot;</span>,\n  <span class=\"tok-s\">&quot;src/styles.css&quot;</span>\n]</code></pre></div>\n<p>or in <code>src/styles.css</code>:</p>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">css</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-css\">@import &quot;@wf-controls/styles/css/bundles/modern-full.css&quot;;\n@import &quot;@wf-controls/styles/css/adapters.css&quot;;</code></pre></div>\n<p>Then give each component the theme class:</p>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">ts</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-ts\">grid = <span class=\"tok-k\">new</span> <span class=\"tok-t\">GridViewController</span>&lt;<span class=\"tok-t\">Employee</span>&gt;({ id: <span class=\"tok-s\">&quot;g&quot;</span>, dataKeyField: <span class=\"tok-s\">&quot;id&quot;</span>, columns, allowPaging: <span class=\"tok-k\">true</span>, pageSize: <span class=\"tok-n\">5</span>,\n  cssClass: <span class=\"tok-s\">&quot;gv-modern&quot;</span> });                          <span class=\"tok-c\">// table.gv-modern</span></code></pre></div>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">html</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-html\"><span class=\"tok-t\">&lt;wf-grid-view</span><span class=\"tok-k\"> [controller]</span>=<span class=\"tok-s\">&quot;grid&quot;</span> /&gt;\n<span class=\"tok-t\">&lt;wf-menu</span><span class=\"tok-k\"> [controller]</span>=<span class=\"tok-s\">&quot;menu&quot;</span><span class=\"tok-k\"> cssClass</span>=<span class=\"tok-s\">&quot;mn-modern&quot;</span> /&gt;\n<span class=\"tok-t\">&lt;wf-menu</span><span class=\"tok-k\"> [items]</span>=<span class=\"tok-s\">&quot;items&quot;</span><span class=\"tok-k\"> orientation</span>=<span class=\"tok-s\">&quot;vertical&quot;</span><span class=\"tok-k\"> cssClass</span>=<span class=\"tok-s\">&quot;mn-modern&quot;</span> /&gt;   <span class=\"tok-c\">&lt;!-- mn-vertical is added for you --&gt;</span>\n<span class=\"tok-t\">&lt;wf-tree-view</span><span class=\"tok-k\"> [controller]</span>=<span class=\"tok-s\">&quot;tree&quot;</span><span class=\"tok-k\"> cssClass</span>=<span class=\"tok-s\">&quot;tv-modern&quot;</span> /&gt;\n<span class=\"tok-t\">&lt;wf-breadcrumb</span><span class=\"tok-k\"> [controller]</span>=<span class=\"tok-s\">&quot;path&quot;</span><span class=\"tok-k\"> currentUrl</span>=<span class=\"tok-s\">&quot;/staff&quot;</span><span class=\"tok-k\"> cssClass</span>=<span class=\"tok-s\">&quot;nv-modern&quot;</span> /&gt;\n<span class=\"tok-t\">&lt;wf-tabs</span><span class=\"tok-k\"> [controller]</span>=<span class=\"tok-s\">&quot;tabs&quot;</span><span class=\"tok-k\"> cssClass</span>=<span class=\"tok-s\">&quot;tb-modern&quot;</span>&gt; ... <span class=\"tok-t\">&lt;/wf-tabs</span>&gt;\n<span class=\"tok-t\">&lt;wf-repeater</span><span class=\"tok-k\"> [controller]</span>=<span class=\"tok-s\">&quot;rep&quot;</span><span class=\"tok-k\"> cssClass</span>=<span class=\"tok-s\">&quot;rp-modern&quot;</span>&gt; ... <span class=\"tok-t\">&lt;/wf-repeater</span>&gt;\n<span class=\"tok-t\">&lt;wf-data-list</span><span class=\"tok-k\"> [controller]</span>=<span class=\"tok-s\">&quot;list&quot;</span><span class=\"tok-k\"> cssClass</span>=<span class=\"tok-s\">&quot;dl-modern&quot;</span>&gt; ... <span class=\"tok-t\">&lt;/wf-data-list</span>&gt;\n<span class=\"tok-t\">&lt;wf-modal</span><span class=\"tok-k\"> [behavior]</span>=<span class=\"tok-s\">&quot;modal&quot;</span><span class=\"tok-k\"> cssClass</span>=<span class=\"tok-s\">&quot;md-modern&quot;</span><span class=\"tok-k\"> title</span>=<span class=\"tok-s\">&quot;Confirm&quot;</span>&gt; ... <span class=\"tok-t\">&lt;/wf-modal</span>&gt;</code></pre></div>\n<p><strong>Bundles.</strong> <code>&lt;theme&gt;-full.css</code> = the kit's <code>&lt;theme&gt;-all.css</code> (seven families, verbatim) plus <code>md-</code>, <code>rp-</code>, <code>dl-</code> and the grid edit-row sheet. Prefer <code>-full</code>; <code>-all</code> alone leaves the modal, repeater, data list and non-text controls in grid edit rows unstyled.</p>\n<p><strong>Edit templates.</strong> The kit only styles <code>text</code> and <code>date</code> inputs inside <code>tr.edit</code> / <code>tr.footer</code>. <code>gv-&lt;t&gt;-edit.css</code> (part of <code>-full</code>) adds <code>select</code>, <code>textarea</code>, <code>number</code> / <code>email</code> / untyped <code>input</code>, checkbox, label and button, so an <code>#editTemplate</code> using them is themed. The Repeater and DataList edit items are themed by <code>rp-</code> / <code>dl-</code>.</p>\n<p><strong>Switching theme:</strong> load the bundles you want to offer and change the one class on each control root (<code>gv-modern</code> to <code>gv-dark</code>, <code>mn-modern</code> to <code>mn-dark</code>, and so on). Every rule is scoped to its class, so several themes can be loaded at once. Because <code>cssClass</code> is an input (or a controller option for the grid), bind it to a signal or property to switch at runtime.</p>\n<p><strong><code>adapters.css</code></strong> carries no colours or sizes. It resets what the kit did not expect from list and button markup: tree bullets and toggle buttons, tab buttons, absolutely positioned menu flyouts, and the disabled pager link. Load it after the theme.</p>\n","option-to-class-table":"<h3 id=\"option-to-class-table\">Option-to-class table<a class=\"anchor\" href=\"#option-to-class-table\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Controller option / input</th><th>Value for the kit</th><th>What the component does</th></tr></thead><tbody><tr><td>GridView <code>cssClass</code> / <code>tableCssClass</code></td><td><code>gv-&lt;t&gt;</code></td><td>on <code>table</code> (<code>cssClass</code> also on the wrapper <code>div</code>)</td></tr><tr><td><code>rowCssClass</code> / <code>alternatingRowCssClass</code></td><td>none needed; add your own class for zebra</td><td>on <code>tr</code> (alternating on odd page positions)</td></tr><tr><td><code>selectedRowCssClass</code></td><td>none needed</td><td><code>tr.selected</code> + your class; <code>aria-selected=&quot;true&quot;</code></td></tr><tr><td><code>editRowCssClass</code></td><td>none needed</td><td><code>tr.edit</code> + your class; <code>aria-selected=&quot;true&quot;</code> when it is the selected row</td></tr><tr><td><code>headerCssClass</code></td><td>none needed</td><td>on <code>thead</code> and its <code>tr</code></td></tr><tr><td><code>footerCssClass</code></td><td>none needed</td><td><code>tr.footer</code> + your class (needs <code>showFooter</code>)</td></tr><tr><td><code>pagerCssClass</code></td><td>none needed</td><td><code>tr.pager</code> + your class (needs <code>allowPaging</code>)</td></tr><tr><td><code>emptyDataText</code></td><td>--</td><td><code>tr.empty &gt; td.empty</code></td></tr><tr><td><code>wf-menu</code> <code>cssClass</code></td><td><code>mn-&lt;t&gt;</code></td><td>root <code>div[role=navigation]</code>; <code>mn-vertical</code> added for vertical</td></tr><tr><td><code>wf-tree-view</code> <code>cssClass</code></td><td><code>tv-&lt;t&gt;</code></td><td>root <code>div.wf-treeview</code>; labels <code>a.root/parent/leaf(.selected)</code></td></tr><tr><td><code>wf-tabs</code> <code>cssClass</code></td><td><code>tb-&lt;t&gt;</code></td><td>wrapper <code>div.wf-tabs</code>; <code>ajax__tab_*</code> inside</td></tr><tr><td><code>wf-breadcrumb</code> <code>cssClass</code></td><td><code>nv-&lt;t&gt;</code></td><td>inner <code>span</code>; <code>a</code>, <code>span.sep[data-separator]</code>, <code>span.current</code></td></tr><tr><td>Login family, validators</td><td><code>lg-&lt;t&gt;</code>, <code>vl-&lt;t&gt;</code></td><td>no Angular adapter; add the class to your own markup</td></tr><tr><td><code>wf-repeater</code> <code>cssClass</code> input / controller <code>cssClass</code></td><td><code>rp-&lt;t&gt;</code></td><td>root <code>div.wf-repeater</code>; items <code>div.wf-item</code> (+ <code>alt</code>, <code>active</code>, <code>edit</code>), <code>button.add</code>, <code>header.wf-item-header</code>, <code>div.empty</code></td></tr><tr><td><code>wf-data-list</code> <code>cssClass</code></td><td><code>dl-&lt;t&gt;</code></td><td>Flow <code>div.wf-datalist</code>, items <code>div.datalist-item</code> (+ <code>alt</code> / <code>selected</code> / <code>edit</code>); Table <code>table.datalist-table.wf-datalist</code>, cells <code>td.datalist-cell</code>; <code>p.empty</code></td></tr><tr><td><code>itemCssClass</code>, <code>alternatingItemCssClass</code> (Repeater)</td><td>none needed</td><td>appended to the item next to the adapter's own classes</td></tr><tr><td><code>wf-modal</code> <code>cssClass</code></td><td><code>md-&lt;t&gt;</code></td><td>on the overlay <code>div.modal</code>; backdrop colour via <code>--wf-backdrop</code></td></tr><tr><td>Calendar, Accordion, AdRotator</td><td>not covered</td><td>style yourself</td></tr></tbody></table></div>\n<p>Validation highlighting: the kit styles <code>.is-invalid</code> inputs, but its <code>validation-input-highlight.js</code> only works with the ASP.NET <code>WebUIValidation</code> globals. In Angular bind <code>[class.is-invalid]=&quot;invalid&quot;</code> from the validator state yourself.</p>"}};
export default area;
